);

const BackBtn = () => (
  <div
    style={{
      width: 36,
      height: 36,
      borderRadius: 10,
      border: `1.5px solid ${colors.primary}`,
      display: "flex",
      alignItems: "center",
      justifyContent: "center",
      color: colors.primary,
      fontSize: 16,
      fontWeight: 700,
      cursor: "pointer",
    }}
  >
    &#8249;
  </div>
);

const TealBtn = ({ children, outline, danger, small }) => (
  <div
    style={{
      background: danger ? "transparent" : outline ? "transparent" : `linear-gradient(135deg, ${colors.primary}, #00B4D8)`,
      border: danger ? `1.5px solid ${colors.error}` : outline ? `1.5px solid ${colors.primary}` : "none",
      color: danger ? colors.error : colors.text,
      borderRadius: 12,
      padding: small ? "8px 16px" : "14px 20px",
      textAlign: "center",
      fontWeight: 700,
      fontSize: small ? 12 : 14,
      cursor: "pointer",
      width: "100%",
    }}
  >
    {children}
  </div>
);

const InputField = ({ label, placeholder, secure, icon }) => (
  <div style={{ marginBottom: 14 }}>
    <div style={{ color: colors.textSec, fontSize: 11, marginBottom: 4 }}>{label}</div>
    <div
      style={{
        background: colors.bgInput,
        border: `1px solid ${colors.border}`,
        borderRadius: 12,
        padding: "12px 14px",
        display: "flex",
        justifyContent: "space-between",
        alignItems: "center",
      }}
    >
      <span style={{ color: colors.textMuted, fontSize: 13 }}>{secure ? "••••••••" : placeholder}</span>
      {icon && <span style={{ color: colors.textMuted, fontSize: 14 }}>{icon}</span>}
    </div>
  </div>
);

const Badge = ({ status }) => {
  const map = {
    on_track: { bg: "rgba(0,217,152,0.15)", color: colors.primary, text: "On Track" },
    behind: { bg: "rgba(255,71,87,0.15)", color: colors.error, text: "Behind" },
    completed: { bg: "rgba(0,217,152,0.15)", color: colors.primary, text: "Completed" },
    current: { bg: "rgba(255,193,7,0.15)", color: colors.warning, text: "Current" },
    upcoming: { bg: "rgba(100,116,139,0.15)", color: colors.textMuted, text: "Upcoming" },
  };
  const s = map[status] || map.on_track;
  return (
    <span
      style={{
        background: s.bg,
        color: s.color,
        fontSize: 9,
        fontWeight: 700,
        padding: "3px 8px",
        borderRadius: 10,
      }}
    >
      {s.text}
    </span>
  );
};

const ProgressBar = ({ progress, color }) => (
  <div style={{ height: 5, background: colors.border, borderRadius: 3, marginTop: 6, width: "100%" }}>
    <div
      style={{
        height: "100%",
        width: `${Math.min(progress, 100)}%`,
        background: color || colors.primary,
        borderRadius: 3,
      }}
    />
  </div>
);

