      {/* Status bar */}
      <div
        style={{
          height: 44,
          background: COLORS.navy,
          display: "flex",
          alignItems: "center",
          justifyContent: "space-between",
          padding: "0 20px",
        }}
      >
        <span style={{ color: COLORS.white, fontSize: 12, fontWeight: 600 }}>
          9:41
        </span>
        <div style={{ display: "flex", gap: 4 }}>
          <div
            style={{
              width: 16,
              height: 10,
              border: `1px solid ${COLORS.white}`,
              borderRadius: 2,
              position: "relative",
