      { id: "insights", icon: "📊", label: "Insights" },
      { id: "profile", icon: "👤", label: "Profile" },
    ].map((item) =>
      item.isAdd ? (
        <div
          key={item.id}
          style={{
            width: 44,
            height: 44,
            borderRadius: 22,
            background: COLORS.teal,
            display: "flex",
            alignItems: "center",
            justifyContent: "center",
