{
  "expo": {
    "name": "Fractional Bill Pay",
    "slug": "fractional-bill-pay",
    "version": "1.0.0",
    "orientation": "portrait",
    "scheme": "fractionalbillpay",
    "icon": "./assets/icon.png",
    "splash": {
      "image": "./assets/splash.png",
      "resizeMode": "contain",
      "backgroundColor": "#0A1628"
    },
    "ios": {
      "supportsTablet": false,
      "bundleIdentifier": "com.fractionalbillpay.app",
      "config": {
        "usesNonExemptEncryption": false
      }
    },
    "android": {
      "adaptiveIcon": {
        "foregroundImage": "./assets/adaptive-icon.png",
        "backgroundColor": "#0A1628"
      },
      "package": "com.fractionalbillpay.app"
    },
    "plugins": [
      "expo-secure-store",
      "expo-font"
    ]
  }
}

module.exports = function (api) {
  api.cache(true);
  return {
    presets: ["babel-preset-expo"],
    plugins: [
      [
        "module-resolver",
        {
          alias: {
            "@": "./src",
          },
        },
      ],
    ],
  };
};

// User Types
export interface User {
  id: string;
  email: string;
  full_name: string;
  avatar_url?: string;
  created_at: string;
  updated_at: string;
}

// Bill Types
export interface Bill {
  id: string;
  user_id: string;
  name: string;
  description?: string;
  amount: number;
  due_date: number; // day of month (1-31)
  category: BillCategory;
  is_active: boolean;
  created_at: string;
  updated_at: string;
}

export type BillCategory =
  | 'utilities'
  | 'subscription'
  | 'insurance'
  | 'housing'
  | 'transportation'
  | 'healthcare'
  | 'entertainment'
  | 'education'
  | 'other';

// Micro-contribution Types
export interface MicroContribution {
  id: string;
  bill_id: string;
  user_id: string;
  amount: number;
  due_date: string; // ISO date
  is_paid: boolean;
  paid_at?: string;
  payment_method_id?: string;
  created_at: string;
  updated_at: string;
}

// Payment Method Types
export interface PaymentMethod {
  id: string;
  user_id: string;
  type: PaymentMethodType;
  name: string;
  is_default: boolean;
  is_active: boolean;
  metadata: Record<string, any>;
  created_at: string;
  updated_at: string;
}

export type PaymentMethodType = 'bank_account' | 'card' | 'paypal' | 'wallet';

// Funding Source Types
export interface FundingSource {
  id: string;
  user_id: string;
  plaid_account_id: string;
  name: string;
  account_type: string;
  is_default: boolean;
  is_active: boolean;
  created_at: string;
  updated_at: string;
}

// Auth Types
export interface AuthSession {
  user: User | null;
  isLoading: boolean;
  isSignedIn: boolean;
}

// Navigation Types
export type RootStackParamList = {
  Auth: undefined;
  MainApp: undefined;
  Splash: undefined;
};

export type AuthStackParamList = {
  SignIn: undefined;
  SignUp: undefined;
  ForgotPassword: undefined;
  VerifyEmail: { email: string };
};

export type MainAppParamList = {
  HomeTabs: undefined;
};

export type HomeTabs = {
  Home: undefined;
  Bills: undefined;
  Insights: undefined;
  Profile: undefined;
};

// API Response Types
export interface ApiResponse<T> {
  success: boolean;
  data?: T;
  error?: string;
  message?: string;
}

// Transaction Types
export interface Transaction {
  id: string;
  user_id: string;
  micro_contribution_id: string;
  amount: number;
  status: TransactionStatus;
  payment_method_id: string;
  reference_id?: string;
  error_message?: string;
  created_at: string;
  updated_at: string;
}

export type TransactionStatus = 'pending' | 'completed' | 'failed' | 'cancelled';

// Statistics Types
export interface BillStats {
  total_bills: number;
  total_amount: number;
  paid_this_month: number;
  pending_this_month: number;
  due_soon_count: number;
}

export interface UserStats {
  bills: BillStats;
  contribution_streak: number;
  on_time_rate: number;
}

