import { createClient } from '@supabase/supabase-js';

const supabaseUrl = process.env.EXPO_PUBLIC_SUPABASE_URL || '';
const supabaseAnonKey = process.env.EXPO_PUBLIC_SUPABASE_ANON_KEY || '';

if (!supabaseUrl || !supabaseAnonKey) {
  throw new Error('Missing Supabase credentials in environment variables');
}

export const supabase = createClient(supabaseUrl, supabaseAnonKey);

// Auth service
export const authService = {
  async signUp(email: string, password: string, fullName: string) {
    const { data, error } = await supabase.auth.signUp({
      email,
      password,
      options: {
        data: {
          full_name: fullName,
        },
      },
    });

    if (error) throw error;
    return data;
  },

  async signIn(email: string, password: string) {
    const { data, error } = await supabase.auth.signInWithPassword({
      email,
      password,
    });

    if (error) throw error;
    return data;
  },

  async signOut() {
    const { error } = await supabase.auth.signOut();
    if (error) throw error;
  },

  async getCurrentUser() {
    const {
      data: { user },
      error,
    } = await supabase.auth.getUser();

    if (error) throw error;
    return user;
  },

  async resetPassword(email: string) {
    const { error } = await supabase.auth.resetPasswordForEmail(email);
    if (error) throw error;
  },

  async updatePassword(newPassword: string) {
    const { error } = await supabase.auth.updateUser({
      password: newPassword,
    });

    if (error) throw error;
  },

  onAuthStateChange(callback: (event: string, session: any) => void) {
    return supabase.auth.onAuthStateChange(callback);
  },
};

// User profile service
export const userService = {
  async getProfile(userId: string) {
    const { data, error } = await supabase
      .from('users')
      .select('*')
      .eq('id', userId)
      .single();

    if (error) throw error;
    return data;
  },

  async updateProfile(userId: string, updates: Record<string, any>) {
    const { data, error } = await supabase
      .from('users')
      .update(updates)
      .eq('id', userId)
      .select()
      .single();

    if (error) throw error;
    return data;
  },

  async uploadAvatar(userId: string, file: Blob) {
    const fileName = `${userId}-${Date.now()}.jpg`;
    const { error } = await supabase.storage
      .from('avatars')
      .upload(fileName, file, { upsert: true });

    if (error) throw error;
    return fileName;
  },
};

// Bills service
export const billService = {
  async createBill(userId: string, billData: Record<string, any>) {
    const { data, error } = await supabase
      .from('bills')
      .insert({ ...billData, user_id: userId })
      .select()
      .single();

    if (error) throw error;
    return data;
  },

  async getBills(userId: string) {
    const { data, error } = await supabase
      .from('bills')
      .select('*')
      .eq('user_id', userId)
      .eq('is_active', true)
      .order('due_date', { ascending: true });

    if (error) throw error;
    return data;
  },

  async updateBill(billId: string, updates: Record<string, any>) {
    const { data, error } = await supabase
      .from('bills')
      .update(updates)
      .eq('id', billId)
      .select()
      .single();

    if (error) throw error;
    return data;
  },

  async deleteBill(billId: string) {
    const { error } = await supabase
      .from('bills')
      .update({ is_active: false })
      .eq('id', billId);

    if (error) throw error;
  },
};

// Micro-contributions service
export const contributionService = {
  async getContributions(userId: string) {
    const { data, error } = await supabase
      .from('micro_contributions')
      .select('*')
      .eq('user_id', userId)
      .order('due_date', { ascending: true });

    if (error) throw error;
    return data;
  },

  async getContributionsByBill(billId: string) {
    const { data, error } = await supabase
      .from('micro_contributions')
      .select('*')
      .eq('bill_id', billId)
      .order('due_date', { ascending: true });

    if (error) throw error;
    return data;
  },

  async createContribution(contributionData: Record<string, any>) {
    const { data, error } = await supabase
      .from('micro_contributions')
      .insert(contributionData)
      .select()
      .single();

    if (error) throw error;
    return data;
  },

  async markAsPaid(contributionId: string, paymentMethodId: string) {
    const { data, error } = await supabase
      .from('micro_contributions')
      .update({
        is_paid: true,
        paid_at: new Date().toISOString(),
        payment_method_id: paymentMethodId,
      })
      .eq('id', contributionId)
      .select()
      .single();

    if (error) throw error;
    return data;
  },
};

// Payment methods service
export const paymentMethodService = {
  async getPaymentMethods(userId: string) {
    const { data, error } = await supabase
      .from('payment_methods')
      .select('*')
      .eq('user_id', userId)
      .eq('is_active', true);

    if (error) throw error;
    return data;
  },

  async addPaymentMethod(userId: string, methodData: Record<string, any>) {
    const { data, error } = await supabase
      .from('payment_methods')
      .insert({ ...methodData, user_id: userId })
      .select()
      .single();

    if (error) throw error;
    return data;
  },

  async removePaymentMethod(paymentMethodId: string) {
    const { error } = await supabase
      .from('payment_methods')
      .update({ is_active: false })
      .eq('id', paymentMethodId);

    if (error) throw error;
  },

  async setDefaultPaymentMethod(userId: string, paymentMethodId: string) {
    const { error: resetError } = await supabase
      .from('payment_methods')
      .update({ is_default: false })
      .eq('user_id', userId);

    if (resetError) throw resetError;

    const { error } = await supabase
      .from('payment_methods')
      .update({ is_default: true })
      .eq('id', paymentMethodId);

    if (error) throw error;
  },
};

