import { create } from 'zustand';
import { Bill, MicroContribution } from '@/types';
import {
  billService,
  contributionService,
} from '@/services/supabase';

interface BillStore {
  bills: Bill[];
  contributions: MicroContribution[];
  isLoading: boolean;
  error: string | null;

  // Bill actions
  fetchBills: (userId: string) => Promise<void>;
  addBill: (userId: string, bill: Omit<Bill, 'id' | 'created_at' | 'updated_at'>) => Promise<void>;
  updateBill: (billId: string, updates: Partial<Bill>) => Promise<void>;
  removeBill: (billId: string) => Promise<void>;

  // Contribution actions
  fetchContributions: (userId: string) => Promise<void>;
  fetchContributionsByBill: (billId: string) => Promise<void>;
  markContributionAsPaid: (contributionId: string, paymentMethodId: string) => Promise<void>;

  // Utilities
  setBills: (bills: Bill[]) => void;
  setContributions: (contributions: MicroContribution[]) => void;
  setLoading: (loading: boolean) => void;
  setError: (error: string | null) => void;
}

export const useBillStore = create<BillStore>((set) => ({
  bills: [],
  contributions: [],
  isLoading: false,
  error: null,

  setBills: (bills) => set({ bills }),
  setContributions: (contributions) => set({ contributions }),
  setLoading: (isLoading) => set({ isLoading }),
  setError: (error) => set({ error }),

  fetchBills: async (userId) => {
    try {
      set({ isLoading: true, error: null });
      const bills = await billService.getBills(userId);
      set({ bills });
    } catch (error) {
      const errorMessage = error instanceof Error ? error.message : 'Failed to fetch bills';
      set({ error: errorMessage });
      console.error('Fetch bills error:', error);
    } finally {
      set({ isLoading: false });
    }
  },

  addBill: async (userId, billData) => {
    try {
      set({ isLoading: true, error: null });
      const newBill = await billService.createBill(userId, {
        ...billData,
        is_active: true,
      });
      set((state) => ({ bills: [...state.bills, newBill] }));
    } catch (error) {
      const errorMessage = error instanceof Error ? error.message : 'Failed to add bill';
      set({ error: errorMessage });
      console.error('Add bill error:', error);
      throw error;
    } finally {
      set({ isLoading: false });
    }
  },

  updateBill: async (billId, updates) => {
    try {
      set({ isLoading: true, error: null });
      const updatedBill = await billService.updateBill(billId, updates);
      set((state) => ({
        bills: state.bills.map((b) => (b.id === billId ? updatedBill : b)),
      }));
    } catch (error) {
      const errorMessage = error instanceof Error ? error.message : 'Failed to update bill';
      set({ error: errorMessage });
      console.error('Update bill error:', error);
      throw error;
    } finally {
      set({ isLoading: false });
    }
  },

  removeBill: async (billId) => {
    try {
      set({ isLoading: true, error: null });
      await billService.deleteBill(billId);
      set((state) => ({
        bills: state.bills.filter((b) => b.id !== billId),
      }));
    } catch (error) {
      const errorMessage = error instanceof Error ? error.message : 'Failed to remove bill';
      set({ error: errorMessage });
      console.error('Remove bill error:', error);
      throw error;
    } finally {
      set({ isLoading: false });
    }
  },

  fetchContributions: async (userId) => {
    try {
      set({ isLoading: true, error: null });
      const contributions = await contributionService.getContributions(userId);
      set({ contributions });
    } catch (error) {
      const errorMessage = error instanceof Error ? error.message : 'Failed to fetch contributions';
      set({ error: errorMessage });
      console.error('Fetch contributions error:', error);
    } finally {
      set({ isLoading: false });
    }
  },

  fetchContributionsByBill: async (billId) => {
    try {
      set({ isLoading: true, error: null });
      const contributions = await contributionService.getContributionsByBill(billId);
      set({ contributions });
    } catch (error) {
      const errorMessage = error instanceof Error ? error.message : 'Failed to fetch bill contributions';
      set({ error: errorMessage });
      console.error('Fetch contributions error:', error);
    } finally {
      set({ isLoading: false });
    }
  },

  markContributionAsPaid: async (contributionId, paymentMethodId) => {
    try {
      set({ isLoading: true, error: null });
      const paidContribution = await contributionService.markAsPaid(
        contributionId,
        paymentMethodId
      );
      set((state) => ({
        contributions: state.contributions.map((c) =>
          c.id === contributionId ? paidContribution : c
        ),
      }));
    } catch (error) {
      const errorMessage = error instanceof Error ? error.message : 'Failed to mark contribution as paid';
      set({ error: errorMessage });
      console.error('Mark contribution error:', error);
      throw error;
    } finally {
      set({ isLoading: false });
    }
  },
}));

