          onChangeText={setFullName}
          editable={!isLoading}
          style={{
            backgroundColor: colors.bgInput,
            color: colors.text,
            padding: spacing.md,
            borderRadius: 8,
            marginBottom: spacing.lg,
            fontSize: 16,
          }}
        />

        <TextInput
          placeholder="Email"
          placeholderTextColor={colors.textMuted}
          value={email}
          onChangeText={setEmail}
          keyboardType="email-address"
          editable={!isLoading}
          style={{
            backgroundColor: colors.bgInput,
            color: colors.text,
            padding: spacing.md,
            borderRadius: 8,
            marginBottom: spacing.lg,
            fontSize: 16,
          }}
        />

        <TextInput
          placeholder="Password"
          placeholderTextColor={colors.textMuted}
          value={password}
          onChangeText={setPassword}
          secureTextEntry
          editable={!isLoading}
          style={{
            backgroundColor: colors.bgInput,
            color: colors.text,
            padding: spacing.md,
            borderRadius: 8,
            marginBottom: spacing.lg,
            fontSize: 16,
          }}
        />

        <TextInput
          placeholder="Confirm Password"
          placeholderTextColor={colors.textMuted}
          value={confirmPassword}
          onChangeText={setConfirmPassword}
          secureTextEntry
          editable={!isLoading}
          style={{
            backgroundColor: colors.bgInput,
            color: colors.text,
            padding: spacing.md,
            borderRadius: 8,
            marginBottom: spacing.lg,
            fontSize: 16,
          }}
        />

        {error ? (
          <Text style={{ color: colors.error, marginBottom: spacing.md, ...typography.body }}>
            {error}
          </Text>
        ) : null}

        <TouchableOpacity
          onPress={handleSignUp}
          disabled={isLoading}
          style={{
            backgroundColor: colors.primary,
            padding: spacing.md,
            borderRadius: 8,
            alignItems: 'center',
            marginBottom: spacing.lg,
            opacity: isLoading ? 0.6 : 1,
