import { serve } from "https://deno.land/std@0.168.0/http/server.ts";
import { corsHeaders, handleCors } from "../_shared/cors.ts";
import { verifyAuth, createSupabaseClient } from "../_shared/supabase.ts";

const PLAID_CLIENT_ID = Deno.env.get("PLAID_CLIENT_ID") || "";
const PLAID_SECRET = Deno.env.get("PLAID_SECRET") || "";
const PLAID_ENV = Deno.env.get("PLAID_ENV") || "sandbox";
const SUPABASE_URL = Deno.env.get("SUPABASE_URL") || "";
const SUPABASE_ANON_KEY = Deno.env.get("SUPABASE_ANON_KEY") || "";
const SUPABASE_SERVICE_KEY = Deno.env.get("SUPABASE_SERVICE_ROLE_KEY") || "";

serve(async (req: Request) => {
  const corsResponse = handleCors(req);
  if (corsResponse) return corsResponse;

  try {
    const { user, client: userClient } = await verifyAuth(
      SUPABASE_URL,
      SUPABASE_ANON_KEY,
      req
    );

    const { public_token } = await req.json();

    if (!public_token) {
      return new Response(JSON.stringify({ error: "Missing public_token" }), {
        status: 400,
        headers: { ...corsHeaders, "Content-Type": "application/json" },
      });
    }

    const plaidApiUrl =
      PLAID_ENV === "production"
        ? "https://production.plaid.com"
        : "https://sandbox.plaid.com";

    const exchangeResponse = await fetch(
      `${plaidApiUrl}/item/public_token/exchange`,
      {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          client_id: PLAID_CLIENT_ID,
          secret: PLAID_SECRET,
          public_token,
        }),
      }
    );

    const exchangeData = await exchangeResponse.json();

    if (!exchangeResponse.ok) {
      console.error("Plaid exchange error:", exchangeData);
      return new Response(
        JSON.stringify({
          error: exchangeData.error_message || "Failed to exchange token",
        }),
        {
          status: exchangeResponse.status,
          headers: { ...corsHeaders, "Content-Type": "application/json" },
        }
      );
    }

    const { access_token, item_id } = exchangeData;

    // Get account info from Plaid
    const accountResponse = await fetch(`${plaidApiUrl}/accounts/get`, {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({
        client_id: PLAID_CLIENT_ID,
        secret: PLAID_SECRET,
        access_token,
      }),
    });

    const accountData = await accountResponse.json();

    if (!accountResponse.ok) {
      console.error("Plaid accounts error:", accountData);
      return new Response(
        JSON.stringify({
          error: accountData.error_message || "Failed to fetch accounts",
        }),
        {
          status: accountResponse.status,
          headers: { ...corsHeaders, "Content-Type": "application/json" },
        }
      );
    }

    const { accounts, item } = accountData;
    const primaryAccount = accounts[0];

    // Store in database using service role
    const serviceClient = createSupabaseClient(
      SUPABASE_URL,
      SUPABASE_SERVICE_KEY
    );

    const { error: insertError } = await serviceClient
      .from("linked_accounts")
      .insert({
        user_id: user.id,
        plaid_item_id: item_id,
        plaid_access_token: access_token,
        institution_name: item.institution?.name || "Unknown",
        institution_id: item.institution?.institution_id || "",
        account_name: primaryAccount.name,
        account_mask: primaryAccount.mask,
        account_type: primaryAccount.subtype || "checking",
        is_primary: true,
      });

    if (insertError) {
      console.error("Database insert error:", insertError);
      return new Response(
        JSON.stringify({ error: "Failed to save linked account" }),
        {
          status: 500,
          headers: { ...corsHeaders, "Content-Type": "application/json" },
        }
      );
    }

    return new Response(
      JSON.stringify({
        success: true,
        message: `Connected ${item.institution?.name || "account"} successfully`,
      }),
      {
        headers: { ...corsHeaders, "Content-Type": "application/json" },
      }
    );
  } catch (error) {
    console.error("Error:", error);
    return new Response(
      JSON.stringify({ error: error.message || "Internal server error" }),
      {
        status: 401,
        headers: { ...corsHeaders, "Content-Type": "application/json" },
      }
    );
  }
});

import React, { useEffect } from 'react';
import {
  View,
  Text,
  ScrollView,
  TouchableOpacity,
  ActivityIndicator,
} from 'react-native';
import { useSafeAreaInsets } from 'react-native-safe-area-context';
import { MaterialIcons } from '@expo/vector-icons';
import { useAuthStore } from '@/store/authStore';
import { useBillStore } from '@/store/billStore';
import { colors, typography, spacing } from '@/theme';

export default function HomeScreen() {
  const insets = useSafeAreaInsets();
  const { user } = useAuthStore();
  const { bills, contributions, isLoading, fetchBills, fetchContributions } = useBillStore();

  useEffect(() => {
    if (user?.id) {
      fetchBills(user.id);
      fetchContributions(user.id);
    }
  }, [user?.id]);

  const totalDue = bills.reduce((sum, bill) => sum + bill.amount, 0);
  const paidContributions = contributions.filter((c) => c.is_paid).length;
  const totalContributions = contributions.length;

  return (
    <View
      style={{
        flex: 1,
        backgroundColor: colors.bg,
        paddingTop: insets.top,
      }}
    >
      <ScrollView
        contentContainerStyle={{
          paddingHorizontal: spacing.lg,
          paddingBottom: spacing['3xl'],
        }}
        showsVerticalScrollIndicator={false}
      >
        {/* Header */}
        <View style={{ marginTop: spacing.lg, marginBottom: spacing['2xl'] }}>
          <Text style={{ ...typography.h2, color: colors.text }}>
            Welcome back!
          </Text>
          <Text style={{ ...typography.body, color: colors.textSecondary, marginTop: spacing.sm }}>
            {user?.full_name}
          </Text>
        </View>

        {/* Summary Cards */}
        {isLoading ? (
          <View style={{ alignItems: 'center', marginVertical: spacing['3xl'] }}>
            <ActivityIndicator size="large" color={colors.primary} />
          </View>
        ) : (
          <>
            {/* Total Due Card */}
            <View
              style={{
                backgroundColor: colors.bgCard,
                borderRadius: 12,
                padding: spacing.lg,
                marginBottom: spacing.lg,
                borderLeftWidth: 4,
                borderLeftColor: colors.primary,
              }}
            >
              <View style={{ flexDirection: 'row', justifyContent: 'space-between', alignItems: 'center' }}>
                <View style={{ flex: 1 }}>
                  <Text style={{ ...typography.bodySmall, color: colors.textSecondary, marginBottom: spacing.sm }}>
                    Total Monthly Bills
                  </Text>
                  <Text style={{ ...typography.h3, color: colors.text }}>
                    ${totalDue.toFixed(2)}
                  </Text>
                </View>
                <MaterialIcons name="receipt-long" size={32} color={colors.primary} />
              </View>
            </View>

            {/* Progress Card */}
            <View
              style={{
                backgroundColor: colors.bgCard,
                borderRadius: 12,
                padding: spacing.lg,
                marginBottom: spacing.lg,
                borderLeftWidth: 4,
                borderLeftColor: colors.success,
              }}
            >
              <View style={{ flexDirection: 'row', justifyContent: 'space-between', alignItems: 'center' }}>
                <View style={{ flex: 1 }}>
                  <Text style={{ ...typography.bodySmall, color: colors.textSecondary, marginBottom: spacing.sm }}>
                    Contributions Progress
                  </Text>
                  <Text style={{ ...typography.h3, color: colors.text }}>
                    {paidContributions} / {totalContributions}
                  </Text>
                  <View
                    style={{
                      width: '100%',
                      height: 6,
                      backgroundColor: colors.border,
                      borderRadius: 3,
                      marginTop: spacing.md,
                      overflow: 'hidden',
                    }}
                  >
                    <View
                      style={{
                        width: totalContributions > 0 ? `${(paidContributions / totalContributions) * 100}%` : '0%',
                        height: '100%',
                        backgroundColor: colors.success,
                      }}
                    />
                  </View>
                </View>
              </View>
            </View>

            {/* Upcoming Bills */}
            {bills.length > 0 ? (
              <View>
                <Text style={{ ...typography.h4, color: colors.text, marginBottom: spacing.lg }}>
                  Upcoming Bills
                </Text>
                {bills.slice(0, 3).map((bill) => (
                  <View
                    key={bill.id}
                    style={{
                      backgroundColor: colors.bgCard,
                      borderRadius: 12,
                      padding: spacing.md,
                      marginBottom: spacing.md,
                      flexDirection: 'row',
                      justifyContent: 'space-between',
                      alignItems: 'center',
