                ))}
              </View>
            ) : (
              <View style={{ alignItems: 'center', marginVertical: spacing['3xl'] }}>
                <Text style={{ ...typography.body, color: colors.textSecondary }}>
                  No bills yet. Add one to get started!
                </Text>
              </View>
            )}
          </>
        )}
      </ScrollView>
    </View>
  );
}

