import { serve } from "https://deno.land/std@0.168.0/http/server.ts";
import { corsHeaders, handleCors } from "../_shared/cors.ts";
import { verifyAuth, createSupabaseClient } from "../_shared/supabase.ts";

const PLAID_CLIENT_ID = Deno.env.get("PLAID_CLIENT_ID") || "";
const PLAID_SECRET = Deno.env.get("PLAID_SECRET") || "";
const PLAID_ENV = Deno.env.get("PLAID_ENV") || "sandbox";
const SUPABASE_URL = Deno.env.get("SUPABASE_URL") || "";
const SUPABASE_ANON_KEY = Deno.env.get("SUPABASE_ANON_KEY") || "";
const SUPABASE_SERVICE_KEY = Deno.env.get("SUPABASE_SERVICE_ROLE_KEY") || "";

interface Transaction {
  date: string;
  amount: number;
  merchant_name?: string;
  name: string;
  [key: string]: unknown;
}

interface GroupedTransaction {
  merchant: string;
  amounts: number[];
  dates: Date[];
  category?: string;
}

function detectFrequency(dayGaps: number[]): string {
  if (dayGaps.length === 0) return "unknown";

  const avgGap = dayGaps.reduce((a, b) => a + b, 0) / dayGaps.length;

  // Monthly: 25-35 days
  if (avgGap >= 25 && avgGap <= 35) return "monthly";
  // Biweekly: 12-16 days
  if (avgGap >= 12 && avgGap <= 16) return "biweekly";
  // Weekly: 5-9 days
  if (avgGap >= 5 && avgGap <= 9) return "weekly";

  return "unknown";
}

function calculateConfidence(
  count: number,
  amountVariance: number,
  frequency: string
): number {
  let confidence = 0.5;

  // More occurrences = higher confidence
  if (count >= 5) confidence += 0.3;
  else if (count >= 3) confidence += 0.2;
  else if (count >= 2) confidence += 0.1;

  // Lower variance = higher confidence
  if (amountVariance < 0.05) confidence += 0.15;
  else if (amountVariance < 0.1) confidence += 0.1;
  else if (amountVariance < 0.2) confidence += 0.05;

  // Known frequency = higher confidence
  if (frequency !== "unknown") confidence += 0.1;

  return Math.min(1.0, confidence);
}

serve(async (req: Request) => {
  const corsResponse = handleCors(req);
  if (corsResponse) return corsResponse;

  try {
    const { user } = await verifyAuth(SUPABASE_URL, SUPABASE_ANON_KEY, req);

    // Get linked accounts
    const serviceClient = createSupabaseClient(
      SUPABASE_URL,
      SUPABASE_SERVICE_KEY
    );

    const { data: linkedAccounts, error: accountsError } = await serviceClient
      .from("linked_accounts")
      .select("*")
      .eq("user_id", user.id);

    if (accountsError) {
      throw new Error(`Failed to fetch linked accounts: ${accountsError.message}`);
    }

    if (!linkedAccounts || linkedAccounts.length === 0) {
      return new Response(
        JSON.stringify({ error: "No linked accounts found" }),
        {
          status: 404,
          headers: { ...corsHeaders, "Content-Type": "application/json" },
        }
      );
    }

    const plaidApiUrl =
      PLAID_ENV === "production"
        ? "https://production.plaid.com"
        : "https://sandbox.plaid.com";

    const detectedBills = [];

    // Process each linked account
    for (const account of linkedAccounts) {
      try {
        // Fetch transactions from Plaid
        const transResponse = await fetch(`${plaidApiUrl}/transactions/get`, {
          method: "POST",
          headers: { "Content-Type": "application/json" },
          body: JSON.stringify({
            client_id: PLAID_CLIENT_ID,
            secret: PLAID_SECRET,
            access_token: account.plaid_access_token,
            start_date: new Date(Date.now() - 90 * 24 * 60 * 60 * 1000)
              .toISOString()
              .split("T")[0],
            end_date: new Date().toISOString().split("T")[0],
            options: {
              include_personal_finance_category: true,
            },
          }),
        });

        const transData = await transResponse.json();

        if (!transResponse.ok) {
          console.error(`Plaid transactions error for account:`, transData);
          continue;
        }

        const transactions: Transaction[] = transData.transactions || [];

        // Group transactions by merchant
        const grouped: { [key: string]: GroupedTransaction } = {};

        for (const trans of transactions) {
          const merchant =
            trans.merchant_name || trans.name || "Unknown Merchant";
          const amount = Math.abs(trans.amount);

          if (!grouped[merchant]) {
            grouped[merchant] = {
              merchant,
              amounts: [],
              dates: [],
              category: trans.personal_finance_category?.[0] || "other",
            };
          }

          grouped[merchant].amounts.push(amount);
          grouped[merchant].dates.push(new Date(trans.date));
        }

        // Analyze grouped transactions
        for (const [merchant, data] of Object.entries(grouped)) {
          // Need at least 2 occurrences to be a subscription
          if (data.amounts.length < 2) continue;

          const amounts = data.amounts.sort((a, b) => a - b);
          const avgAmount =
            amounts.reduce((a, b) => a + b, 0) / amounts.length;
          const maxAmount = amounts[amounts.length - 1];
          const amountVariance = (maxAmount - amounts[0]) / avgAmount;

          // Check 10% variance threshold
          if (amountVariance > 0.1 && amounts.length < 5) continue;

          const sortedDates = data.dates.sort(
            (a, b) => a.getTime() - b.getTime()
          );
          const dayGaps = [];

          for (let i = 1; i < sortedDates.length; i++) {
            const gap =
              (sortedDates[i].getTime() - sortedDates[i - 1].getTime()) /
              (1000 * 60 * 60 * 24);
            dayGaps.push(gap);
          }

          const frequency = detectFrequency(dayGaps);
          const confidence = calculateConfidence(
            data.amounts.length,
            amountVariance,
            frequency
          );

          detectedBills.push({
            user_id: user.id,
            linked_account_id: account.id,
            merchant_name: merchant,
            amount: avgAmount,
            frequency,
            category: data.category,
            confidence,
            last_charge_date: sortedDates[sortedDates.length - 1]
              .toISOString()
              .split("T")[0],
          });
        }
      } catch (error) {
        console.error(`Error processing account ${account.id}:`, error);
      }
    }

    // Save detected bills to database
    if (detectedBills.length > 0) {
      const { error: insertError } = await serviceClient
        .from("detected_bills")
        .insert(detectedBills);

      if (insertError) {
        console.error("Database insert error:", insertError);
      }
    }

    return new Response(
      JSON.stringify({
        success: true,
        detected: detectedBills.length,
        bills: detectedBills,
      }),
      {
        headers: { ...corsHeaders, "Content-Type": "application/json" },
      }
    );
  } catch (error) {
    console.error("Error:", error);
    return new Response(
      JSON.stringify({ error: error.message || "Internal server error" }),
      {
        status: 401,
        headers: { ...corsHeaders, "Content-Type": "application/json" },
      }
    );
  }
});

