import { corsHeaders, handleCors } from "../_shared/cors.ts";
import { verifyAuth, createSupabaseClient } from "../_shared/supabase.ts";

const STRIPE_SECRET_KEY = Deno.env.get("STRIPE_SECRET_KEY") || "";
const SUPABASE_URL = Deno.env.get("SUPABASE_URL") || "";
const SUPABASE_ANON_KEY = Deno.env.get("SUPABASE_ANON_KEY") || "";
const SUPABASE_SERVICE_KEY = Deno.env.get("SUPABASE_SERVICE_ROLE_KEY") || "";

serve(async (req: Request) => {
  const corsResponse = handleCors(req);
  if (corsResponse) return corsResponse;

  try {
    const { user } = await verifyAuth(SUPABASE_URL, SUPABASE_ANON_KEY, req);
    const { amount, billId, paymentMethodId, description } = await req.json();

    if (!amount || !paymentMethodId) {
      return new Response(
        JSON.stringify({
          error: "Missing required fields: amount, paymentMethodId",
        }),
        {
          status: 400,
          headers: { ...corsHeaders, "Content-Type": "application/json" },
        }
      );
    }

    const serviceClient = createSupabaseClient(
      SUPABASE_URL,
      SUPABASE_SERVICE_KEY
    );

    // Get or create Stripe customer
    const { data: paymentMethod } = await serviceClient
      .from("payment_methods")
      .select("stripe_customer_id")
      .eq("id", paymentMethodId)
      .eq("user_id", user.id)
      .single();

    let customerId = paymentMethod?.stripe_customer_id;

    if (!customerId) {
      // Create Stripe customer
      const customerResponse = await fetch("https://api.stripe.com/v1/customers", {
        method: "POST",
        headers: {
          Authorization: `Bearer ${STRIPE_SECRET_KEY}`,
          "Content-Type": "application/x-www-form-urlencoded",
        },
        body: new URLSearchParams({
          email: user.email || "",
          metadata: JSON.stringify({ user_id: user.id }),
        }),
      });

      const customerData = await customerResponse.json();
      customerId = customerData.id;

      // Update payment method with customer ID
      await serviceClient
        .from("payment_methods")
        .update({ stripe_customer_id: customerId })
        .eq("id", paymentMethodId);
    }

    // Create payment intent
    const intentResponse = await fetch(
      "https://api.stripe.com/v1/payment_intents",
      {
        method: "POST",
        headers: {
          Authorization: `Bearer ${STRIPE_SECRET_KEY}`,
          "Content-Type": "application/x-www-form-urlencoded",
        },
        body: new URLSearchParams({
          amount: String(Math.round(amount * 100)),
          currency: "usd",
          customer: customerId,
          payment_method: paymentMethod?.stripe_payment_method_id || "",
          off_session: "true",
          confirm: "true",
          description:
            description ||
            `Bill payment ${billId ? `for ${billId}` : ""}`,
          metadata: JSON.stringify({
            user_id: user.id,
            bill_id: billId,
          }),
        }),
      }
    );

    const intentData = await intentResponse.json();

    if (!intentResponse.ok) {
      console.error("Stripe error:", intentData);
      return new Response(
        JSON.stringify({
          error: intentData.error?.message || "Failed to create payment",
        }),
        {
          status: 400,
          headers: { ...corsHeaders, "Content-Type": "application/json" },
        }
      );
    }

    // Create transaction record
    const { error: transError } = await serviceClient
      .from("transactions")
      .insert({
        user_id: user.id,
        bill_id: billId,
        amount,
        type: "payment",
        status: intentData.status === "succeeded" ? "completed" : "pending",
        stripe_payment_intent_id: intentData.id,
      });

    if (transError) {
      console.error("Transaction insert error:", transError);
    }

    return new Response(
      JSON.stringify({
        success: true,
        paymentIntentId: intentData.id,
        status: intentData.status,
        clientSecret:
          intentData.client_secret || (intentData.status === "succeeded" ? null : ""),
      }),
      {
        headers: { ...corsHeaders, "Content-Type": "application/json" },
      }
    );
  } catch (error) {
    console.error("Error:", error);
    return new Response(
      JSON.stringify({ error: error.message || "Internal server error" }),
      {
        status: 500,
        headers: { ...corsHeaders, "Content-Type": "application/json" },
      }
    );
  }
});

