import { serve } from "https://deno.land/std@0.168.0/http/server.ts";
import { corsHeaders, handleCors } from "../_shared/cors.ts";
import { verifyAuth, createSupabaseClient } from "../_shared/supabase.ts";

const STRIPE_SECRET_KEY = Deno.env.get("STRIPE_SECRET_KEY") || "";
const SUPABASE_URL = Deno.env.get("SUPABASE_URL") || "";
const SUPABASE_ANON_KEY = Deno.env.get("SUPABASE_ANON_KEY") || "";
const SUPABASE_SERVICE_KEY = Deno.env.get("SUPABASE_SERVICE_ROLE_KEY") || "";

serve(async (req: Request) => {
  const corsResponse = handleCors(req);
  if (corsResponse) return corsResponse;

  try {
    const { user } = await verifyAuth(SUPABASE_URL, SUPABASE_ANON_KEY, req);
    const { paymentIntentId } = await req.json();

    if (!paymentIntentId) {
      return new Response(
        JSON.stringify({ error: "Missing paymentIntentId" }),
        {
          status: 400,
          headers: { ...corsHeaders, "Content-Type": "application/json" },
        }
      );
    }

    // Retrieve payment intent from Stripe
    const intentResponse = await fetch(
      `https://api.stripe.com/v1/payment_intents/${paymentIntentId}`,
      {
        method: "GET",
        headers: {
          Authorization: `Bearer ${STRIPE_SECRET_KEY}`,
        },
      }
    );

    const intentData = await intentResponse.json();

    if (!intentResponse.ok) {
      console.error("Stripe error:", intentData);
      return new Response(
        JSON.stringify({
          error: intentData.error?.message || "Failed to retrieve payment",
        }),
        {
          status: 400,
          headers: { ...corsHeaders, "Content-Type": "application/json" },
        }
      );
    }

    const serviceClient = createSupabaseClient(
      SUPABASE_URL,
      SUPABASE_SERVICE_KEY
    );

    let transactionStatus = "pending";
    let fundingStatus = "pending";

    if (intentData.status === "succeeded") {
      transactionStatus = "completed";
      fundingStatus = "completed";
    } else if (intentData.status === "requires_action") {
      transactionStatus = "pending";
    } else if (intentData.status === "canceled") {
      transactionStatus = "failed";
      fundingStatus = "failed";
    }

    // Update transaction
    const { error: updateError } = await serviceClient
      .from("transactions")
      .update({ status: transactionStatus })
      .eq("stripe_payment_intent_id", paymentIntentId)
      .eq("user_id", user.id);

    if (updateError) {
      console.error("Transaction update error:", updateError);
    }

    // If successful, mark bill bucket as paid
    if (transactionStatus === "completed") {
      const { data: transaction } = await serviceClient
        .from("transactions")
        .select("bill_id")
        .eq("stripe_payment_intent_id", paymentIntentId)
        .single();

      if (transaction?.bill_id) {
        // Mark the current bill bucket as paid
        const { error: bucketError } = await serviceClient
          .from("bill_buckets")
          .update({
            is_paid: true,
            paid_at: new Date().toISOString(),
          })
          .eq("bill_id", transaction.bill_id)
          .eq("user_id", user.id)
          .eq("is_paid", false)
          .order("billing_period_start", { ascending: false })
          .limit(1);

        if (bucketError) {
          console.error("Bucket update error:", bucketError);
        }
      }
    }

    return new Response(
      JSON.stringify({
        success: transactionStatus === "completed",
        paymentIntentId,
        status: intentData.status,
        transactionStatus,
      }),
      {
        headers: { ...corsHeaders, "Content-Type": "application/json" },
      }
    );
  } catch (error) {
    console.error("Error:", error);
    return new Response(
      JSON.stringify({ error: error.message || "Internal server error" }),
      {
        status: 500,
        headers: { ...corsHeaders, "Content-Type": "application/json" },
      }
    );
  }
});

