          premium_expires_at: session.user.user_metadata?.premium_expires_at,
          streak_count: session.user.user_metadata?.streak_count || 0,
          created_at: session.user.created_at || new Date().toISOString(),
          updated_at: session.user.updated_at || new Date().toISOString(),
        });
        setSignedIn(true);
      } else {
        setUser(null);
        setSignedIn(false);
      }
      setLoading(false);
    });

    return () => {
      data?.subscription.unsubscribe();
    };
  }, [setUser, setSignedIn, setLoading]);

  return (
    <SafeAreaProvider>
      <AppNavigator />
    </SafeAreaProvider>
  );
}

import { create } from 'zustand';
import { PaymentMethod } from '@/types';
import { paymentMethodService } from '@/services/supabase';

interface PaymentStore {
  paymentMethods: PaymentMethod[];
  isLoading: boolean;
  error: string | null;

  fetchPaymentMethods: (userId: string) => Promise<void>;
  addPaymentMethod: (userId: string, method: Record<string, any>) => Promise<void>;
  removePaymentMethod: (paymentMethodId: string) => Promise<void>;
  setDefaultPaymentMethod: (userId: string, paymentMethodId: string) => Promise<void>;

  setPaymentMethods: (methods: PaymentMethod[]) => void;
  setLoading: (loading: boolean) => void;
  setError: (error: string | null) => void;
}

export const usePaymentStore = create<PaymentStore>((set) => ({
  paymentMethods: [],
  isLoading: false,
  error: null,

  setPaymentMethods: (paymentMethods) => set({ paymentMethods }),
  setLoading: (isLoading) => set({ isLoading }),
  setError: (error) => set({ error }),

  fetchPaymentMethods: async (userId) => {
    try {
      set({ isLoading: true, error: null });
      const methods = await paymentMethodService.getPaymentMethods(userId);
      set({ paymentMethods: methods });
    } catch (error) {
      const errorMessage = error instanceof Error ? error.message : 'Failed to fetch payment methods';
      set({ error: errorMessage });
      console.error('Fetch payment methods error:', error);
    } finally {
      set({ isLoading: false });
    }
  },

  addPaymentMethod: async (userId, methodData) => {
    try {
      set({ isLoading: true, error: null });
      const newMethod = await paymentMethodService.addPaymentMethod(userId, methodData);
      set((state) => ({ paymentMethods: [...state.paymentMethods, newMethod] }));
    } catch (error) {
      const errorMessage = error instanceof Error ? error.message : 'Failed to add payment method';
      set({ error: errorMessage });
      console.error('Add payment method error:', error);
      throw error;
    } finally {
      set({ isLoading: false });
    }
  },

  removePaymentMethod: async (paymentMethodId) => {
    try {
      set({ isLoading: true, error: null });
      await paymentMethodService.removePaymentMethod(paymentMethodId);
      set((state) => ({
        paymentMethods: state.paymentMethods.filter((m) => m.id !== paymentMethodId),
      }));
    } catch (error) {
      const errorMessage = error instanceof Error ? error.message : 'Failed to remove payment method';
      set({ error: errorMessage });
      console.error('Remove payment method error:', error);
      throw error;
    } finally {
      set({ isLoading: false });
    }
  },

  setDefaultPaymentMethod: async (userId, paymentMethodId) => {
    try {
      set({ isLoading: true, error: null });
      await paymentMethodService.setDefaultPaymentMethod(userId, paymentMethodId);
      set((state) => ({
        paymentMethods: state.paymentMethods.map((m) => ({
          ...m,
          is_default: m.id === paymentMethodId,
        })),
      }));
    } catch (error) {
      const errorMessage = error instanceof Error ? error.message : 'Failed to set default payment method';
      set({ error: errorMessage });
      console.error('Set default payment method error:', error);
      throw error;
    } finally {
      set({ isLoading: false });
    }
  },
}));

/**
 * Formatting utilities for Fractional Bill Pay
 */

export function formatCurrency(amount: number, currency: string = 'USD'): string {
  return new Intl.NumberFormat('en-US', {
    style: 'currency',
    currency,
  }).format(amount);
}

export function formatDate(dateString: string, locale: string = 'en-US'): string {
  const date = new Date(dateString);
  return new Intl.DateTimeFormat(locale, {
    month: 'short',
    day: 'numeric',
    year: 'numeric',
  }).format(date);
}

export function formatDatetime(dateString: string, locale: string = 'en-US'): string {
  const date = new Date(dateString);
  return new Intl.DateTimeFormat(locale, {
    month: 'short',
    day: 'numeric',
    year: 'numeric',
    hour: 'numeric',
    minute: '2-digit',
  }).format(date);
}

export function getDayOfMonthOrdinal(day: number): string {
  if (day >= 11 && day <= 13) {
    return `${day}th`;
  }
  const lastDigit = day % 10;
  if (lastDigit === 1) {
    return `${day}st`;
  }
  if (lastDigit === 2) {
    return `${day}nd`;
  }
  if (lastDigit === 3) {
    return `${day}rd`;
  }
  return `${day}th`;
}

export function formatPercentage(value: number, decimals: number = 0): string {
  return `${(value * 100).toFixed(decimals)}%`;
}

export function truncateString(str: string, maxLength: number): string {
  if (str.length <= maxLength) {
    return str;
  }
  return `${str.slice(0, maxLength - 3)}...`;
}

export function getMonthName(monthIndex: number, locale: string = 'en-US'): string {
  const date = new Date(2024, monthIndex, 1);
  return new Intl.DateTimeFormat(locale, { month: 'long' }).format(date);
}

export function getDaysUntil(targetDate: string): number {
  const today = new Date();
  today.setHours(0, 0, 0, 0);

  const target = new Date(targetDate);
  target.setHours(0, 0, 0, 0);

  const diffTime = target.getTime() - today.getTime();
  const diffDays = Math.ceil(diffTime / (1000 * 60 * 60 * 24));

  return diffDays;
}

export function maskCardNumber(cardNumber: string): string {
  const lastFour = cardNumber.slice(-4);
  return `•••• •••• •••• ${lastFour}`;
}

export function maskEmail(email: string): string {
  const [localPart, domain] = email.split('@');
  const maskedLocal = localPart[0] + '*'.repeat(localPart.length - 2) + localPart[localPart.length - 1];
  return `${maskedLocal}@${domain}`;
}

import { serve } from "https://deno.land/std@0.168.0/http/server.ts";
import { corsHeaders, handleCors } from "../_shared/cors.ts";
import { verifyAuth, createSupabaseClient } from "../_shared/supabase.ts";

const STRIPE_SECRET_KEY = Deno.env.get("STRIPE_SECRET_KEY") || "";
const SUPABASE_URL = Deno.env.get("SUPABASE_URL") || "";
const SUPABASE_ANON_KEY = Deno.env.get("SUPABASE_ANON_KEY") || "";
const SUPABASE_SERVICE_KEY = Deno.env.get("SUPABASE_SERVICE_ROLE_KEY") || "";

serve(async (req: Request) => {
  const corsResponse = handleCors(req);
  if (corsResponse) return corsResponse;

  try {
    const { user } = await verifyAuth(SUPABASE_URL, SUPABASE_ANON_KEY, req);
    const serviceClient = createSupabaseClient(
      SUPABASE_URL,
      SUPABASE_SERVICE_KEY
    );

    const url = new URL(req.url);
    const action = url.searchParams.get("action") || "list";

    // LIST payment methods
    if (req.method === "GET" && action === "list") {
      const { data, error } = await serviceClient
        .from("payment_methods")
        .select("*")
        .eq("user_id", user.id)
        .order("created_at", { ascending: false });

      if (error) {
        throw error;
      }

      return new Response(JSON.stringify({ methods: data || [] }), {
        headers: { ...corsHeaders, "Content-Type": "application/json" },
      });
    }

    // ATTACH payment method
    if (req.method === "POST" && action === "attach") {
      const { paymentMethodToken, type, cardLast4, cardBrand } =
        await req.json();

      if (!paymentMethodToken) {
        return new Response(
          JSON.stringify({ error: "Missing paymentMethodToken" }),
          {
            status: 400,
            headers: { ...corsHeaders, "Content-Type": "application/json" },
          }
        );
      }

      // Create Stripe customer if needed
      let customerId: string;

      const { data: existing } = await serviceClient
        .from("payment_methods")
        .select("stripe_customer_id")
        .eq("user_id", user.id)
        .limit(1);

      if (existing && existing.length > 0 && existing[0].stripe_customer_id) {
        customerId = existing[0].stripe_customer_id;
      } else {
        const customerResponse = await fetch("https://api.stripe.com/v1/customers", {
          method: "POST",
          headers: {
            Authorization: `Bearer ${STRIPE_SECRET_KEY}`,
            "Content-Type": "application/x-www-form-urlencoded",
          },
          body: new URLSearchParams({
            email: user.email || "",
            metadata: JSON.stringify({ user_id: user.id }),
          }),
        });

        const customerData = await customerResponse.json();
        customerId = customerData.id;
      }

      // Create payment method in Stripe (assuming token is a Stripe token)
      const methodResponse = await fetch(
        "https://api.stripe.com/v1/payment_methods",
        {
          method: "POST",
          headers: {
            Authorization: `Bearer ${STRIPE_SECRET_KEY}`,
            "Content-Type": "application/x-www-form-urlencoded",
          },
          body: new URLSearchParams({
            type: type || "card",
            card: JSON.stringify(paymentMethodToken),
          }),
        }
      );

      const methodData = await methodResponse.json();

      if (!methodResponse.ok) {
        console.error("Stripe payment method error:", methodData);
        return new Response(
          JSON.stringify({
            error: methodData.error?.message || "Failed to add payment method",
          }),
          {
            status: 400,
            headers: { ...corsHeaders, "Content-Type": "application/json" },
          }
        );
      }

      // Attach to customer
      const attachResponse = await fetch(
        `https://api.stripe.com/v1/payment_methods/${methodData.id}/attach`,
        {
          method: "POST",
          headers: {
            Authorization: `Bearer ${STRIPE_SECRET_KEY}`,
            "Content-Type": "application/x-www-form-urlencoded",
          },
          body: new URLSearchParams({
            customer: customerId,
          }),
        }
      );

      if (!attachResponse.ok) {
        console.error("Stripe attach error:", await attachResponse.json());
        return new Response(
          JSON.stringify({ error: "Failed to attach payment method" }),
          {
            status: 400,
            headers: { ...corsHeaders, "Content-Type": "application/json" },
          }
        );
      }

      // Save to database
      const { data: newMethod, error: insertError } = await serviceClient
        .from("payment_methods")
        .insert({
          user_id: user.id,
          type: type || "card",
          last_four: cardLast4 || "",
          brand: cardBrand || "",
          stripe_payment_method_id: methodData.id,
          stripe_customer_id: customerId,
          is_default: false,
        })
        .select();

      if (insertError) {
        throw insertError;
      }

      return new Response(
        JSON.stringify({
          success: true,
          method: newMethod[0],
        }),
        {
          headers: { ...corsHeaders, "Content-Type": "application/json" },
        }
      );
    }

    // DETACH payment method
    if (req.method === "DELETE" && action === "detach") {
      const { methodId } = await req.json();

      if (!methodId) {
        return new Response(JSON.stringify({ error: "Missing methodId" }), {
          status: 400,
          headers: { ...corsHeaders, "Content-Type": "application/json" },
        });
      }

      const { data: method } = await serviceClient
        .from("payment_methods")
        .select("stripe_payment_method_id")
        .eq("id", methodId)
        .eq("user_id", user.id)
        .single();

      if (!method || !method.stripe_payment_method_id) {
        return new Response(JSON.stringify({ error: "Payment method not found" }), {
          status: 404,
          headers: { ...corsHeaders, "Content-Type": "application/json" },
        });
      }

      // Detach from Stripe
      const detachResponse = await fetch(
        `https://api.stripe.com/v1/payment_methods/${method.stripe_payment_method_id}/detach`,
        {
          method: "POST",
          headers: {
            Authorization: `Bearer ${STRIPE_SECRET_KEY}`,
            "Content-Type": "application/x-www-form-urlencoded",
          },
        }
      );

      if (!detachResponse.ok) {
        console.error("Stripe detach error:", await detachResponse.json());
      }

      // Delete from database
      const { error: deleteError } = await serviceClient
        .from("payment_methods")
        .delete()
        .eq("id", methodId)
        .eq("user_id", user.id);

      if (deleteError) {
        throw deleteError;
      }

      return new Response(
        JSON.stringify({ success: true }),
        {
          headers: { ...corsHeaders, "Content-Type": "application/json" },
        }
      );
    }

    // SET DEFAULT payment method
    if (req.method === "PATCH" && action === "set-default") {
      const { methodId } = await req.json();

      if (!methodId) {
        return new Response(JSON.stringify({ error: "Missing methodId" }), {
          status: 400,
          headers: { ...corsHeaders, "Content-Type": "application/json" },
        });
      }

      // Clear other defaults
      await serviceClient
        .from("payment_methods")
        .update({ is_default: false })
        .eq("user_id", user.id);

      // Set new default
      const { data, error } = await serviceClient
        .from("payment_methods")
        .update({ is_default: true })
        .eq("id", methodId)
        .eq("user_id", user.id)
        .select();

      if (error) {
        throw error;
      }

      return new Response(
        JSON.stringify({ success: true, method: data[0] }),
        {
          headers: { ...corsHeaders, "Content-Type": "application/json" },
        }
      );
    }

    return new Response(JSON.stringify({ error: "Invalid action" }), {
      status: 400,
      headers: { ...corsHeaders, "Content-Type": "application/json" },
    });
  } catch (error) {
    console.error("Error:", error);
    return new Response(
      JSON.stringify({ error: error.message || "Internal server error" }),
      {
        status: 500,
        headers: { ...corsHeaders, "Content-Type": "application/json" },
      }
    );
  }
});

/**
 * Validation utilities for Fractional Bill Pay
 */

export function isValidEmail(email: string): boolean {
  const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
  return emailRegex.test(email);
}

export function isValidPassword(password: string): {
  isValid: boolean;
  errors: string[];
} {
  const errors: string[] = [];

  if (password.length < 8) {
    errors.push('Password must be at least 8 characters');
  }

  if (!/[A-Z]/.test(password)) {
    errors.push('Password must contain at least one uppercase letter');
  }

  if (!/[a-z]/.test(password)) {
    errors.push('Password must contain at least one lowercase letter');
  }

  if (!/[0-9]/.test(password)) {
    errors.push('Password must contain at least one number');
  }

  return {
    isValid: errors.length === 0,
    errors,
  };
}

export function isValidPhoneNumber(phone: string): boolean {
  // Basic validation for US phone numbers
  const phoneRegex = /^(\+1)?[-.\s]?\(?[0-9]{3}\)?[-.\s]?[0-9]{3}[-.\s]?[0-9]{4}$/;
  return phoneRegex.test(phone);
}

export function isValidAmount(amount: any): boolean {
  const num = parseFloat(amount);
  return !isNaN(num) && num > 0;
}

export function isValidPercentage(value: any): boolean {
  const num = parseFloat(value);
  return !isNaN(num) && num >= 0 && num <= 100;
}

export function isValidCardNumber(cardNumber: string): boolean {
  // Basic Luhn algorithm validation
  const cleaned = cardNumber.replace(/\s/g, '');

  if (!/^\d+$/.test(cleaned)) {
    return false;
  }

  if (cleaned.length < 13 || cleaned.length > 19) {
    return false;
  }

  let sum = 0;
  let isEven = false;

  for (let i = cleaned.length - 1; i >= 0; i--) {
    let digit = parseInt(cleaned.charAt(i), 10);

    if (isEven) {
      digit *= 2;
      if (digit > 9) {
        digit -= 9;
      }
    }

    sum += digit;
    isEven = !isEven;
  }

  return sum % 10 === 0;
}

export function isValidExpiryDate(month: string, year: string): boolean {
  const m = parseInt(month, 10);
  const y = parseInt(year, 10);

  if (m < 1 || m > 12) {
    return false;
  }

  const currentDate = new Date();
  const currentYear = currentDate.getFullYear() % 100;
  const currentMonth = currentDate.getMonth() + 1;

  if (y < currentYear) {
    return false;
  }

  if (y === currentYear && m < currentMonth) {
    return false;
  }

  return true;
}

export function isValidCVV(cvv: string, cardType?: string): boolean {
  const cvvLength = cardType === 'amex' ? 4 : 3;
  return /^\d+$/.test(cvv) && cvv.length === cvvLength;
}

export function isValidBillName(name: string): boolean {
  return name.trim().length > 0 && name.length <= 100;
}

export function isValidBillAmount(amount: any): boolean {
  const num = parseFloat(amount);
  return !isNaN(num) && num > 0 && num <= 999999.99;
}

import { serve } from "https://deno.land/std@0.168.0/http/server.ts";
import { corsHeaders, handleCors } from "../_shared/cors.ts";
import { verifyAuth, createSupabaseClient } from "../_shared/supabase.ts";

const STRIPE_SECRET_KEY = Deno.env.get("STRIPE_SECRET_KEY") || "";
const STRIPE_PRICE_ID = Deno.env.get("STRIPE_PREMIUM_PRICE_ID") || "";
const SUPABASE_URL = Deno.env.get("SUPABASE_URL") || "";
const SUPABASE_ANON_KEY = Deno.env.get("SUPABASE_ANON_KEY") || "";
const SUPABASE_SERVICE_KEY = Deno.env.get("SUPABASE_SERVICE_ROLE_KEY") || "";

serve(async (req: Request) => {
  const corsResponse = handleCors(req);
  if (corsResponse) return corsResponse;

  try {
    const { user } = await verifyAuth(SUPABASE_URL, SUPABASE_ANON_KEY, req);
    const { paymentMethodId } = await req.json();

    if (!paymentMethodId) {
      return new Response(
        JSON.stringify({ error: "Missing paymentMethodId" }),
        {
          status: 400,
          headers: { ...corsHeaders, "Content-Type": "application/json" },
        }
      );
    }

    const serviceClient = createSupabaseClient(
      SUPABASE_URL,
      SUPABASE_SERVICE_KEY
    );

    // Get payment method details
    const { data: paymentMethod } = await serviceClient
      .from("payment_methods")
      .select("stripe_customer_id, stripe_payment_method_id")
      .eq("id", paymentMethodId)
      .eq("user_id", user.id)
      .single();

    if (!paymentMethod || !paymentMethod.stripe_customer_id) {
      return new Response(
        JSON.stringify({ error: "Payment method not found" }),
        {
          status: 404,
          headers: { ...corsHeaders, "Content-Type": "application/json" },
        }
      );
    }

    // Check if subscription already exists
    const { data: existing } = await serviceClient
      .from("subscriptions")
      .select("stripe_subscription_id, status")
      .eq("user_id", user.id)
      .eq("plan", "premium")
      .neq("status", "canceled");

    if (existing && existing.length > 0) {
      return new Response(
        JSON.stringify({
          error: "Premium subscription already active",
          subscription: existing[0],
        }),
        {
          status: 400,
          headers: { ...corsHeaders, "Content-Type": "application/json" },
        }
      );
    }

    // Create subscription in Stripe
    const subscriptionResponse = await fetch(
      "https://api.stripe.com/v1/subscriptions",
      {
        method: "POST",
        headers: {
          Authorization: `Bearer ${STRIPE_SECRET_KEY}`,
          "Content-Type": "application/x-www-form-urlencoded",
        },
        body: new URLSearchParams({
          customer: paymentMethod.stripe_customer_id,
          items: JSON.stringify([{ price: STRIPE_PRICE_ID }]),
          default_payment_method:
            paymentMethod.stripe_payment_method_id || "",
          off_session: "true",
          metadata: JSON.stringify({ user_id: user.id }),
        }),
      }
    );

    const subscriptionData = await subscriptionResponse.json();

    if (!subscriptionResponse.ok) {
      console.error("Stripe subscription error:", subscriptionData);
      return new Response(
        JSON.stringify({
          error:
            subscriptionData.error?.message ||
            "Failed to create subscription",
        }),
        {
          status: 400,
          headers: { ...corsHeaders, "Content-Type": "application/json" },
        }
      );
    }

    // Save subscription to database
    const { data: subscription, error: insertError } = await serviceClient
      .from("subscriptions")
      .insert({
        user_id: user.id,
        stripe_subscription_id: subscriptionData.id,
        stripe_customer_id: paymentMethod.stripe_customer_id,
        plan: "premium",
        status: subscriptionData.status,
        current_period_start: new Date(
          subscriptionData.current_period_start * 1000
        ).toISOString(),
        current_period_end: new Date(
          subscriptionData.current_period_end * 1000
        ).toISOString(),
      })
      .select();

    if (insertError) {
      throw insertError;
    }

    // Update profile to mark as premium
    await serviceClient
      .from("profiles")
      .update({
        is_premium: true,
        premium_expires_at: new Date(
          subscriptionData.current_period_end * 1000
        ).toISOString(),
      })
      .eq("id", user.id);

    return new Response(
      JSON.stringify({
        success: true,
        subscription: subscription[0],
        message: "Premium subscription activated",
      }),
      {
        headers: { ...corsHeaders, "Content-Type": "application/json" },
      }
    );
  } catch (error) {
    console.error("Error:", error);
    return new Response(
      JSON.stringify({ error: error.message || "Internal server error" }),
      {
        status: 500,
        headers: { ...corsHeaders, "Content-Type": "application/json" },
      }
    );
  }
});

-- Enable required extensions
CREATE EXTENSION IF NOT EXISTS "uuid-ossp";
CREATE EXTENSION IF NOT EXISTS "pgcrypto";

-- Users table (extends Supabase auth)
CREATE TABLE IF NOT EXISTS users (
  id UUID PRIMARY KEY REFERENCES auth.users(id) ON DELETE CASCADE,
  email TEXT UNIQUE NOT NULL,
  full_name TEXT,
  avatar_url TEXT,
  income_cadence TEXT DEFAULT 'monthly' CHECK (income_cadence IN ('daily', 'weekly', 'biweekly', 'monthly')),
  income_amount DECIMAL(10, 2),
  pay_day INTEGER,
  timezone TEXT DEFAULT 'UTC',
  is_premium BOOLEAN DEFAULT FALSE,
  premium_expires_at TIMESTAMP WITH TIME ZONE,
  streak_count INTEGER DEFAULT 0,
  created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
  updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP
);

-- Bills table
CREATE TABLE IF NOT EXISTS bills (
  id UUID PRIMARY KEY DEFAULT uuid_generate_v4(),
  user_id UUID NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  name TEXT NOT NULL,
  description TEXT,
  amount DECIMAL(10, 2) NOT NULL CHECK (amount > 0),
  due_date INTEGER NOT NULL CHECK (due_date >= 1 AND due_date <= 31),
  category TEXT NOT NULL DEFAULT 'other',
  is_auto_detected BOOLEAN DEFAULT FALSE,
  plaid_merchant_name TEXT,
  cadence TEXT DEFAULT 'monthly' CHECK (cadence IN ('daily', 'weekly', 'biweekly', 'monthly')),
  contribution_amount DECIMAL(10, 2),
  is_active BOOLEAN DEFAULT TRUE,
  created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
  updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP
);

-- Micro-contributions table
CREATE TABLE IF NOT EXISTS micro_contributions (
  id UUID PRIMARY KEY DEFAULT uuid_generate_v4(),
  bill_id UUID NOT NULL REFERENCES bills(id) ON DELETE CASCADE,
  user_id UUID NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  amount DECIMAL(10, 2) NOT NULL CHECK (amount > 0),
  due_date DATE NOT NULL,
  is_paid BOOLEAN DEFAULT FALSE,
  paid_at TIMESTAMP WITH TIME ZONE,
  payment_method_id UUID,
  created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
  updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP
);

-- Payment methods table
CREATE TABLE IF NOT EXISTS payment_methods (
  id UUID PRIMARY KEY DEFAULT uuid_generate_v4(),
  user_id UUID NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  type TEXT NOT NULL CHECK (type IN ('card', 'bank', 'apple_pay', 'paypal')),
