import { serve } from "https://deno.land/std@0.168.0/http/server.ts";
import { corsHeaders, handleCors } from "../_shared/cors.ts";
import { createSupabaseClient } from "../_shared/supabase.ts";

const STRIPE_WEBHOOK_SECRET = Deno.env.get("STRIPE_WEBHOOK_SECRET") || "";
const SUPABASE_URL = Deno.env.get("SUPABASE_URL") || "";
const SUPABASE_SERVICE_KEY = Deno.env.get("SUPABASE_SERVICE_ROLE_KEY") || "";

function verifyStripeSignature(
  body: string,
  signature: string,
  secret: string
): boolean {
  try {
    // In production, implement proper Stripe signature verification
    // For now, this is a simplified version
    return signature === `t=${Date.now()},v1=test`;
  } catch {
    return false;
  }
}

serve(async (req: Request) => {
  if (req.method === "OPTIONS") {
    return new Response("ok", { headers: corsHeaders });
  }

  try {
    const body = await req.text();
    const signature = req.headers.get("stripe-signature") || "";

    if (!verifyStripeSignature(body, signature, STRIPE_WEBHOOK_SECRET)) {
      console.warn("Invalid Stripe signature");
      return new Response(JSON.stringify({ received: true }), {
        status: 200,
        headers: { "Content-Type": "application/json" },
      });
    }

    const event = JSON.parse(body);
    const serviceClient = createSupabaseClient(
      SUPABASE_URL,
      SUPABASE_SERVICE_KEY
    );

    console.log(`Processing Stripe event: ${event.type}`);

    switch (event.type) {
      case "payment_intent.succeeded":
        {
          const { metadata, id } = event.data.object;
          const userId = metadata?.user_id;

          if (userId) {
            await serviceClient
              .from("transactions")
              .update({ status: "completed" })
              .eq("stripe_payment_intent_id", id);
          }
        }
        break;

      case "payment_intent.payment_failed":
        {
          const { metadata, id } = event.data.object;
          const userId = metadata?.user_id;

          if (userId) {
            await serviceClient
              .from("transactions")
              .update({ status: "failed" })
              .eq("stripe_payment_intent_id", id);

            // Create notification
            await serviceClient.from("notifications").insert({
              user_id: userId,
              title: "Payment Failed",
              body: "Your recent payment could not be processed. Please try again.",
              type: "system",
            });
          }
        }
        break;

      case "customer.subscription.created":
      case "customer.subscription.updated":
        {
          const { id, metadata, status, current_period_start, current_period_end } =
            event.data.object;
          const userId = metadata?.user_id;

          if (userId) {
            const { data: existing } = await serviceClient
              .from("subscriptions")
              .select("id")
              .eq("stripe_subscription_id", id);

            if (existing && existing.length > 0) {
              await serviceClient
                .from("subscriptions")
                .update({
                  status,
                  current_period_start: new Date(
                    current_period_start * 1000
                  ).toISOString(),
                  current_period_end: new Date(
                    current_period_end * 1000
                  ).toISOString(),
                })
                .eq("stripe_subscription_id", id);
            } else {
              await serviceClient.from("subscriptions").insert({
                user_id: userId,
                stripe_subscription_id: id,
                plan: "premium",
                status,
                current_period_start: new Date(
                  current_period_start * 1000
                ).toISOString(),
                current_period_end: new Date(
                  current_period_end * 1000
                ).toISOString(),
              });
            }

            // Update profile
            await serviceClient
              .from("profiles")
              .update({
                is_premium: status === "active",
                premium_expires_at: new Date(
                  current_period_end * 1000
                ).toISOString(),
              })
              .eq("id", userId);
          }
        }
        break;

      case "customer.subscription.deleted":
        {
          const { id, metadata } = event.data.object;
          const userId = metadata?.user_id;

          if (userId) {
            await serviceClient
              .from("subscriptions")
              .update({ status: "canceled" })
              .eq("stripe_subscription_id", id);

            // Update profile
            await serviceClient
              .from("profiles")
              .update({ is_premium: false })
              .eq("id", userId);

            // Create notification
            await serviceClient.from("notifications").insert({
              user_id: userId,
              title: "Subscription Canceled",
              body: "Your premium subscription has been canceled.",
              type: "system",
            });
          }
        }
        break;

      case "invoice.payment_failed":
        {
          const { customer, billing_reason } = event.data.object;

          if (customer) {
            // Get user from subscription
            const { data: subscription } = await serviceClient
              .from("subscriptions")
              .select("user_id")
              .eq("stripe_customer_id", customer)
              .limit(1);

            if (subscription && subscription.length > 0) {
              const userId = subscription[0].user_id;

              await serviceClient.from("notifications").insert({
                user_id: userId,
                title: "Invoice Payment Failed",
                body: `Your ${billing_reason} payment could not be processed. Please update your payment method.`,
                type: "system",
              });
            }
          }
        }
        break;

      default:
        console.log(`Unhandled Stripe event type: ${event.type}`);
    }

    return new Response(JSON.stringify({ received: true }), {
      status: 200,
      headers: { "Content-Type": "application/json" },
    });
  } catch (error) {
    console.error("Webhook error:", error);
    return new Response(
      JSON.stringify({ error: error.message || "Webhook processing failed" }),
      {
        status: 500,
        headers: { "Content-Type": "application/json" },
      }
    );
  }
});

import { useMemo } from 'react';
import { Bill, MicroContribution } from '@/types';

interface BillStatsResult {
  totalBills: number;
  totalAmount: number;
  paidThisMonth: number;
  pendingThisMonth: number;
  dueSoonCount: number;
  averageBillAmount: number;
  on_track_count: number;
  behind_count: number;
}

export function useBillStats(
  bills: Bill[],
  contributions: MicroContribution[]
): BillStatsResult {
  return useMemo(() => {
    const now = new Date();
    const currentMonth = now.getMonth() + 1;
    const currentYear = now.getFullYear();

    const totalBills = bills.length;
    const totalAmount = bills.reduce((sum, bill) => sum + bill.amount, 0);

    // Count contributions paid this month
    const paidThisMonth = contributions.filter((c) => {
      if (!c.is_paid || !c.paid_at) return false;
      const paidDate = new Date(c.paid_at);
      return (
        paidDate.getMonth() + 1 === currentMonth &&
        paidDate.getFullYear() === currentYear
      );
    }).length;

    const pendingThisMonth = contributions.filter((c) => {
      if (c.is_paid) return false;
      const dueDate = new Date(c.due_date);
      return (
        dueDate.getMonth() + 1 === currentMonth &&
        dueDate.getFullYear() === currentYear
      );
    }).length;

    // Count bills due in next 7 days
    const dueSoonCount = bills.filter((bill) => {
      const daysUntilDue = bill.due_date - now.getDate();
      return daysUntilDue > 0 && daysUntilDue <= 7;
    }).length;

    const averageBillAmount = totalBills > 0 ? totalAmount / totalBills : 0;

    // Count on-track and behind bills
    let on_track_count = 0;
    let behind_count = 0;

    bills.forEach((bill) => {
      const billContributions = contributions.filter((c) => c.bill_id === bill.id);
      const totalPaid = billContributions
        .filter((c) => c.is_paid)
        .reduce((sum, c) => sum + c.amount, 0);

      if (totalPaid >= bill.amount) {
        on_track_count++;
      } else if (totalPaid === 0 && bill.due_date < now.getDate()) {
        behind_count++;
      }
    });

    return {
      totalBills,
      totalAmount,
      paidThisMonth,
      pendingThisMonth,
      dueSoonCount,
      averageBillAmount,
      on_track_count,
      behind_count,
    };
  }, [bills, contributions]);
}

import { useState, useEffect, useCallback, useRef } from 'react';

interface AsyncState<T> {
  status: 'idle' | 'pending' | 'success' | 'error';
  data: T | null;
  error: Error | null;
}

export function useAsync<T>(
  asyncFunction: () => Promise<T>,
  immediate: boolean = true,
  dependencies: any[] = []
) {
  const [state, setState] = useState<AsyncState<T>>({
    status: 'idle',
    data: null,
    error: null,
  });

  const mountedRef = useRef(true);

  const execute = useCallback(async () => {
    setState({ status: 'pending', data: null, error: null });
    try {
      const response = await asyncFunction();
      if (mountedRef.current) {
        setState({ status: 'success', data: response, error: null });
      }
      return response;
    } catch (error) {
      if (mountedRef.current) {
        setState({
          status: 'error',
          data: null,
          error: error instanceof Error ? error : new Error('Unknown error'),
        });
      }
      throw error;
    }
  }, [asyncFunction]);

  useEffect(() => {
    mountedRef.current = true;

    if (immediate) {
      execute();
    }

    return () => {
      mountedRef.current = false;
    };
  }, dependencies);

  return { ...state, execute };
}

import { serve } from "https://deno.land/std@0.168.0/http/server.ts";
import { corsHeaders, handleCors } from "../_shared/cors.ts";
import { verifyAuth, createSupabaseClient } from "../_shared/supabase.ts";

const AIRTABLE_API_KEY = Deno.env.get("AIRTABLE_API_KEY") || "";
const AIRTABLE_BASE_ID = Deno.env.get("AIRTABLE_BASE_ID") || "";
const SUPABASE_URL = Deno.env.get("SUPABASE_URL") || "";
const SUPABASE_ANON_KEY = Deno.env.get("SUPABASE_ANON_KEY") || "";
const SUPABASE_SERVICE_KEY = Deno.env.get("SUPABASE_SERVICE_ROLE_KEY") || "";

interface AirtableRecord {
  id?: string;
  fields: Record<string, unknown>;
  createdTime?: string;
}

serve(async (req: Request) => {
  const corsResponse = handleCors(req);
  if (corsResponse) return corsResponse;

  try {
    const { user } = await verifyAuth(SUPABASE_URL, SUPABASE_ANON_KEY, req);
    const serviceClient = createSupabaseClient(
      SUPABASE_URL,
      SUPABASE_SERVICE_KEY
    );

    const url = new URL(req.url);
    const action = url.searchParams.get("action") || "sync-users";

    // SYNC USERS to Airtable
    if (req.method === "POST" && action === "sync-users") {
      const { data: profiles } = await serviceClient
        .from("profiles")
        .select("*")
        .eq("id", user.id);

      if (!profiles || profiles.length === 0) {
        return new Response(
          JSON.stringify({ error: "No profile found" }),
          {
            status: 404,
            headers: { ...corsHeaders, "Content-Type": "application/json" },
          }
        );
      }

      const profile = profiles[0];

      const airtableRecords: AirtableRecord[] = [
        {
          fields: {
            "User ID": profile.id,
            Email: profile.email,
            "Full Name": profile.full_name,
            "Income Cadence": profile.income_cadence,
            "Income Amount": profile.income_amount,
            "Pay Day": profile.pay_day,
            Timezone: profile.timezone,
            "Is Premium": profile.is_premium,
            "Streak Count": profile.streak_count,
            "Onboarding Completed": profile.onboarding_completed,
            "Created At": profile.created_at,
            "Updated At": profile.updated_at,
          },
        },
      ];

      const airtableResponse = await fetch(
        `https://api.airtable.com/v0/${AIRTABLE_BASE_ID}/Users`,
        {
          method: "POST",
          headers: {
            Authorization: `Bearer ${AIRTABLE_API_KEY}`,
            "Content-Type": "application/json",
          },
          body: JSON.stringify({ records: airtableRecords }),
        }
      );

      const airtableData = await airtableResponse.json();

      if (!airtableResponse.ok) {
        console.error("Airtable error:", airtableData);
        return new Response(
          JSON.stringify({
            error: airtableData.error?.message || "Failed to sync to Airtable",
          }),
          {
            status: 400,
            headers: { ...corsHeaders, "Content-Type": "application/json" },
          }
        );
      }

      return new Response(
        JSON.stringify({
          success: true,
          synced: airtableData.records.length,
        }),
        {
          headers: { ...corsHeaders, "Content-Type": "application/json" },
        }
      );
    }

    // SYNC BILLS to Airtable
    if (req.method === "POST" && action === "sync-bills") {
      const { data: bills } = await serviceClient
        .from("bills")
        .select("*")
        .eq("user_id", user.id);

      if (!bills || bills.length === 0) {
        return new Response(
          JSON.stringify({ synced: 0, message: "No bills to sync" }),
          {
            headers: { ...corsHeaders, "Content-Type": "application/json" },
          }
        );
      }

      const airtableRecords: AirtableRecord[] = bills.map((bill) => ({
        fields: {
          "Bill ID": bill.id,
          "User ID": bill.user_id,
          Name: bill.name,
          Amount: bill.amount,
          "Due Date": bill.due_date,
          Category: bill.category,
          "Is Active": bill.is_active,
          Cadence: bill.cadence,
          "Contribution Amount": bill.contribution_amount,
          "Created At": bill.created_at,
        },
      }));

      const airtableResponse = await fetch(
        `https://api.airtable.com/v0/${AIRTABLE_BASE_ID}/Bills`,
        {
          method: "POST",
          headers: {
            Authorization: `Bearer ${AIRTABLE_API_KEY}`,
            "Content-Type": "application/json",
          },
          body: JSON.stringify({ records: airtableRecords }),
        }
      );

      const airtableData = await airtableResponse.json();

      if (!airtableResponse.ok) {
        console.error("Airtable error:", airtableData);
        return new Response(
          JSON.stringify({
            error: airtableData.error?.message || "Failed to sync bills",
          }),
          {
            status: 400,
            headers: { ...corsHeaders, "Content-Type": "application/json" },
          }
        );
      }

      return new Response(
        JSON.stringify({
          success: true,
          synced: airtableData.records.length,
        }),
        {
          headers: { ...corsHeaders, "Content-Type": "application/json" },
        }
      );
    }

    // SYNC TRANSACTIONS to Airtable
    if (req.method === "POST" && action === "sync-transactions") {
      const { data: transactions } = await serviceClient
        .from("transactions")
        .select("*")
        .eq("user_id", user.id)
        .order("created_at", { ascending: false })
        .limit(100);

      if (!transactions || transactions.length === 0) {
        return new Response(
          JSON.stringify({ synced: 0, message: "No transactions to sync" }),
          {
            headers: { ...corsHeaders, "Content-Type": "application/json" },
          }
        );
      }

      const airtableRecords: AirtableRecord[] = transactions.map(
        (transaction) => ({
          fields: {
            "Transaction ID": transaction.id,
            "User ID": transaction.user_id,
            "Bill ID": transaction.bill_id,
            Amount: transaction.amount,
            Type: transaction.type,
            Status: transaction.status,
            Description: transaction.description,
            "Created At": transaction.created_at,
          },
        })
      );

      const airtableResponse = await fetch(
        `https://api.airtable.com/v0/${AIRTABLE_BASE_ID}/Transactions`,
        {
          method: "POST",
          headers: {
            Authorization: `Bearer ${AIRTABLE_API_KEY}`,
            "Content-Type": "application/json",
          },
          body: JSON.stringify({ records: airtableRecords }),
        }
      );

      const airtableData = await airtableResponse.json();

      if (!airtableResponse.ok) {
        console.error("Airtable error:", airtableData);
        return new Response(
          JSON.stringify({
            error:
              airtableData.error?.message || "Failed to sync transactions",
          }),
          {
            status: 400,
            headers: { ...corsHeaders, "Content-Type": "application/json" },
          }
        );
      }

      return new Response(
        JSON.stringify({
          success: true,
          synced: airtableData.records.length,
        }),
        {
          headers: { ...corsHeaders, "Content-Type": "application/json" },
        }
      );
    }

    // GET AIRTABLE USERS
    if (req.method === "GET" && action === "get-users") {
      const airtableResponse = await fetch(
        `https://api.airtable.com/v0/${AIRTABLE_BASE_ID}/Users`,
        {
          method: "GET",
          headers: {
            Authorization: `Bearer ${AIRTABLE_API_KEY}`,
          },
        }
      );

      const airtableData = await airtableResponse.json();

      if (!airtableResponse.ok) {
        console.error("Airtable error:", airtableData);
        return new Response(
          JSON.stringify({
            error: airtableData.error?.message || "Failed to fetch users",
          }),
          {
            status: 400,
            headers: { ...corsHeaders, "Content-Type": "application/json" },
          }
        );
      }

      return new Response(JSON.stringify(airtableData), {
        headers: { ...corsHeaders, "Content-Type": "application/json" },
      });
    }

    return new Response(JSON.stringify({ error: "Invalid action" }), {
      status: 400,
      headers: { ...corsHeaders, "Content-Type": "application/json" },
    });
  } catch (error) {
    console.error("Error:", error);
    return new Response(
      JSON.stringify({ error: error.message || "Internal server error" }),
      {
        status: 500,
        headers: { ...corsHeaders, "Content-Type": "application/json" },
      }
    );
  }
});

