/**
 * Error handling utilities
 */

export interface AppError {
  code: string;
  message: string;
  statusCode?: number;
  originalError?: Error;
}

export class AppErrorHandler {
  static handle(error: unknown): AppError {
    // Handle Supabase errors
    if (error && typeof error === 'object' && 'status' in error) {
      const supabaseError = error as any;
      return {
        code: supabaseError.status || 'UNKNOWN_ERROR',
        message: supabaseError.message || 'An unexpected error occurred',
        statusCode: supabaseError.status,
        originalError: error instanceof Error ? error : undefined,
      };
    }

    // Handle native errors
    if (error instanceof Error) {
      return {
        code: 'ERROR',
        message: error.message,
        originalError: error,
      };
    }

    // Handle unknown errors
    return {
      code: 'UNKNOWN_ERROR',
      message: 'An unexpected error occurred',
    };
  }

  static getErrorMessage(error: unknown): string {
    const appError = this.handle(error);
    return appError.message;
  }

  static logError(error: unknown, context?: string): void {
    const appError = this.handle(error);
    console.error(`[${context || 'AppError'}] ${appError.code}: ${appError.message}`, {
      originalError: appError.originalError,
    });
  }

  static isNetworkError(error: unknown): boolean {
    const appError = this.handle(error);
    return (
      appError.code === 'NETWORK_ERROR' ||
      appError.code === 'ECONNREFUSED' ||
      appError.code === 'TIMEOUT'
    );
  }

  static isAuthError(error: unknown): boolean {
    const appError = this.handle(error);
    return (
      appError.statusCode === 401 ||
      appError.statusCode === 403 ||
      appError.code === 'AUTH_ERROR'
    );
  }

  static isValidationError(error: unknown): boolean {
    const appError = this.handle(error);
    return (
      appError.statusCode === 400 ||
      appError.code === 'VALIDATION_ERROR'
    );
  }
}

export const createErrorBoundary = (errorHandler: (error: Error) => void) => {
  return (error: Error) => {
    AppErrorHandler.logError(error, 'ErrorBoundary');
    errorHandler(error);
  };
};

