/**
 * Supabase Edge Function: Process Contribution
 * Handles micro-contribution processing and payment initiation
 */

import { serve } from 'https://deno.land/std@0.168.0/http/server.ts';
import { createClient } from 'https://esm.sh/@supabase/supabase-js@2';

const supabaseUrl = Deno.env.get('SUPABASE_URL')!;
const supabaseKey = Deno.env.get('SUPABASE_SERVICE_ROLE_KEY')!;
const supabase = createClient(supabaseUrl, supabaseKey);

interface ProcessContributionRequest {
  contributionId: string;
  userId: string;
  amount: number;
  paymentMethodId: string;
}

serve(async (req) => {
  // Handle CORS
  if (req.method === 'OPTIONS') {
    return new Response('ok', {
      headers: {
        'Access-Control-Allow-Origin': '*',
        'Access-Control-Allow-Methods': 'POST',
        'Access-Control-Allow-Headers': 'authorization, x-client-info, apikey, content-type',
      },
    });
  }

  try {
    // Verify authorization
    const authHeader = req.headers.get('Authorization');
    if (!authHeader) {
      return new Response(
        JSON.stringify({ error: 'Unauthorized' }),
        { status: 401, headers: { 'Content-Type': 'application/json' } }
      );
    }

    const body: ProcessContributionRequest = await req.json();
    const { contributionId, userId, amount, paymentMethodId } = body;

    // Validate input
    if (!contributionId || !userId || !amount || !paymentMethodId) {
      return new Response(
        JSON.stringify({ error: 'Missing required fields' }),
        { status: 400, headers: { 'Content-Type': 'application/json' } }
      );
    }

    // Get contribution details
    const { data: contribution, error: fetchError } = await supabase
      .from('micro_contributions')
      .select('*')
      .eq('id', contributionId)
      .eq('user_id', userId)
      .single();

    if (fetchError || !contribution) {
      return new Response(
        JSON.stringify({ error: 'Contribution not found' }),
        { status: 404, headers: { 'Content-Type': 'application/json' } }
      );
    }

    // Create transaction record
    const { data: transaction, error: transactionError } = await supabase
      .from('transactions')
      .insert({
        user_id: userId,
        micro_contribution_id: contributionId,
        payment_method_id: paymentMethodId,
        amount,
        type: 'contribution',
        status: 'pending',
        description: `Micro-contribution for bill ${contribution.bill_id}`,
      })
      .select()
      .single();

    if (transactionError) {
      return new Response(
        JSON.stringify({ error: 'Failed to create transaction' }),
        { status: 500, headers: { 'Content-Type': 'application/json' } }
      );
    }

    // Here you would integrate with payment processor (Stripe/PayPal)
    // For now, we'll mark it as completed
    const { error: updateError } = await supabase
      .from('micro_contributions')
      .update({
        is_paid: true,
        paid_at: new Date().toISOString(),
        payment_method_id: paymentMethodId,
      })
      .eq('id', contributionId);

    if (updateError) {
      return new Response(
        JSON.stringify({ error: 'Failed to update contribution' }),
        { status: 500, headers: { 'Content-Type': 'application/json' } }
      );
    }

    // Update transaction status
    await supabase
      .from('transactions')
      .update({ status: 'completed' })
      .eq('id', transaction.id);

    return new Response(
      JSON.stringify({
        success: true,
        transactionId: transaction.id,
        message: 'Contribution processed successfully',
      }),
      {
        status: 200,
        headers: { 'Content-Type': 'application/json' },
      }
    );
  } catch (error) {
    console.error('Error processing contribution:', error);
    return new Response(
      JSON.stringify({ error: 'Internal server error' }),
      { status: 500, headers: { 'Content-Type': 'application/json' } }
    );
  }
});

