513	export const useStore = create<AppState>((set, get) => ({
514	  // Initial state - Auth
515	  isAuthenticated: false,
516	  hasCompletedOnboarding: false,
517	  userName: 'Cam',
518	  supabaseUser: null,
519	
520	  // Initial state - Bills
521	  bills: MOCK_BILLS,
522	  buckets: MOCK_BUCKETS,
523	  contributions: MOCK_CONTRIBUTIONS,
524	
525	  // Initial state - User Profile & Accounts
526	  userProfile: MOCK_USER_PROFILE,
527	  linkedAccounts: MOCK_LINKED_ACCOUNTS,
528	  transfers: MOCK_TRANSFERS,
529	  notifications: MOCK_NOTIFICATIONS,
530	  achievements: MOCK_ACHIEVEMENTS,
531	
532	  // Initial state - Settings
533	  autoTransferEnabled: true,
534	  autoTransferFrequency: 'daily',
535	  paySchedule: 'daily',
536	
537	  // Initial state - Loading & Error
538	  isLoading: false,
539	  isInitialized: false,
540	  authError: null,
541	  dataError: null,
542	
543	  // ── Initialization & Sync ────────────────────────────────────────
544	  initialize: async () => {
545	    const state = get();
546	    if (state.isInitialized) return;
547	
548	    set({ isLoading: true });
549	
550	    try {
551	      if (!supabase) {
552	        set({ isLoading: false, isInitialized: true });
553	        return;
554	      }
555	
556	      const { data: { session } } = await supabase.auth.getSession();
557	
558	      if (session?.user) {
559	        set({
560	          isAuthenticated: true,
561	          hasCompletedOnboarding: true,
562	          supabaseUser: session.user,
563	        });
564	        await get().syncFromSupabase();
565	      }
566	
567	      set({ isLoading: false, isInitialized: true });
568	
569	      // Listen for auth changes
570	      if (supabase.auth.onAuthStateChange) {
571	        supabase.auth.onAuthStateChange((event: string, session: any) => {
572	          if (event === 'SIGNED_OUT') {
573	            set({
574	              isAuthenticated: false,
575	              hasCompletedOnboarding: false,
576	              supabaseUser: null,
577	              authError: null,
578	            });
579	          } else if (event === 'SIGNED_IN' && session?.user) {
580	            set({ isAuthenticated: true, supabaseUser: session.user });
581	          }
582	        });
583	      }
584	    } catch (err) {
585	      set({ isLoading: false, isInitialized: true, authError: 'Initialization failed' });
586	    }
587	  },
588	
589	  syncFromSupabase: async () => {
590	    try {
591	      if (!DatabaseServices) {
592	        set({ dataError: 'Database services not available' });
593	        return;
594	      }
595	
596	      const {
597	        ProfileService,
598	        BillService,
599	        BucketService,
600	        ContributionService,
601	        TransferService,
602	        LinkedAccountService,
603	        NotificationService,
604	        AchievementService,
605	      } = DatabaseServices;
606	
607	      const [profileRes, billsRes, bucketsRes, contributionsRes, accountsRes, transfersRes, notificationsRes, achievementsRes] = await Promise.all(
608	        [
609	          ProfileService?.getProfile?.() || Promise.resolve({ data: null }),
610	          BillService?.getBills?.() || Promise.resolve({ data: null }),
611	          BucketService?.getBuckets?.() || Promise.resolve({ data: null }),
612	          ContributionService?.getContributions?.() || Promise.resolve({ data: null }),
613	          LinkedAccountService?.getLinkedAccounts?.() || Promise.resolve({ data: null }),
614	          TransferService?.getTransfers?.() || Promise.resolve({ data: null }),
615	          NotificationService?.getNotifications?.() || Promise.resolve({ data: null }),
616	          AchievementService?.getAchievements?.() || Promise.resolve({ data: null }),
617	        ]
618	      );
619	
620	      const updates: Partial<AppState> = {};
621	
622	      if (profileRes.data) {
623	        updates.userProfile = mapProfile(profileRes.data);
624	        updates.userName = profileRes.data.username || profileRes.data.full_name;
625	        updates.paySchedule = profileRes.data.pay_schedule || 'daily';
626	        updates.autoTransferEnabled = profileRes.data.auto_transfer_enabled ?? true;
627	        updates.autoTransferFrequency = profileRes.data.auto_transfer_frequency || 'daily';
628	      }
629	      if (billsRes.data?.length) updates.bills = billsRes.data.map(mapBill);
630	      if (bucketsRes.data?.length) updates.buckets = bucketsRes.data.map(mapBucket);
631	      if (contributionsRes.data?.length) updates.contributions = contributionsRes.data.map(mapContribution);
632	      if (accountsRes.data?.length) updates.linkedAccounts = accountsRes.data.map(mapLinkedAccount);
633	      if (transfersRes.data?.length) updates.transfers = transfersRes.data.map(mapTransfer);
634	      if (notificationsRes.data?.length) updates.notifications = notificationsRes.data.map(mapNotification);
635	      if (achievementsRes.data?.length) updates.achievements = achievementsRes.data.map(mapAchievement);
636	
637	      set(updates);
638	    } catch (err) {
639	      set({ dataError: 'Failed to sync data from Supabase' });
640	    }
641	  },
642	
643	  // ── Bill Actions (Sync) ────────────────────────────────────────
644	  addBill: (billData) => {
645	    const newBill: Bill = {
646	      ...billData,
647	      billType: billData.billType || 'recurring',
648	      id: Date.now().toString(),
649	      userId: 'user1',
650	      createdAt: new Date().toISOString(),
651	      updatedAt: new Date().toISOString(),
652	    };
653	    const newBucket: BillBucket = {
654	      id: `b-${Date.now()}`,
655	      billId: newBill.id,
656	      targetAmount: newBill.amount,
657	      currentAmount: 0,
658	      billingPeriod: new Date(2026, 3, 1).toISOString(),
659	      status: 'funding',
660	    };
661	    set((state) => ({
662	      bills: [...state.bills, newBill],
663	      buckets: [...state.buckets, newBucket],
664	    }));
665	  },
666	
667	  updateBill: (id, updates) =>
668	    set((state) => ({
669	      bills: state.bills.map((b) =>
670	        b.id === id ? { ...b, ...updates, updatedAt: new Date().toISOString() } : b
671	      ),
672	    })),
673	
674	  deleteBill: (id) =>
675	    set((state) => ({
676	      bills: state.bills.filter((b) => b.id !== id),
677	      buckets: state.buckets.filter((b) => b.billId !== id),
678	    })),
679	
