1	import React from 'react';
2	import { View, Text, StyleSheet, TouchableOpacity } from 'react-native';
3	import { colors, spacing, borderRadius, fontSizes, fontWeights } from '../theme';
4	import { Bill, BillBucket } from '../types/bill';
