6	import { StatusBadge } from './StatusBadge';
7	import { formatCurrency, getNextDueDate, formatDate, getFundedPercent } from '../utils/calculations';
8	
9	interface Props {
10	  bill: Bill;
11	  bucket?: BillBucket;
12	  onPress?: () => void;
13	}
14	
15	export function BillCard({ bill, bucket, onPress }: Props) {
16	  const fundedPercent = bucket ? getFundedPercent(bucket.currentAmount, bucket.targetAmount) : 0;
17	  const dueDate = getNextDueDate(bill.dueDay);
18	  
19	  // Determine status based on funded percentage
20	  const getStatus = () => {
21	    if (fundedPercent >= 100) return 'completed';
22	    if (fundedPercent >= 80) return 'on_track';
23	    if (fundedPercent >= 50) return 'current';
24	    return 'behind';
25	  };
26	
27	  return (
28	    <TouchableOpacity 
29	      style={styles.card} 
30	      onPress={onPress} 
31	      activeOpacity={0.7}
32	    >
33	      <View style={styles.topRow}>
34	        <View style={styles.billNameContainer}>
35	          <Text style={styles.billName}>{bill.name}</Text>
36	          <Text style={styles.dueDate}>Due {formatDate(dueDate)}</Text>
37	        </View>
38	        <StatusBadge status={getStatus() as any} />
39	      </View>
40	
41	      <View style={styles.amountRow}>
42	        <Text style={styles.amount}>{formatCurrency(bill.amount)}</Text>
43	      </View>
44	
45	      <View style={styles.progressContainer}>
46	        <ProgressBar 
47	          progress={fundedPercent / 100} 
48	          height={6}
49	          color={colors.success}
50	        />
51	      </View>
52	
53	      <View style={styles.fundedRow}>
54	        <Text style={styles.fundedText}>{fundedPercent.toFixed(0)}% funded</Text>
55	      </View>
56	    </TouchableOpacity>
57	  );
58	}
