1	import React from 'react';
2	import {
3	  TouchableOpacity,
4	  Text,
5	  StyleSheet,
6	  ViewStyle,
7	  ActivityIndicator,
8	  LinearGradient,
9	} from 'react-native';
10	import { colors, spacing, borderRadius, fontSizes, fontWeights } from '../theme';
11	
12	interface Props {
13	  title: string;
14	  onPress: () => void;
15	  variant?: 'primary' | 'secondary' | 'outline' | 'danger';
16	  loading?: boolean;
17	  disabled?: boolean;
18	  style?: ViewStyle;
19	  size?: 'sm' | 'md' | 'lg';
20	}
21	
22	export function GradientButton({
23	  title,
24	  onPress,
25	  variant = 'primary',
26	  loading = false,
27	  disabled = false,
28	  style,
29	  size = 'md',
30	}: Props) {
31	  const isDisabled = disabled || loading;
32	
33	  const handlePress = () => {
34	    if (!isDisabled) {
35	      onPress();
36	    }
37	  };
38	
39	  // Determine button content based on variant
40	  const renderButton = () => {
41	    const textStyles = [
42	      styles.text,
43	      styles[`text_${variant}`],
44	      styles[`textSize_${size}`],
45	    ];
46	
47	    const content = loading ? (
48	      <ActivityIndicator
49	        color={
50	          variant === 'outline' ? colors.primary : variant === 'danger' ? colors.error : colors.textPrimary
51	        }
52	        size="small"
53	      />
54	    ) : (
55	      <Text style={textStyles}>{title}</Text>
56	    );
57	
58	    // Primary variant with gradient
59	    if (variant === 'primary') {
60	      return (
61	        <LinearGradient
62	          colors={[colors.primaryGradientStart, colors.primaryGradientEnd]}
63	          start={{ x: 0, y: 0 }}
64	          end={{ x: 1, y: 1 }}
65	          style={[styles.base, styles[`size_${size}`], isDisabled && styles.disabled, style]}
66	        >
67	          {content}
68	        </LinearGradient>
69	      );
70	    }
71	
72	    // Other variants without gradient
73	    const baseStyle = [
74	      styles.base,
75	      styles[variant],
76	      styles[`size_${size}`],
77	      isDisabled && styles.disabled,
78	      style,
79	    ];
80	
81	    return (
82	      <TouchableOpacity
83	        style={baseStyle}
84	        onPress={handlePress}
85	        disabled={isDisabled}
86	        activeOpacity={0.8}
87	      >
88	        {content}
89	      </TouchableOpacity>
90	    );
91	  };
92	
93	  // Wrap primary button in TouchableOpacity for press handling
94	  if (variant === 'primary') {
95	    return (
96	      <TouchableOpacity
97	        onPress={handlePress}
98	        disabled={isDisabled}
99	        activeOpacity={0.8}
100	      >
101	        {renderButton()}
102	      </TouchableOpacity>
103	    );
104	  }
105	
106	  return renderButton();
107	}
