  FlatList,
} from 'react-native';
import { colors, spacing, borderRadius, fontSizes, fontWeights } from '../theme';

interface Props {
  navigation: any;
  route?: any;
}

const BANKS = [
  { id: '1', name: 'Chase Bank' },
  { id: '2', name: 'Bank of America' },
  { id: '3', name: 'Wells Fargo' },
  { id: '4', name: 'Citi' },
  { id: '5', name: 'Capital One' },
  { id: '6', name: 'Ally Bank' },
  { id: '7', name: 'TD Bank' },
  { id: '8', name: 'US Bank' },
];

export function BankListScreen({ navigation }: Props) {
  const [searchQuery, setSearchQuery] = useState('');
  const [selectedBank, setSelectedBank] = useState<string | null>(null);

  const filteredBanks = BANKS.filter(bank =>
    bank.name.toLowerCase().includes(searchQuery.toLowerCase())
  );

  const handleSelect = () => {
    if (selectedBank) {
      const bank = BANKS.find(b => b.id === selectedBank);
      navigation.navigate('BankDetails', { selectedBank: bank });
    }
  };

  return (
    <SafeAreaView style={styles.container}>
      {/* Header */}
      <View style={styles.header}>
        <TouchableOpacity onPress={() => navigation.goBack()}>
          <Text style={styles.backBtn}>← Back</Text>
        </TouchableOpacity>
        <Text style={styles.headerTitle}>Bank List</Text>
        <View style={{ width: 50 }} />
      </View>

      {/* Search Bar */}
      <View style={styles.searchContainer}>
        <TextInput
          style={styles.searchInput}
          placeholder="Search banks..."
          placeholderTextColor={colors.textMuted}
          value={searchQuery}
          onChangeText={setSearchQuery}
        />
      </View>

      {/* Bank List */}
      <FlatList
        data={filteredBanks}
        keyExtractor={item => item.id}
        scrollEnabled={false}
        contentContainerStyle={styles.listContent}
        renderItem={({ item }) => (
          <TouchableOpacity
            style={[
              styles.bankItem,
              selectedBank === item.id && styles.bankItemSelected,
            ]}
            onPress={() => setSelectedBank(item.id)}
          >
            <View style={styles.bankIcon}>
              <Text style={styles.bankIconText}>🏦</Text>
            </View>
            <Text style={styles.bankName}>{item.name}</Text>
          </TouchableOpacity>
        )}
      />

      {/* Select Button */}
      <View style={styles.footer}>
        <TouchableOpacity
          style={[
            styles.selectButton,
            !selectedBank && styles.selectButtonDisabled,
          ]}
          onPress={handleSelect}
          disabled={!selectedBank}
        >
          <Text style={styles.selectButtonText}>Select</Text>
        </TouchableOpacity>
      </View>
    </SafeAreaView>
  );
}

