/**
 * Theme system for Fractional Bill Pay
 * Centralized export of all theme-related values
 */

export { colors, type ColorKey } from './colors';
export { typography, type TypographyKey } from './typography';
export { spacing, borderRadius, screenPadding, type SpacingKey, type BorderRadiusKey } from './spacing';

// Re-export as unified theme object for convenience
export { colors as themeColors } from './colors';
export { typography as themeTypography } from './typography';
export { spacing as themeSpacing, borderRadius as themeBorderRadius, screenPadding as themeScreenPadding } from './spacing';

/**
 * Typography system for Fractional Bill Pay
 * Includes font sizes, weights, and line heights
 */

export const typography = {
  // Heading styles
  h1: {
    fontSize: 32,
    fontWeight: '700' as const,
    lineHeight: 40,
    letterSpacing: -0.5,
  },
  h2: {
    fontSize: 28,
    fontWeight: '700' as const,
    lineHeight: 36,
    letterSpacing: -0.3,
  },
  h3: {
    fontSize: 24,
    fontWeight: '600' as const,
    lineHeight: 32,
    letterSpacing: -0.2,
  },
  h4: {
    fontSize: 20,
    fontWeight: '600' as const,
    lineHeight: 28,
    letterSpacing: 0,
  },

  // Body styles
  bodyLarge: {
    fontSize: 16,
    fontWeight: '500' as const,
    lineHeight: 24,
    letterSpacing: 0.15,
  },
  body: {
    fontSize: 14,
    fontWeight: '400' as const,
    lineHeight: 22,
    letterSpacing: 0.25,
  },
  bodySmall: {
    fontSize: 12,
    fontWeight: '400' as const,
    lineHeight: 18,
    letterSpacing: 0.4,
  },

  // Caption style
  caption: {
    fontSize: 11,
    fontWeight: '400' as const,
    lineHeight: 16,
    letterSpacing: 0.5,
  },

  // Overline style
  overline: {
    fontSize: 10,
    fontWeight: '600' as const,
    lineHeight: 16,
    letterSpacing: 1.5,
    textTransform: 'uppercase' as const,
  },
} as const;

export type TypographyKey = keyof typeof typography;

/**
 * Spacing system for Fractional Bill Pay
 * Includes spacing values, border radius, and screen padding
 */

export const spacing = {
  xs: 4,
  sm: 8,
  md: 12,
  lg: 16,
  xl: 20,
  '2xl': 24,
  '3xl': 32,
  '4xl': 40,
  '5xl': 48,
  '6xl': 64,
} as const;

export const borderRadius = {
  xs: 6,
  sm: 8,
  md: 12,
  lg: 16,
  xl: 20,
  full: 9999,
} as const;

export const screenPadding = {
  horizontal: 20,
  vertical: 16,
} as const;

export type SpacingKey = keyof typeof spacing;
export type BorderRadiusKey = keyof typeof borderRadius;

