  title: string;
  message: string;
  read: boolean;
  createdAt: string;
}

export interface UserProfile {
  id: string;
  username: string;
  email: string;
  avatarUrl?: string;
  plan: 'freemium' | 'premium';
  streakDays: number;
  employerLinked: boolean;
}
```

## 4. Create src/utils/calculations.ts

Screens import `formatCurrency` from '../utils/calculations':
```typescript
export function formatCurrency(amount: number): string {
  return '$' + amount.toFixed(2).replace(/\B(?=(\d{3})+(?!\d))/g, ',');
}

export function formatCurrencyShort(amount: number): string {
  if (amount >= 1000) return '$' + (amount / 1000).toFixed(1) + 'k';
  return '$' + amount.toFixed(0);
}

export function calculateDailyContribution(amount: number, daysRemaining: number): number {
  if (daysRemaining <= 0) return amount;
  return Math.ceil((amount / daysRemaining) * 100) / 100;
}

export function calculateWeeklyContribution(amount: number, weeksRemaining: number): number {
  if (weeksRemaining <= 0) return amount;
  return Math.ceil((amount / weeksRemaining) * 100) / 100;
}

export function calculateBiweeklyContribution(amount: number, periodsRemaining: number): number {
  if (periodsRemaining <= 0) return amount;
  return Math.ceil((amount / periodsRemaining) * 100) / 100;
}

export function calculateProgress(current: number, target: number): number {
  if (target <= 0) return 0;
  return Math.min(Math.round((current / target) * 100), 100);
}

export function getDaysUntilDue(dueDay: number): number {
  const today = new Date();
  const currentDay = today.getDate();
  if (dueDay >= currentDay) return dueDay - currentDay;
  const daysInMonth = new Date(today.getFullYear(), today.getMonth() + 1, 0).getDate();
  return daysInMonth - currentDay + dueDay;
}

export function getBillStatus(progress: number, daysUntil: number): 'on_track' | 'behind' | 'completed' {
  if (progress >= 100) return 'completed';
  const expectedProgress = Math.max(0, 100 - (daysUntil / 30) * 100);
  return progress >= expectedProgress * 0.8 ? 'on_track' : 'behind';
}
```

## 5. Create src/services/auth.ts
```typescript
import { supabase } from './supabase';

export const AuthService = {
  async signUp(email: string, password: string, fullName: string) {
    const { data, error } = await supabase.auth.signUp({
      email,
      password,
      options: { data: { full_name: fullName } },
    });
    return { data, error };
  },

  async signIn(email: string, password: string) {
    const { data, error } = await supabase.auth.signInWithPassword({ email, password });
    return { data, error };
  },

  async signOut() {
    const { error } = await supabase.auth.signOut();
    return { error };
  },

  async resetPassword(email: string) {
    const { data, error } = await supabase.auth.resetPasswordForEmail(email);
    return { data, error };
  },

  async getSession() {
    const { data, error } = await supabase.auth.getSession();
    return { data: data?.session, error };
  },

  onAuthStateChange(callback: (event: string, session: any) => void) {
    return supabase.auth.onAuthStateChange(callback);
  },
};
```

