## 4. Create src/utils/calculations.ts

Screens import `formatCurrency` from '../utils/calculations':
```typescript
export function formatCurrency(amount: number): string {
  return '$' + amount.toFixed(2).replace(/\B(?=(\d{3})+(?!\d))/g, ',');
}

export function formatCurrencyShort(amount: number): string {
  if (amount >= 1000) return '$' + (amount / 1000).toFixed(1) + 'k';
  return '$' + amount.toFixed(0);
}

export function calculateDailyContribution(amount: number, daysRemaining: number): number {
  if (daysRemaining <= 0) return amount;
  return Math.ceil((amount / daysRemaining) * 100) / 100;
}

export function calculateWeeklyContribution(amount: number, weeksRemaining: number): number {
  if (weeksRemaining <= 0) return amount;
  return Math.ceil((amount / weeksRemaining) * 100) / 100;
}

export function calculateBiweeklyContribution(amount: number, periodsRemaining: number): number {
  if (periodsRemaining <= 0) return amount;
  return Math.ceil((amount / periodsRemaining) * 100) / 100;
}

export function calculateProgress(current: number, target: number): number {
  if (target <= 0) return 0;
  return Math.min(Math.round((current / target) * 100), 100);
}

export function getDaysUntilDue(dueDay: number): number {
  const today = new Date();
  const currentDay = today.getDate();
  if (dueDay >= currentDay) return dueDay - currentDay;
  const daysInMonth = new Date(today.getFullYear(), today.getMonth() + 1, 0).getDate();
  return daysInMonth - currentDay + dueDay;
}

export function getBillStatus(progress: number, daysUntil: number): 'on_track' | 'behind' | 'completed' {
  if (progress >= 100) return 'completed';
  const expectedProgress = Math.max(0, 100 - (daysUntil / 30) * 100);
  return progress >= expectedProgress * 0.8 ? 'on_track' : 'behind';
}
```

## 5. Create src/services/auth.ts
```typescript
import { supabase } from './supabase';

export const AuthService = {
  async signUp(email: string, password: string, fullName: string) {
    const { data, error } = await supabase.auth.signUp({
      email,
      password,
      options: { data: { full_name: fullName } },
    });
    return { data, error };
  },

  async signIn(email: string, password: string) {
    const { data, error } = await supabase.auth.signInWithPassword({ email, password });
    return { data, error };
  },

  async signOut() {
    const { error } = await supabase.auth.signOut();
    return { error };
  },

  async resetPassword(email: string) {
    const { data, error } = await supabase.auth.resetPasswordForEmail(email);
    return { data, error };
  },

  async getSession() {
    const { data, error } = await supabase.auth.getSession();
    return { data: data?.session, error };
  },

  onAuthStateChange(callback: (event: string, session: any) => void) {
    return supabase.auth.onAuthStateChange(callback);
  },
};
```

## 6. Create src/services/database.ts

Create a comprehensive database service with ProfileService, BillService, BucketService, ContributionService, TransferService, LinkedAccountService, NotificationService, AchievementService. Each service should have CRUD methods using supabase client. Pattern:
```typescript
import { supabase } from './supabase';

export const ProfileService = {
  async get(userId: string) {
    return supabase.from('profiles').select('*').eq('id', userId).single();
  },
  async update(userId: string, data: any) {
    return supabase.from('profiles').update(data).eq('id', userId);
  },
};

// ... similar for all other services
```

Create complete CRUD for: bills, bill_buckets, contributions, linked_accounts, transfers, notifications, achievements.

## 7. Create src/services/payments.ts

Based on the PAYMENT_IMPLEMENTATION_SUMMARY.md the user uploaded, create a unified PaymentService:
```typescript
import { supabase } from './supabase';

export type PaymentProvider = 'stripe' | 'paypal' | 'apple_pay';
export type PaymentStatus = 'pending' | 'processing' | 'completed' | 'failed' | 'refunded';

export interface PaymentMethod { id: string; type: PaymentProvider; lastFour: string; brand?: string; isDefault: boolean; }
export interface PaymentIntent { id: string; clientSecret: string; amount: number; currency: string; status: PaymentStatus; }
export interface PaymentResult { success: boolean; transactionId?: string; error?: string; }
export interface CreatePaymentParams { amount: number; currency?: string; provider: PaymentProvider; paymentMethodId?: string; description?: string; metadata?: Record<string, string>; }

export const PaymentService = {
  async getPaymentMethods() { ... },
  async addPaymentMethod(provider: PaymentProvider, token: string) { ... },
  async removePaymentMethod(id: string) { ... },
  async setDefaultPaymentMethod(id: string) { ... },
  async createPayment(params: CreatePaymentParams) { ... },
  async confirmPayment(intentId: string, provider: PaymentProvider, paymentMethodId?: string) { ... },
  async getPaymentStatus(intentId: string, provider: PaymentProvider) { ... },
  async createSubscription(params: { provider: PaymentProvider; priceId: string; paymentMethodId?: string }) { ... },
  async cancelSubscription(subscriptionId: string) { ... },
  async getSubscriptionStatus() { ... },
  async isApplePayAvailable() { ... },
  async createApplePayPayment(amount: number, description: string) { ... },
};
```

Each method should call the appropriate Supabase edge function. Implement all methods fully.

## 8. Create src/services/index.ts
```typescript
export { supabase } from './supabase';
export { AuthService } from './auth';
export { ProfileService, BillService, BucketService, ContributionService, TransferService, LinkedAccountService, NotificationService, AchievementService } from './database';
export { PaymentService } from './payments';
export type { PaymentProvider, PaymentStatus, PaymentMethod, PaymentIntent, PaymentResult, CreatePaymentParams } from './payments';
```

Write all files with complete, working TypeScript code.

