/**
 * Bill-related type definitions for Fractional Bill Pay
 */

export type Cadence = 'daily' | 'weekly' | 'biweekly' | 'monthly';
export type BillStatus = 'on_track' | 'behind' | 'completed' | 'upcoming' | 'paid' | 'funding';

export interface Bill {
  id: string;
  userId: string;
  name: string;
  amount: number;
  dueDay: number;
  dueDate: string;
  billType: 'recurring' | 'one-time';
  category: string;
  icon: string;
  isActive: boolean;
  autoPay: boolean;
  cadence: Cadence;
  createdAt: string;
  updatedAt: string;
}

export interface BillBucket {
  id: string;
  billId: string;
  targetAmount: number;
  currentAmount: number;
  billingPeriod: string;
  status: 'funding' | 'paid' | 'overdue';
  paidAt?: string;
}

export interface Contribution {
  id: string;
  billId: string;
  bucketId: string;
  amount: number;
  status: 'pending' | 'completed' | 'failed';
  executedAt: string;
  createdAt: string;
}

export interface LinkedAccount {
  id: string;
  bankName: string;
  accountMask: string;
  accountType: 'checking' | 'savings' | 'credit';
  isPrimary: boolean;
  institutionId: string;
  createdAt: string;
}

export interface Transfer {
  id: string;
  billId: string;
  billName: string;
  amount: number;
  date: string;
  status: 'success' | 'pending' | 'failed';
  fundingSource: string;
}

export interface Achievement {
  id: string;
  name: string;
  description: string;
  icon: string;
  unlocked: boolean;
  unlockedAt?: string;
}

export interface Notification {
  id: string;
  type: 'contribution_reminder' | 'due_date' | 'missed_contribution' | 'system' | 'achievement';
  title: string;
  message: string;
  read: boolean;
  createdAt: string;
}

export interface UserProfile {
  id: string;
  username: string;
  email: string;
  avatarUrl?: string;
  plan: 'freemium' | 'premium';
  streakDays: number;
  employerLinked: boolean;
}

/**
 * Calculation utilities for Fractional Bill Pay
 */

export function formatCurrency(amount: number): string {
  return '$' + amount.toFixed(2).replace(/\B(?=(\d{3})+(?!\d))/g, ',');
}

export function formatCurrencyShort(amount: number): string {
  if (amount >= 1000) return '$' + (amount / 1000).toFixed(1) + 'k';
  return '$' + amount.toFixed(0);
}

export function calculateDailyContribution(amount: number, daysRemaining: number): number {
  if (daysRemaining <= 0) return amount;
  return Math.ceil((amount / daysRemaining) * 100) / 100;
}

export function calculateWeeklyContribution(amount: number, weeksRemaining: number): number {
  if (weeksRemaining <= 0) return amount;
  return Math.ceil((amount / weeksRemaining) * 100) / 100;
}

export function calculateBiweeklyContribution(amount: number, periodsRemaining: number): number {
  if (periodsRemaining <= 0) return amount;
  return Math.ceil((amount / periodsRemaining) * 100) / 100;
}

export function calculateProgress(current: number, target: number): number {
  if (target <= 0) return 0;
  return Math.min(Math.round((current / target) * 100), 100);
}

export function getDaysUntilDue(dueDay: number): number {
  const today = new Date();
  const currentDay = today.getDate();
  if (dueDay >= currentDay) return dueDay - currentDay;
  const daysInMonth = new Date(today.getFullYear(), today.getMonth() + 1, 0).getDate();
  return daysInMonth - currentDay + dueDay;
}

export function getBillStatus(progress: number, daysUntil: number): 'on_track' | 'behind' | 'completed' {
  if (progress >= 100) return 'completed';
  const expectedProgress = Math.max(0, 100 - (daysUntil / 30) * 100);
  return progress >= expectedProgress * 0.8 ? 'on_track' : 'behind';
}

export function getNextDueDate(dueDay: number): string {
  const today = new Date();
  const currentDay = today.getDate();

  if (dueDay >= currentDay) {
    return new Date(today.getFullYear(), today.getMonth(), dueDay).toISOString();
  }

  const nextMonth = new Date(today.getFullYear(), today.getMonth() + 1, dueDay);
  return nextMonth.toISOString();
}

export function formatDate(dateString: string): string {
  const date = new Date(dateString);
  return date.toLocaleDateString('en-US', { month: 'short', day: 'numeric', year: 'numeric' });
}

export function getFundedPercent(current: number, target: number): number {
  if (target <= 0) return 0;
  return Math.min(Math.round((current / target) * 100), 100);
}

