/**
 * Database service layer for Fractional Bill Pay
 * Provides CRUD operations for all database tables
 */

import { supabase } from './supabase';

// ============================================================================
// PROFILE SERVICE
// ============================================================================

export const ProfileService = {
  async get(userId: string) {
    return supabase.from('profiles').select('*').eq('id', userId).single();
  },

  async update(userId: string, data: Record<string, any>) {
    return supabase.from('profiles').update(data).eq('id', userId).select().single();
  },

  async create(userId: string, data: Record<string, any>) {
    return supabase.from('profiles').insert({ id: userId, ...data }).select().single();
  },

  async delete(userId: string) {
    return supabase.from('profiles').delete().eq('id', userId);
  },
};

// ============================================================================
// BILL SERVICE
// ============================================================================

export const BillService = {
  async create(userId: string, data: Record<string, any>) {
    return supabase
      .from('bills')
      .insert({ ...data, user_id: userId })
      .select()
      .single();
  },

  async get(billId: string) {
    return supabase.from('bills').select('*').eq('id', billId).single();
  },

  async list(userId: string) {
    return supabase
      .from('bills')
      .select('*')
      .eq('user_id', userId)
      .eq('is_active', true)
      .order('due_date', { ascending: true });
  },

  async listAll(userId: string) {
    return supabase
      .from('bills')
      .select('*')
      .eq('user_id', userId)
      .order('due_date', { ascending: true });
  },

  async update(billId: string, data: Record<string, any>) {
    return supabase.from('bills').update(data).eq('id', billId).select().single();
  },

  async delete(billId: string) {
    return supabase.from('bills').update({ is_active: false }).eq('id', billId);
  },

  async permanentDelete(billId: string) {
    return supabase.from('bills').delete().eq('id', billId);
  },
};

