// ============================================================================
// LINKED ACCOUNT SERVICE
// ============================================================================

export const LinkedAccountService = {
  async create(userId: string, data: Record<string, any>) {
    return supabase
      .from('linked_accounts')
      .insert({ ...data, user_id: userId })
      .select()
      .single();
  },

  async get(accountId: string) {
    return supabase.from('linked_accounts').select('*').eq('id', accountId).single();
  },

  async list(userId: string) {
    return supabase.from('linked_accounts').select('*').eq('user_id', userId);
  },

  async getPrimary(userId: string) {
    return supabase
      .from('linked_accounts')
      .select('*')
      .eq('user_id', userId)
      .eq('is_primary', true)
      .single();
  },

  async update(accountId: string, data: Record<string, any>) {
    return supabase
      .from('linked_accounts')
      .update(data)
      .eq('id', accountId)
      .select()
      .single();
  },

  async delete(accountId: string) {
    return supabase.from('linked_accounts').delete().eq('id', accountId);
  },

  async setPrimary(accountId: string, userId: string) {
    // First, unset all other primary accounts
    await supabase
      .from('linked_accounts')
      .update({ is_primary: false })
      .eq('user_id', userId);

    // Then set the specified account as primary
    return supabase
      .from('linked_accounts')
      .update({ is_primary: true })
      .eq('id', accountId)
      .select()
      .single();
  },
};

// ============================================================================
// NOTIFICATION SERVICE
// ============================================================================

export const NotificationService = {
