/**
 * Payment service for Fractional Bill Pay
 * Handles payment operations across multiple providers (Stripe, PayPal, Apple Pay)
 */

import { supabase } from './supabase';

export type PaymentProvider = 'stripe' | 'paypal' | 'apple_pay';
export type PaymentStatus = 'pending' | 'processing' | 'completed' | 'failed' | 'refunded';

export interface PaymentMethod {
  id: string;
  type: PaymentProvider;
  lastFour: string;
  brand?: string;
  isDefault: boolean;
}

export interface PaymentIntent {
  id: string;
  clientSecret: string;
  amount: number;
  currency: string;
  status: PaymentStatus;
}

export interface PaymentResult {
  success: boolean;
  transactionId?: string;
  error?: string;
}

export interface CreatePaymentParams {
  amount: number;
  currency?: string;
  provider: PaymentProvider;
  paymentMethodId?: string;
  description?: string;
  metadata?: Record<string, string>;
}

export const PaymentService = {
  /**
   * Get all payment methods for the current user
   */
  async getPaymentMethods(): Promise<PaymentMethod[]> {
    try {
      const { data, error } = await supabase.functions.invoke('payment-methods', {
        body: { action: 'list' },
      });

      if (error) throw error;
      return data.paymentMethods || [];
    } catch (err) {
      console.error('Failed to get payment methods:', err);
      return [];
    }
  },

  /**
   * Add a new payment method
   */
  async addPaymentMethod(
    provider: PaymentProvider,
    token: string
  ): Promise<PaymentResult> {
    try {
      const { data, error } = await supabase.functions.invoke('payment-methods', {
        body: {
          action: 'add',
          provider,
          token,
        },
      });

      if (error) throw error;
      return {
        success: true,
        transactionId: data.paymentMethodId,
      };
    } catch (err: any) {
      return {
        success: false,
        error: err.message || 'Failed to add payment method',
      };
    }
  },

  /**
   * Remove an existing payment method
   */
  async removePaymentMethod(id: string): Promise<PaymentResult> {
    try {
      const { error } = await supabase.functions.invoke('payment-methods', {
        body: {
          action: 'remove',
          paymentMethodId: id,
        },
      });

      if (error) throw error;
      return { success: true };
    } catch (err: any) {
      return {
        success: false,
        error: err.message || 'Failed to remove payment method',
      };
    }
  },

  /**
   * Set a payment method as default
   */
  async setDefaultPaymentMethod(id: string): Promise<PaymentResult> {
    try {
      const { error } = await supabase.functions.invoke('payment-methods', {
        body: {
          action: 'setDefault',
          paymentMethodId: id,
        },
      });

      if (error) throw error;
      return { success: true };
    } catch (err: any) {
      return {
        success: false,
        error: err.message || 'Failed to set default payment method',
      };
    }
  },

  /**
   * Create a payment intent
   */
  async createPayment(params: CreatePaymentParams): Promise<PaymentIntent | null> {
    try {
      const { data, error } = await supabase.functions.invoke('create-payment', {
        body: {
          amount: params.amount,
          currency: params.currency || 'USD',
          provider: params.provider,
          paymentMethodId: params.paymentMethodId,
          description: params.description,
          metadata: params.metadata,
        },
      });

      if (error) throw error;

      return {
        id: data.id,
        clientSecret: data.clientSecret,
        amount: params.amount,
        currency: params.currency || 'USD',
        status: 'pending',
      };
    } catch (err) {
      console.error('Failed to create payment:', err);
      return null;
    }
  },

  /**
   * Confirm a payment intent
   */
  async confirmPayment(
    intentId: string,
    provider: PaymentProvider,
    paymentMethodId?: string
  ): Promise<PaymentResult> {
    try {
      const { data, error } = await supabase.functions.invoke('confirm-payment', {
        body: {
          intentId,
          provider,
          paymentMethodId,
        },
      });

      if (error) throw error;

      return {
        success: data.status === 'completed',
        transactionId: data.id,
        error: data.error,
      };
    } catch (err: any) {
      return {
        success: false,
        error: err.message || 'Failed to confirm payment',
      };
    }
  },

  /**
   * Get payment status
   */
  async getPaymentStatus(
    intentId: string,
    provider: PaymentProvider
  ): Promise<PaymentStatus | null> {
    try {
      const { data, error } = await supabase.functions.invoke('get-payment-status', {
        body: { intentId, provider },
      });

      if (error) throw error;
      return data.status;
    } catch (err) {
      console.error('Failed to get payment status:', err);
      return null;
    }
  },

  /**
   * Create a subscription
   */
  async createSubscription(params: {
    provider: PaymentProvider;
    priceId: string;
    paymentMethodId?: string;
  }): Promise<PaymentResult> {
    try {
      const { data, error } = await supabase.functions.invoke('create-subscription', {
        body: {
          provider: params.provider,
          priceId: params.priceId,
          paymentMethodId: params.paymentMethodId,
        },
      });

      if (error) throw error;

      return {
        success: true,
        transactionId: data.subscriptionId,
      };
    } catch (err: any) {
      return {
        success: false,
        error: err.message || 'Failed to create subscription',
      };
    }
  },

  /**
   * Cancel a subscription
   */
  async cancelSubscription(subscriptionId: string): Promise<PaymentResult> {
    try {
      const { error } = await supabase.functions.invoke('cancel-subscription', {
        body: { subscriptionId },
      });

      if (error) throw error;
      return { success: true };
    } catch (err: any) {
      return {
        success: false,
        error: err.message || 'Failed to cancel subscription',
      };
    }
  },

  /**
   * Get current subscription status
   */
  async getSubscriptionStatus(): Promise<{
    active: boolean;
    plan?: string;
    expiresAt?: string;
    canceledAt?: string;
  }> {
    try {
      const { data, error } = await supabase.functions.invoke('get-subscription-status', {
        body: {},
      });

      if (error) throw error;
      return data;
    } catch (err) {
      console.error('Failed to get subscription status:', err);
      return { active: false };
    }
  },

  /**
   * Check if Apple Pay is available
   */
  async isApplePayAvailable(): Promise<boolean> {
    try {
      const { data, error } = await supabase.functions.invoke('apple-pay-status', {
        body: {},
      });

      if (error) return false;
      return data.available === true;
    } catch {
      return false;
    }
  },

  /**
   * Create an Apple Pay payment
   */
  async createApplePayPayment(
    amount: number,
    description: string
  ): Promise<PaymentResult> {
    try {
      const { data, error } = await supabase.functions.invoke('create-apple-pay-payment', {
        body: {
          amount,
          description,
        },
      });

      if (error) throw error;

      return {
        success: data.status === 'completed',
        transactionId: data.transactionId,
        error: data.error,
      };
    } catch (err: any) {
      return {
        success: false,
        error: err.message || 'Failed to create Apple Pay payment',
      };
    }
  },
};

