import React, { useState } from 'react';
import { View, Text, StyleSheet, TouchableOpacity, SafeAreaView, ScrollView, TextInput } from 'react-native';
import { colors, spacing, fontSizes, borderRadius } from '../theme';

interface Props {
  navigation: any;
  route: any;
}

interface DetectedBill {
  id: string;
  name: string;
  amount: number;
  icon: string;
}

export function AddBillScreen({ navigation }: Props) {
  const [billName, setBillName] = useState('');
  const [billAmount, setBillAmount] = useState('');
  const [dueDate, setDueDate] = useState('');
  const [category, setCategory] = useState('Entertainment');
  const [showCategoryDropdown, setShowCategoryDropdown] = useState(false);

  const detectedBills: DetectedBill[] = [
    { id: '1', name: 'Netflix', amount: 15.99, icon: '🎬' },
    { id: '2', name: 'Spotify', amount: 10.99, icon: '🎵' },
    { id: '3', name: 'Gym Membership', amount: 49.99, icon: '💪' },
  ];

  const categories = ['Entertainment', 'Utilities', 'Insurance', 'Housing', 'Transportation', 'Health', 'Subscriptions', 'Other'];

  const handleAddDetectedBill = (bill: DetectedBill) => {
    setBillName(bill.name);
    setBillAmount(bill.amount.toString());
    setCategory('Entertainment');
  };

  const handleAddBill = () => {
    if (billName && billAmount && dueDate) {
      navigation.goBack();
    }
  };

  return (
    <SafeAreaView style={styles.container}>
      {/* Header */}
      <View style={styles.header}>
        <TouchableOpacity onPress={() => navigation.goBack()}>
          <Text style={styles.backButton}>←</Text>
        </TouchableOpacity>
        <Text style={styles.headerTitle}>Add New Bill</Text>
        <View style={{ width: 24 }} />
      </View>

      <ScrollView showsVerticalScrollIndicator={false} style={styles.content}>
        {/* Auto-Detect Section */}
        <View style={styles.section}>
          <Text style={styles.sectionTitle}>Detected Bills</Text>
          <Text style={styles.sectionDescription}>We found these subscriptions on your bank account</Text>

          {detectedBills.map((bill) => (
            <View key={bill.id} style={styles.detectedBillCard}>
              <View style={styles.detectedBillLeft}>
                <Text style={styles.detectedBillIcon}>{bill.icon}</Text>
                <View>
                  <Text style={styles.detectedBillName}>{bill.name}</Text>
                  <Text style={styles.detectedBillAmount}>${bill.amount.toFixed(2)}</Text>
                </View>
              </View>
              <TouchableOpacity
                style={styles.addButton}
                onPress={() => handleAddDetectedBill(bill)}
              >
                <Text style={styles.addButtonText}>Add</Text>
              </TouchableOpacity>
            </View>
          ))}
        </View>

        {/* Manual Entry Section */}
        <View style={styles.section}>
          <Text style={styles.sectionTitle}>Or Add Manually</Text>

          {/* Bill Name */}
          <View style={styles.formGroup}>
            <Text style={styles.label}>Bill Name</Text>
            <TextInput
              style={styles.input}
              placeholder="e.g., Electric Bill, Internet"
              placeholderTextColor={colors.textMuted}
              value={billName}
              onChangeText={setBillName}
            />
          </View>

          {/* Amount */}
          <View style={styles.formGroup}>
            <Text style={styles.label}>Amount</Text>
            <View style={styles.amountContainer}>
              <Text style={styles.currencySymbol}>$</Text>
              <TextInput
                style={styles.amountInput}
                placeholder="0.00"
                placeholderTextColor={colors.textMuted}
                value={billAmount}
                onChangeText={setBillAmount}
                keyboardType="decimal-pad"
              />
            </View>
          </View>

          {/* Due Date */}
          <View style={styles.formGroup}>
            <Text style={styles.label}>Due Date</Text>
            <TouchableOpacity style={styles.input}>
              <Text style={dueDate ? styles.inputText : styles.inputPlaceholder}>
                {dueDate || 'Select date'}
              </Text>
            </TouchableOpacity>
          </View>

          {/* Category */}
          <View style={styles.formGroup}>
            <Text style={styles.label}>Category</Text>
            <TouchableOpacity
              style={styles.input}
              onPress={() => setShowCategoryDropdown(!showCategoryDropdown)}
            >
              <View style={styles.categoryHeader}>
                <Text style={styles.inputText}>{category}</Text>
                <Text style={styles.chevron}>▼</Text>
              </View>
            </TouchableOpacity>

            {showCategoryDropdown && (
              <View style={styles.dropdown}>
                {categories.map((cat) => (
                  <TouchableOpacity
                    key={cat}
                    style={[
                      styles.dropdownItem,
                      cat === category && styles.dropdownItemSelected,
                    ]}
                    onPress={() => {
                      setCategory(cat);
                      setShowCategoryDropdown(false);
                    }}
                  >
                    <Text
                      style={[
                        styles.dropdownItemText,
                        cat === category && styles.dropdownItemTextSelected,
                      ]}
                    >
                      {cat}
                    </Text>
                  </TouchableOpacity>
                ))}
              </View>
            )}
          </View>
        </View>

        <View style={{ height: 20 }} />
      </ScrollView>

      {/* Footer Button */}
      <View style={styles.footer}>
        <TouchableOpacity style={styles.addBillButton} onPress={handleAddBill}>
          <Text style={styles.addBillButtonText}>Add Bill</Text>
        </TouchableOpacity>
      </View>
    </SafeAreaView>
  );
}

