    if (password.length < 12) return 'medium';
    return 'strong';
  };

  const strength = getPasswordStrength(newPassword);
  const strengthColor = {
    weak: colors.error,
    medium: '#FFA500',
    strong: colors.primary,
    none: colors.textMuted,
  }[strength];

  const handleUpdatePassword = () => {
