                </TouchableOpacity>
              </View>
            </View>

            {/* Password Strength Indicator */}
            {newPassword && (
              <View style={styles.strengthContainer}>
                <View style={styles.strengthBars}>
                  <View
                    style={[
                      styles.strengthBar,
                      { backgroundColor: strengthColor },
                    ]}
