            ]}
            onPress={handleUpdatePassword}
            disabled={!(newPassword === confirmPassword && newPassword.length >= 8)}
          >
            <Text style={styles.updateButtonText}>Update Password</Text>
          </TouchableOpacity>
        </ScrollView>
      </KeyboardAvoidingView>
