interface Props {
  navigation: any;
  route: any;
}

interface NotificationSetting {
  id: string;
  label: string;
  description: string;
  enabled: boolean;
}

export function NotificationSettingsScreen({ navigation }: Props) {
  const [settings, setSettings] = useState<NotificationSetting[]>([
    {
      id: 'push',
      label: 'Push Notifications',
      description: 'Receive push notifications on your device',
      enabled: true,
    },
    {
      id: 'email',
      label: 'Email Notifications',
      description: 'Receive email updates about your account',
      enabled: true,
    },
    {
      id: 'billReminders',
      label: 'Bill Reminders',
      description: 'Get reminded when bills are due',
      enabled: true,
    },
    {
      id: 'contributionReminders',
      label: 'Contribution Reminders',
      description: 'Get reminded to make contributions',
      enabled: false,
    },
    {
      id: 'dueDateAlerts',
      label: 'Due Date Alerts',
      description: 'Alerts 3 days before bills are due',
      enabled: true,
    },
    {
      id: 'weeklySummary',
      label: 'Weekly Summary',
      description: 'Get a weekly summary of your bills',
      enabled: true,
    },
    {
      id: 'marketing',
      label: 'Marketing Updates',
      description: 'Hear about new features and promotions',
      enabled: false,
    },
  ]);

  const toggleSetting = (id: string) => {
    setSettings(
      settings.map((setting) =>
        setting.id === id ? { ...setting, enabled: !setting.enabled } : setting
      )
    );
  };

  return (
    <SafeAreaView style={styles.container}>
      {/* Header */}
      <View style={styles.header}>
        <TouchableOpacity onPress={() => navigation.goBack()}>
          <Text style={styles.backButton}>←</Text>
        </TouchableOpacity>
        <Text style={styles.headerTitle}>Notifications</Text>
        <View style={{ width: 24 }} />
      </View>

      <ScrollView showsVerticalScrollIndicator={false} style={styles.content}>
        {/* Notification Settings List */}
        {settings.map((setting) => (
