import React from 'react';
import { View, Text, StyleSheet, TouchableOpacity, SafeAreaView, ScrollView } from 'react-native';
import { colors, spacing, fontSizes, borderRadius } from '../theme';

interface Props {
  navigation: any;
  route: any;
}

interface Feature {
  name: string;
  free: boolean | string;
  premium: boolean | string;
}

export function PlansComparisonScreen({ navigation }: Props) {
  const features: Feature[] = [
    { name: 'Number of Bills', free: '5', premium: 'Unlimited' },
    { name: 'Auto-detect Bills', free: false, premium: true },
    { name: 'Export Reports', free: false, premium: true },
    { name: 'Priority Support', free: false, premium: true },
    { name: 'Advanced Insights', free: false, premium: true },
    { name: 'Monthly Reports', free: false, premium: true },
    { name: 'Recurring Contributions', free: true, premium: true },
    { name: 'Payment History', free: true, premium: true },
    { name: 'Community Access', free: true, premium: true },
  ];

  const renderFeatureValue = (value: boolean | string) => {
    if (typeof value === 'boolean') {
      return value ? '✓' : '✗';
    }
    return value;
  };

  const getFeatureColor = (isFree: boolean) => {
    return isFree
      ? { color: colors.textMuted }
      : { color: colors.primary };
  };

  return (
    <SafeAreaView style={styles.container}>
      {/* Header */}
      <View style={styles.header}>
        <TouchableOpacity onPress={() => navigation.goBack()}>
          <Text style={styles.backButton}>←</Text>
        </TouchableOpacity>
        <Text style={styles.headerTitle}>Compare Plans</Text>
        <View style={{ width: 24 }} />
      </View>

      <ScrollView showsVerticalScrollIndicator={false} style={styles.content}>
        {/* Plans Header */}
        <View style={styles.plansHeader}>
          <View style={styles.planHeaderItem}>
            <Text style={styles.planHeaderTitle}>Free</Text>
            <Text style={styles.planPrice}>$0</Text>
          </View>
          <View style={styles.planHeaderDivider} />
          <View style={styles.planHeaderItem}>
            <Text style={styles.planHeaderTitle}>Premium</Text>
            <Text style={styles.planPrice}>$7.99/mo</Text>
          </View>
        </View>

        {/* Features Comparison Table */}
        <View style={styles.comparisonTable}>
          {features.map((feature, idx) => (
            <View key={feature.name}>
              <View style={styles.featureRow}>
                <Text style={styles.featureName}>{feature.name}</Text>
                <View style={styles.featureValueContainer}>
                  <Text
                    style={[
                      styles.featureValue,
                      getFeatureColor(
                        typeof feature.free === 'boolean' && !feature.free
                      ),
                    ]}
                  >
                    {renderFeatureValue(feature.free)}
                  </Text>
                </View>
                <View style={styles.featureValueContainer}>
                  <Text
                    style={[
                      styles.featureValue,
                      getFeatureColor(
                        typeof feature.premium === 'boolean' && feature.premium
                      ),
                    ]}
                  >
                    {renderFeatureValue(feature.premium)}
                  </Text>
                </View>
              </View>
              {idx < features.length - 1 && <View style={styles.rowDivider} />}
            </View>
          ))}
        </View>

        {/* Action Buttons */}
        <View style={styles.actionSection}>
          <TouchableOpacity style={styles.currentButton}>
            <Text style={styles.currentButtonText}>Current Plan</Text>
          </TouchableOpacity>
          <TouchableOpacity style={styles.upgradeButton}>
            <Text style={styles.upgradeButtonText}>Upgrade to Premium</Text>
          </TouchableOpacity>
        </View>

        {/* Benefits Section */}
        <View style={styles.benefitsSection}>
          <Text style={styles.benefitsTitle}>Premium Benefits</Text>

          <View style={styles.benefitCard}>
            <Text style={styles.benefitIcon}>📊</Text>
            <View style={styles.benefitContent}>
              <Text style={styles.benefitName}>Advanced Insights</Text>
              <Text style={styles.benefitDescription}>
                Get detailed analytics and spending trends
              </Text>
            </View>
          </View>

          <View style={styles.benefitCard}>
            <Text style={styles.benefitIcon}>⚡</Text>
            <View style={styles.benefitContent}>
              <Text style={styles.benefitName}>Auto-Detection</Text>
              <Text style={styles.benefitDescription}>
                Automatically detect new bills from transactions
              </Text>
            </View>
          </View>

          <View style={styles.benefitCard}>
            <Text style={styles.benefitIcon}>📥</Text>
            <View style={styles.benefitContent}>
              <Text style={styles.benefitName}>Export Reports</Text>
              <Text style={styles.benefitDescription}>
                Download and share your financial reports
              </Text>
            </View>
          </View>

          <View style={styles.benefitCard}>
            <Text style={styles.benefitIcon}>🎯</Text>
            <View style={styles.benefitContent}>
              <Text style={styles.benefitName}>Priority Support</Text>
              <Text style={styles.benefitDescription}>
                Get faster support responses from our team
              </Text>
            </View>
          </View>
        </View>

        {/* FAQ */}
        <View style={styles.faqSection}>
          <Text style={styles.faqTitle}>Frequently Asked Questions</Text>

          <View style={styles.faqItem}>
            <Text style={styles.faqQuestion}>Can I change plans anytime?</Text>
            <Text style={styles.faqAnswer}>
              Yes! You can upgrade or downgrade your plan at any time. Changes take effect immediately.
            </Text>
          </View>

          <View style={styles.faqItem}>
            <Text style={styles.faqQuestion}>What happens when I upgrade?</Text>
            <Text style={styles.faqAnswer}>
              All premium features will be available immediately. Your billing will adjust based on your current cycle.
            </Text>
          </View>

          <View style={styles.faqItem}>
            <Text style={styles.faqQuestion}>Is there a money-back guarantee?</Text>
            <Text style={styles.faqAnswer}>
              Yes! If you're not satisfied within 7 days, we'll refund your payment in full.
            </Text>
          </View>
        </View>

        <View style={{ height: 20 }} />
      </ScrollView>
    </SafeAreaView>
  );
}

