import { createClient } from '@supabase/supabase-js';
import type { AdminUser, AdminBill, AdminTransaction, AdminSubscription, DashboardStats, ChartDataPoint, Activity, ApiResponse } from '../types';

const supabaseUrl = import.meta.env.VITE_SUPABASE_URL || '';
const supabaseServiceKey = import.meta.env.VITE_SUPABASE_SERVICE_KEY || '';

export const supabase = createClient(supabaseUrl, supabaseServiceKey);

// Helper function to handle API responses
function handleResponse<T>(data: T, error: any): ApiResponse<T> {
  if (error) {
    console.error('Supabase error:', error);
    return {
      data: data as T,
      error: error.message,
      success: false,
    };
  }
  return {
    data,
    success: true,
  };
}

export const adminApi = {
  // AUTH
  async loginAdmin(email: string, password: string) {
    try {
      const { data, error } = await supabase.auth.signInWithPassword({
        email,
        password,
      });
      return handleResponse(data, error);
    } catch (error) {
      return { data: null, error: 'Login failed', success: false };
    }
  },

  async logoutAdmin() {
    try {
      const { error } = await supabase.auth.signOut();
      return handleResponse(null, error);
    } catch (error) {
      return { data: null, error: 'Logout failed', success: false };
    }
  },

  async getCurrentAdmin() {
    try {
      const { data: { user }, error } = await supabase.auth.getUser();
      return handleResponse(user, error);
    } catch (error) {
      return { data: null, error: 'Failed to get current user', success: false };
    }
  },

  // USERS
  async getUsers(page: number = 1, limit: number = 20, search?: string) {
    try {
      let query = supabase.from('users').select('*');

      if (search) {
        query = query.or(`email.ilike.%${search}%,full_name.ilike.%${search}%`);
      }

      const { data, error, count } = await query
        .order('created_at', { ascending: false })
        .range((page - 1) * limit, page * limit - 1);

      const response: ApiResponse<AdminUser[]> = {
        data: data as AdminUser[],
        pagination: {
          page,
          limit,
          total: count || 0,
          total_pages: Math.ceil((count || 0) / limit),
        },
        success: !error,
        error: error?.message,
      };
      return response;
    } catch (error) {
      return { data: [], pagination: { page, limit, total: 0, total_pages: 0 }, error: 'Failed to fetch users', success: false };
    }
  },

  async getUserById(id: string) {
    try {
      const { data, error } = await supabase
        .from('users')
        .select('*')
        .eq('id', id)
        .single();

      return handleResponse(data, error);
    } catch (error) {
      return { data: null, error: 'Failed to fetch user', success: false };
    }
  },

  async getUserBills(userId: string, page: number = 1, limit: number = 10) {
    try {
      const { data, error, count } = await supabase
        .from('bills')
        .select('*')
        .eq('user_id', userId)
        .order('created_at', { ascending: false })
        .range((page - 1) * limit, page * limit - 1);

      const response: ApiResponse<AdminBill[]> = {
        data: data as AdminBill[],
        pagination: {
          page,
          limit,
          total: count || 0,
          total_pages: Math.ceil((count || 0) / limit),
        },
        success: !error,
        error: error?.message,
      };
