      }));

      return { data, success: true };
    } catch (error) {
      return { data: [], error: 'Failed to fetch recent activity', success: false };
    }
  },

  async exportUsers(format: 'csv' | 'json' = 'csv') {
    try {
      const { data, error } = await supabase
        .from('users')
        .select('*')
        .limit(10000);

      if (error) throw error;

      if (format === 'csv') {
        const csv = this.convertToCSV(data);
        return { data: csv, success: true };
      } else {
        return { data: JSON.stringify(data, null, 2), success: true };
      }
    } catch (error) {
      return { data: null, error: 'Failed to export users', success: false };
    }
  },

  private convertToCSV(data: any[]) {
    if (!data || data.length === 0) return '';

    const headers = Object.keys(data[0]);
    const csv = [
      headers.join(','),
      ...data.map(row =>
        headers.map(header => {
          const value = row[header];
          if (typeof value === 'string' && value.includes(',')) {
            return `"${value}"`;
          }
          return value;
        }).join(',')
      ),
    ].join('\n');

    return csv;
  },
};

