export const StatusBadge: React.FC<StatusBadgeProps> = ({ status, size = 'md' }) => {
  const statusConfig: Record<string, { bg: string; text: string; border: string }> = {
    active: { bg: 'bg-emerald-900', text: 'text-emerald-300', border: 'border-emerald-700' },
    success: { bg: 'bg-green-900', text: 'text-green-300', border: 'border-green-700' },
    pending: { bg: 'bg-amber-900', text: 'text-amber-300', border: 'border-amber-700' },
    failed: { bg: 'bg-red-900', text: 'text-red-300', border: 'border-red-700' },
    paused: { bg: 'bg-slate-700', text: 'text-slate-300', border: 'border-slate-600' },
    cancelled: { bg: 'bg-red-950', text: 'text-red-300', border: 'border-red-800' },
    overdue: { bg: 'bg-red-900', text: 'text-red-300', border: 'border-red-700' },
    paid: { bg: 'bg-green-900', text: 'text-green-300', border: 'border-green-700' },
  };

  const config = statusConfig[status] || {
    bg: 'bg-slate-700',
    text: 'text-slate-300',
