5	const STRIPE_SECRET_KEY = Deno.env.get("STRIPE_SECRET_KEY") || "";
6	const STRIPE_PRICE_ID = Deno.env.get("STRIPE_PREMIUM_PRICE_ID") || "";
7	const SUPABASE_URL = Deno.env.get("SUPABASE_URL") || "";
8	const SUPABASE_ANON_KEY = Deno.env.get("SUPABASE_ANON_KEY") || "";
9	const SUPABASE_SERVICE_KEY = Deno.env.get("SUPABASE_SERVICE_ROLE_KEY") || "";
10	
11	serve(async (req: Request) => {
12	  const corsResponse = handleCors(req);
13	  if (corsResponse) return corsResponse;
14	
15	  try {
16	    const { user } = await verifyAuth(SUPABASE_URL, SUPABASE_ANON_KEY, req);
17	    const { paymentMethodId } = await req.json();
18	
19	    if (!paymentMethodId) {
20	      return new Response(
21	        JSON.stringify({ error: "Missing paymentMethodId" }),
22	        {
23	          status: 400,
24	          headers: { ...corsHeaders, "Content-Type": "application/json" },
25	        }
26	      );
27	    }
28	
29	    const serviceClient = createSupabaseClient(
30	      SUPABASE_URL,
31	      SUPABASE_SERVICE_KEY
32	    );
33	
34	    // Get payment method details
35	    const { data: paymentMethod } = await serviceClient
36	      .from("payment_methods")
37	      .select("stripe_customer_id, stripe_payment_method_id")
38	      .eq("id", paymentMethodId)
39	      .eq("user_id", user.id)
40	      .single();
41	
42	    if (!paymentMethod || !paymentMethod.stripe_customer_id) {
43	      return new Response(
44	        JSON.stringify({ error: "Payment method not found" }),
45	        {
46	          status: 404,
47	          headers: { ...corsHeaders, "Content-Type": "application/json" },
48	        }
49	      );
50	    }
51	
52	    // Check if subscription already exists
53	    const { data: existing } = await serviceClient
54	      .from("subscriptions")
55	      .select("stripe_subscription_id, status")
56	      .eq("user_id", user.id)
57	      .eq("plan", "premium")
58	      .neq("status", "canceled");
59	
60	    if (existing && existing.length > 0) {
61	      return new Response(
62	        JSON.stringify({
63	          error: "Premium subscription already active",
64	          subscription: existing[0],
65	        }),
66	        {
67	          status: 400,
68	          headers: { ...corsHeaders, "Content-Type": "application/json" },
69	        }
70	      );
71	    }
72	
73	    // Create subscription in Stripe
74	    const subscriptionResponse = await fetch(
75	      "https://api.stripe.com/v1/subscriptions",
76	      {
77	        method: "POST",
78	        headers: {
79	          Authorization: `Bearer ${STRIPE_SECRET_KEY}`,
80	          "Content-Type": "application/x-www-form-urlencoded",
81	        },
82	        body: new URLSearchParams({
83	          customer: paymentMethod.stripe_customer_id,
84	          items: JSON.stringify([{ price: STRIPE_PRICE_ID }]),
85	          default_payment_method:
86	            paymentMethod.stripe_payment_method_id || "",
87	          off_session: "true",
88	          metadata: JSON.stringify({ user_id: user.id }),
89	        }),
90	      }
91	    );
92	
93	    const subscriptionData = await subscriptionResponse.json();
94	
95	    if (!subscriptionResponse.ok) {
96	      console.error("Stripe subscription error:", subscriptionData);
97	      return new Response(
98	        JSON.stringify({
99	          error:
100	            subscriptionData.error?.message ||
101	            "Failed to create subscription",
102	        }),
103	        {
104	          status: 400,
105	          headers: { ...corsHeaders, "Content-Type": "application/json" },
106	        }
107	      );
108	    }
109	
110	    // Save subscription to database
111	    const { data: subscription, error: insertError } = await serviceClient
112	      .from("subscriptions")
113	      .insert({
114	        user_id: user.id,
115	        stripe_subscription_id: subscriptionData.id,
116	        stripe_customer_id: paymentMethod.stripe_customer_id,
117	        plan: "premium",
118	        status: subscriptionData.status,
119	        current_period_start: new Date(
120	          subscriptionData.current_period_start * 1000
121	        ).toISOString(),
122	        current_period_end: new Date(
123	          subscriptionData.current_period_end * 1000
124	        ).toISOString(),
125	      })
126	      .select();
127	
128	    if (insertError) {
129	      throw insertError;
130	    }
131	
132	    // Update profile to mark as premium
133	    await serviceClient
134	      .from("profiles")
135	      .update({
136	        is_premium: true,
137	        premium_expires_at: new Date(
138	          subscriptionData.current_period_end * 1000
139	        ).toISOString(),
140	      })
141	      .eq("id", user.id);
142	
143	    return new Response(
144	      JSON.stringify({
145	        success: true,
146	        subscription: subscription[0],
147	        message: "Premium subscription activated",
148	      }),
149	      {
150	        headers: { ...corsHeaders, "Content-Type": "application/json" },
151	      }
152	    );
153	  } catch (error) {
154	    console.error("Error:", error);
155	    return new Response(
156	      JSON.stringify({ error: error.message || "Internal server error" }),
157	      {
158	        status: 500,
159	        headers: { ...corsHeaders, "Content-Type": "application/json" },
160	      }
161	    );
162	  }
163	});
