1	import { createClient } from "https://esm.sh/@supabase/supabase-js@2.38.4";
2	
3	export function createSupabaseClient(
4	  supabaseUrl: string,
5	  supabaseKey: string,
6	  authToken?: string
7	) {
8	  const client = createClient(supabaseUrl, supabaseKey, {
9	    global: {
10	      headers: authToken
11	        ? {
12	            Authorization: `Bearer ${authToken}`,
13	          }
14	        : {},
15	    },
16	  });
17	
18	  return client;
19	}
20	
21	export async function verifyAuth(
22	  supabaseUrl: string,
23	  supabaseKey: string,
24	  req: Request
25	) {
26	  const authHeader = req.headers.get("authorization");
27	  if (!authHeader) {
28	    throw new Error("Missing authorization header");
29	  }
30	
31	  const token = authHeader.replace("Bearer ", "");
32	  const client = createSupabaseClient(supabaseUrl, supabaseKey, token);
33	
34	  const {
35	    data: { user },
36	    error,
37	  } = await client.auth.getUser();
38	
39	  if (error || !user) {
40	    throw new Error("Unauthorized");
41	  }
42	
43	  return { user, client };
44	}
45

1	export const corsHeaders = {
2	  "Access-Control-Allow-Origin": "*",
3	  "Access-Control-Allow-Methods": "GET, POST, PUT, DELETE, PATCH, OPTIONS",
4	  "Access-Control-Allow-Headers":
5	    "authorization, x-client-info, content-type",
6	};
7	
8	export function handleCors(req: Request): Response | null {
9	  if (req.method === "OPTIONS") {
10	    return new Response("ok", { headers: corsHeaders });
11	  }
12	  return null;
13	}
