// ── Contribution Actions (Async) ────────────────────────────────────────
makeManualContributionAsync: async (billId, amount, source) => {
  set({ isLoading: true, dataError: null });
  try {
    if (!DatabaseServices?.ContributionService || !supabase) {
      get().makeManualContribution(billId, amount, source);
      set({ isLoading: false });
      return {};
    }

    const { data: { user } } = await supabase.auth.getUser();
    if (!user) {
      const errMsg = 'User not authenticated';
      set({ isLoading: false, dataError: errMsg });
      return { error: errMsg };
    }

    const bucket = get().getBucket(billId);
    if (!bucket) {
      const errMsg = 'Bucket not found';
      set({ isLoading: false, dataError: errMsg });
      return { error: errMsg };
    }

    const { data, error } = await DatabaseServices.ContributionService.create({
      user_id: user.id,
      bill_id: billId,
      bucket_id: bucket.id,
      amount,
      status: 'completed',
      executed_at: new Date().toISOString(),
    });
    if (error) {
      set({ isLoading: false, dataError: error.message });
      return { error: error.message };
    }

    const newContribution = mapContribution(data);
    set((state) => ({
      contributions: [...state.contributions, newContribution],
      buckets: state.buckets.map((b) =>
        b.id === bucket.id
          ? { ...b, currentAmount: Math.min(b.currentAmount + amount, b.targetAmount) }
          : b
      ),
      isLoading: false,
    }));
    return {};
  } catch (err: any) {
    const errMsg = err?.message || 'Failed to make contribution';
    set({ isLoading: false, dataError: errMsg });
    return { error: errMsg };
  }
},

