-- Admin users table (separate from regular users)
CREATE TABLE public.admin_users (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  email TEXT UNIQUE NOT NULL,
  full_name TEXT NOT NULL,
  role TEXT NOT NULL DEFAULT 'admin' CHECK (role IN ('admin', 'super_admin', 'support')),
  is_active BOOLEAN DEFAULT TRUE,
  last_login TIMESTAMPTZ,
  created_at TIMESTAMPTZ DEFAULT NOW()
);

-- Admin activity log
CREATE TABLE public.admin_activity_log (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  admin_id UUID REFERENCES public.admin_users(id) ON DELETE SET NULL,
  action TEXT NOT NULL,
  target_type TEXT,
  target_id TEXT,
  details JSONB,
  ip_address TEXT,
  created_at TIMESTAMPTZ DEFAULT NOW()
);

-- App settings (key-value config)
CREATE TABLE public.app_settings (
  key TEXT PRIMARY KEY,
  value JSONB NOT NULL,
  updated_by UUID REFERENCES public.admin_users(id) ON DELETE SET NULL,
  updated_at TIMESTAMPTZ DEFAULT NOW()
);

-- Support tickets
CREATE TABLE public.support_tickets (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  user_id UUID REFERENCES public.users(id) ON DELETE CASCADE,
  subject TEXT NOT NULL,
  description TEXT,
  status TEXT DEFAULT 'open' CHECK (status IN ('open', 'in_progress', 'resolved', 'closed')),
  priority TEXT DEFAULT 'medium' CHECK (priority IN ('low', 'medium', 'high', 'urgent')),
  assigned_to UUID REFERENCES public.admin_users(id) ON DELETE SET NULL,
  notes TEXT,
  created_at TIMESTAMPTZ DEFAULT NOW(),
  updated_at TIMESTAMPTZ DEFAULT NOW()
);

-- Insert default app settings
INSERT INTO public.app_settings (key, value) VALUES
  ('premium_price', '"7.99"'),
  ('max_free_bills', '5'),
  ('auto_contribution_enabled', 'true'),
  ('maintenance_mode', 'false'),
  ('app_version', '"1.0.0"'),
  ('max_daily_transactions', '100'),
  ('notification_email', '"support@fractionalbillpay.com"'),
  ('feature_flags', '{"new_dashboard": false, "beta_features": false}');

-- Create indexes
CREATE INDEX idx_admin_activity_admin_id ON public.admin_activity_log(admin_id);
CREATE INDEX idx_admin_activity_created_at ON public.admin_activity_log(created_at DESC);
CREATE INDEX idx_admin_activity_target ON public.admin_activity_log(target_type, target_id);
CREATE INDEX idx_support_tickets_user_id ON public.support_tickets(user_id);
CREATE INDEX idx_support_tickets_status ON public.support_tickets(status);
CREATE INDEX idx_support_tickets_assigned_to ON public.support_tickets(assigned_to);
CREATE INDEX idx_support_tickets_created_at ON public.support_tickets(created_at DESC);

-- Enable RLS for admin tables
ALTER TABLE public.admin_users ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.admin_activity_log ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.app_settings ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.support_tickets ENABLE ROW LEVEL SECURITY;

-- Create admin role if it doesn't exist
CREATE ROLE admin_role NOINHERIT;

-- Grant permissions to admin role (service role access only)
-- These tables should only be accessible via service role key, not by regular users
GRANT USAGE ON SCHEMA public TO admin_role;
GRANT SELECT, INSERT, UPDATE, DELETE ON public.admin_users TO admin_role;
GRANT SELECT, INSERT ON public.admin_activity_log TO admin_role;
GRANT SELECT, UPDATE ON public.app_settings TO admin_role;
GRANT SELECT, INSERT, UPDATE ON public.support_tickets TO admin_role;

