import React, { useEffect, useState } from 'react';
import {
  BarChart3,
  TrendingUp,
  CreditCard,
  Users,
  Activity,
  Zap,
  AlertCircle,
} from 'lucide-react';
import { StatsCard, Chart } from '../components';
import { adminApi } from '../lib/supabase';
import type { DashboardStats, ChartDataPoint, Activity as ActivityType } from '../types';
import { formatDistanceToNow } from 'date-fns';

export const Dashboard: React.FC = () => {
  const [stats, setStats] = useState<DashboardStats | null>(null);
  const [revenueData, setRevenueData] = useState<ChartDataPoint[]>([]);
  const [growthData, setGrowthData] = useState<ChartDataPoint[]>([]);
  const [recentActivity, setRecentActivity] = useState<ActivityType[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    const fetchDashboardData = async () => {
      try {
        setLoading(true);
        setError(null);

        const [statsRes, revenueRes, growthRes, activityRes] = await Promise.all([
          adminApi.getDashboardStats(),
          adminApi.getRevenueData(6),
          adminApi.getUserGrowthData(6),
          adminApi.getRecentActivity(10),
        ]);

        if (statsRes.success) setStats(statsRes.data);
        if (revenueRes.success) setRevenueData(revenueRes.data);
        if (growthRes.success) setGrowthData(growthRes.data);
        if (activityRes.success) setRecentActivity(activityRes.data);

        if (!statsRes.success) {
          setError('Failed to load dashboard data');
        }
      } catch (err) {
        setError('An error occurred while loading dashboard data');
        console.error(err);
      } finally {
        setLoading(false);
      }
    };

    fetchDashboardData();
  }, []);

  if (loading) {
    return (
      <div className="space-y-6 animate-pulse">
        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-4">
          {Array.from({ length: 4 }).map((_, i) => (
            <div key={i} className="bg-slate-800 rounded-lg p-6 h-24" />
          ))}
        </div>
      </div>
    );
  }

  if (error && !stats) {
    return (
      <div className="bg-red-900 border border-red-700 rounded-lg p-4 flex gap-3">
        <AlertCircle className="w-5 h-5 text-red-400 flex-shrink-0 mt-0.5" />
        <p className="text-red-300">{error}</p>
      </div>
    );
  }

  return (
    <div className="space-y-6">
      {/* Page Title */}
      <div>
        <h1 className="text-3xl font-bold text-slate-50">Dashboard</h1>
        <p className="text-slate-400 mt-1">Overview of your platform's performance</p>
      </div>

      {/* KPI Cards */}
      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-4">
        <StatsCard
          icon={<Users />}
          label="Total Users"
          value={stats?.total_users.toLocaleString() || '0'}
          change={12.5}
          changeLabel="from last month"
          color="blue"
        />
        <StatsCard
          icon={<FileText />}
          label="Active Bills"
          value={stats?.active_bills.toLocaleString() || '0'}
          change={8.3}
          changeLabel="from last month"
          color="purple"
        />
        <StatsCard
          icon={<CreditCard />}
          label="Monthly Revenue"
          value={`$${stats?.monthly_revenue.toLocaleString() || '0'}`}
          change={15.2}
          changeLabel="from last month"
          color="green"
        />
        <StatsCard
          icon={<TrendingUp />}
          label="Subscription Rate"
          value={`${stats?.subscription_rate.toFixed(1) || '0'}%`}
          change={2.1}
          changeLabel="from last month"
          color="teal"
        />
      </div>

      {/* Charts Row 1 */}
      <div className="grid grid-cols-1 lg:grid-cols-2 gap-6">
        <Chart
          type="line"
          data={revenueData}
          title="Revenue Trend"
          dataKey="revenue"
          xAxisKey="month"
          color="#00D998"
          height={300}
        />
        <Chart
          type="bar"
          data={growthData}
          title="User Growth"
          dataKey="users"
          xAxisKey="month"
          color="#0EA5E9"
          height={300}
        />
      </div>

      {/* Quick Stats and Activity */}
      <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
        {/* Quick Stats */}
        <div className="bg-slate-800 rounded-lg border border-slate-700 p-6">
          <h3 className="text-lg font-semibold text-slate-50 mb-4">Quick Stats</h3>
          <div className="space-y-4">
            <div>
              <p className="text-slate-400 text-sm mb-1">Bills Paid This Month</p>
              <p className="text-2xl font-bold text-slate-50">
                {stats?.bills_paid_this_month.toLocaleString() || '0'}
              </p>
            </div>
            <div className="h-px bg-slate-700" />
            <div>
              <p className="text-slate-400 text-sm mb-1">Avg Funding Rate</p>
              <p className="text-2xl font-bold text-emerald-400">
                {stats?.avg_funding_rate.toFixed(1) || '0'}%
              </p>
            </div>
            <div className="h-px bg-slate-700" />
            <div>
              <p className="text-slate-400 text-sm mb-1">Active Streaks</p>
              <p className="text-2xl font-bold text-blue-400">
                {stats?.active_streaks.toLocaleString() || '0'}
              </p>
            </div>
          </div>
        </div>

        {/* System Health */}
        <div className="bg-slate-800 rounded-lg border border-slate-700 p-6">
          <h3 className="text-lg font-semibold text-slate-50 mb-4">System Health</h3>
          <div className="space-y-4">
            <div>
              <div className="flex items-center justify-between mb-1">
                <p className="text-slate-400 text-sm">API Response Time</p>
                <p className="text-sm text-green-400 font-semibold">
                  {stats?.api_response_time}ms
                </p>
              </div>
              <div className="w-full bg-slate-700 rounded-full h-2">
                <div
                  className="bg-green-500 h-2 rounded-full"
                  style={{
                    width: `${Math.min(100, (stats?.api_response_time || 0) / 2)}%`,
                  }}
                />
              </div>
            </div>
            <div className="h-px bg-slate-700" />
            <div>
              <div className="flex items-center justify-between mb-1">
                <p className="text-slate-400 text-sm">Error Rate</p>
                <p className="text-sm text-green-400 font-semibold">
                  {stats?.error_rate.toFixed(2)}%
                </p>
              </div>
              <div className="w-full bg-slate-700 rounded-full h-2">
                <div
                  className="bg-green-500 h-2 rounded-full"
                  style={{
                    width: `${Math.max(0, 100 - (stats?.error_rate || 0) * 10)}%`,
                  }}
                />
              </div>
            </div>
            <div className="h-px bg-slate-700" />
            <div className="flex items-center gap-2">
              <div className="w-3 h-3 bg-green-500 rounded-full" />
              <p className="text-slate-300 text-sm">All Systems Operational</p>
            </div>
          </div>
        </div>

        {/* Recent Activity */}
        <div className="bg-slate-800 rounded-lg border border-slate-700 p-6">
          <h3 className="text-lg font-semibold text-slate-50 mb-4 flex items-center gap-2">
            <Activity className="w-5 h-5" />
            Recent Activity
          </h3>
          <div className="space-y-3 max-h-80 overflow-y-auto">
            {recentActivity.length === 0 ? (
              <p className="text-slate-400 text-sm">No recent activity</p>
            ) : (
              recentActivity.slice(0, 5).map((activity) => (
                <div
                  key={activity.id}
                  className="flex items-start gap-3 p-2 rounded hover:bg-slate-700 transition-colors"
                >
                  <div className="w-2 h-2 bg-emerald-500 rounded-full mt-1.5 flex-shrink-0" />
                  <div className="flex-1 min-w-0">
                    <p className="text-sm text-slate-200 truncate">
                      {activity.description}
                    </p>
                    <p className="text-xs text-slate-500">
                      {formatDistanceToNow(new Date(activity.timestamp), {
                        addSuffix: true,
                      })}
                    </p>
                  </div>
                </div>
              ))
            )}
          </div>
        </div>
      </div>
    </div>
  );
};

// Helper component
const FileText = () => (
  <BarChart3 className="w-6 h-6" />
);

