import { serve } from "https://deno.land/std@0.168.0/http/server.ts";
import { corsHeaders, handleCors } from "../_shared/cors.ts";
import { verifyAdminAuth, createSupabaseClient } from "../_shared/admin-utils.ts";

const SUPABASE_URL = Deno.env.get("SUPABASE_URL") || "";
const SUPABASE_SERVICE_KEY = Deno.env.get("SUPABASE_SERVICE_ROLE_KEY") || "";

serve(async (req: Request) => {
  const corsResponse = handleCors(req);
  if (corsResponse) return corsResponse;

  try {
    // Verify admin authentication
    const authHeader = req.headers.get("authorization");
    if (!authHeader) {
      return new Response(
        JSON.stringify({ error: "Missing authorization header" }),
        {
          status: 401,
          headers: { ...corsHeaders, "Content-Type": "application/json" },
        }
      );
    }

    const token = authHeader.replace("Bearer ", "");
    const admin = await verifyAdminAuth(SUPABASE_URL, SUPABASE_SERVICE_KEY, token);

    const supabase = createSupabaseClient(SUPABASE_URL, SUPABASE_SERVICE_KEY);
    const url = new URL(req.url);
    const action = url.searchParams.get("action") || "stats";

    switch (action) {
      case "stats": {
        // Get total users
        const { count: totalUsers } = await supabase
          .from("users")
          .select("*", { count: "exact", head: true });

        // Get active bills
        const { count: activeBills } = await supabase
          .from("bills")
          .select("*", { count: "exact", head: true })
          .eq("is_active", true);

        // Get premium subscribers
        const { count: premiumUsers } = await supabase
          .from("subscriptions")
          .select("*", { count: "exact", head: true })
          .eq("status", "active");

        // Get total transaction volume
        const { data: transactions } = await supabase
          .from("transactions")
          .select("amount")
          .eq("status", "completed");

        const totalVolume = transactions?.reduce(
          (sum: number, t: any) => sum + Number(t.amount),
          0
        ) || 0;

        // Get recent signups (last 30 days)
        const thirtyDaysAgo = new Date(
          Date.now() - 30 * 24 * 60 * 60 * 1000
        ).toISOString();
        const { count: newUsers } = await supabase
          .from("users")
          .select("*", { count: "exact", head: true })
          .gte("created_at", thirtyDaysAgo);

        // Get bill category breakdown
        const { data: categoryData } = await supabase
          .from("bills")
          .select("category")
          .eq("is_active", true);

        const categories: Record<string, number> = {};
        categoryData?.forEach((b: any) => {
          categories[b.category] = (categories[b.category] || 0) + 1;
        });

        // Get monthly revenue (subscriptions)
        const premiumPrice = 7.99;
        const monthlyRevenue = (premiumUsers || 0) * premiumPrice;

        // Calculate subscription rate
        const subscriptionRate = totalUsers
          ? (((premiumUsers || 0) / totalUsers) * 100).toFixed(1)
          : "0";

        return new Response(
          JSON.stringify({
            totalUsers: totalUsers || 0,
            activeBills: activeBills || 0,
            premiumUsers: premiumUsers || 0,
            totalVolume: totalVolume.toFixed(2),
            newUsers: newUsers || 0,
            monthlyRevenue: monthlyRevenue.toFixed(2),
            categoryBreakdown: categories,
            subscriptionRate: subscriptionRate + "%",
            timestamp: new Date().toISOString(),
          }),
          {
            headers: { ...corsHeaders, "Content-Type": "application/json" },
          }
        );
      }

      case "users": {
        const page = parseInt(url.searchParams.get("page") || "1");
        const limit = parseInt(url.searchParams.get("limit") || "20");
        const search = url.searchParams.get("search") || "";
        const sortBy = url.searchParams.get("sortBy") || "created_at";
        const sortOrder = url.searchParams.get("sortOrder") || "desc";
        const offset = (page - 1) * limit;

        let query = supabase
          .from("users")
          .select(
            "id, email, full_name, is_premium, created_at, updated_at, premium_expires_at",
            { count: "exact" }
          );

        if (search) {
          query = query.or(
            `email.ilike.%${search}%,full_name.ilike.%${search}%`
          );
        }

        const { data, count, error } = await query
          .range(offset, offset + limit - 1)
          .order(sortBy, { ascending: sortOrder === "asc" });

        if (error) {
          throw error;
        }

        return new Response(
          JSON.stringify({
            users: data || [],
            total: count || 0,
            page,
            limit,
            totalPages: Math.ceil((count || 0) / limit),
          }),
          { headers: { ...corsHeaders, "Content-Type": "application/json" } }
        );
      }

      case "bills": {
        const page = parseInt(url.searchParams.get("page") || "1");
        const limit = parseInt(url.searchParams.get("limit") || "20");
        const userId = url.searchParams.get("userId");
        const category = url.searchParams.get("category");
        const status = url.searchParams.get("status");
        const offset = (page - 1) * limit;

        let query = supabase
          .from("bills")
          .select(
            "id, name, amount, due_date, category, is_active, user_id, created_at, users(email, full_name)",
            { count: "exact" }
          );

        if (userId) {
          query = query.eq("user_id", userId);
        }
        if (category) {
          query = query.eq("category", category);
        }
        if (status === "active") {
          query = query.eq("is_active", true);
        } else if (status === "inactive") {
          query = query.eq("is_active", false);
        }

        const { data, count, error } = await query
          .range(offset, offset + limit - 1)
          .order("created_at", { ascending: false });

        if (error) {
          throw error;
        }

        return new Response(
          JSON.stringify({
            bills: data || [],
            total: count || 0,
            page,
            limit,
            totalPages: Math.ceil((count || 0) / limit),
          }),
          { headers: { ...corsHeaders, "Content-Type": "application/json" } }
        );
      }

      case "transactions": {
        const page = parseInt(url.searchParams.get("page") || "1");
        const limit = parseInt(url.searchParams.get("limit") || "20");
        const offset = (page - 1) * limit;
        const status = url.searchParams.get("status");
        const type = url.searchParams.get("type");
        const userId = url.searchParams.get("userId");

        let query = supabase
          .from("transactions")
          .select(
            "id, amount, status, type, created_at, user_id, users(email, full_name)",
            { count: "exact" }
          );

        if (status) {
          query = query.eq("status", status);
        }
        if (type) {
          query = query.eq("type", type);
        }
        if (userId) {
          query = query.eq("user_id", userId);
        }

        const { data, count, error } = await query
          .range(offset, offset + limit - 1)
          .order("created_at", { ascending: false });

        if (error) {
          throw error;
        }

        return new Response(
          JSON.stringify({
            transactions: data || [],
            total: count || 0,
            page,
            limit,
            totalPages: Math.ceil((count || 0) / limit),
          }),
          { headers: { ...corsHeaders, "Content-Type": "application/json" } }
        );
      }

      case "revenue": {
        const months = parseInt(url.searchParams.get("months") || "6");
        const data = [];

        for (let i = months - 1; i >= 0; i--) {
          const date = new Date();
          date.setMonth(date.getMonth() - i);
          const monthStart = new Date(
            date.getFullYear(),
            date.getMonth(),
            1
          ).toISOString();
          const monthEnd = new Date(
            date.getFullYear(),
            date.getMonth() + 1,
            0
          ).toISOString();

          // Get transaction revenue
          const { data: txns } = await supabase
            .from("transactions")
            .select("amount")
            .eq("status", "completed")
            .gte("created_at", monthStart)
            .lte("created_at", monthEnd);

          const transactionRevenue = txns?.reduce(
            (sum: number, t: any) => sum + Number(t.amount),
            0
          ) || 0;

          // Get subscription revenue
          const { count: activeSubs } = await supabase
            .from("subscriptions")
            .select("*", { count: "exact", head: true })
            .eq("status", "active")
            .lte("created_at", monthEnd);

          const subscriptionRevenue = (activeSubs || 0) * 7.99;
          const totalRevenue = transactionRevenue + subscriptionRevenue;

          data.push({
            month: date.toLocaleString("default", { month: "short", year: "numeric" }),
            transactionRevenue: transactionRevenue.toFixed(2),
            subscriptionRevenue: subscriptionRevenue.toFixed(2),
            totalRevenue: totalRevenue.toFixed(2),
            transactionCount: txns?.length || 0,
            subscriptionCount: activeSubs || 0,
          });
        }

        return new Response(JSON.stringify(data), {
          headers: { ...corsHeaders, "Content-Type": "application/json" },
        });
      }

      case "user-growth": {
        const months = parseInt(url.searchParams.get("months") || "6");
        const data = [];

        for (let i = months - 1; i >= 0; i--) {
          const date = new Date();
          date.setMonth(date.getMonth() - i);
          const monthStart = new Date(
            date.getFullYear(),
            date.getMonth(),
            1
          ).toISOString();
          const monthEnd = new Date(
            date.getFullYear(),
            date.getMonth() + 1,
            0
          ).toISOString();

          const { count } = await supabase
            .from("users")
            .select("*", { count: "exact", head: true })
            .gte("created_at", monthStart)
            .lte("created_at", monthEnd);

          data.push({
            month: date.toLocaleString("default", { month: "short", year: "numeric" }),
            newUsers: count || 0,
          });
        }

        return new Response(JSON.stringify(data), {
          headers: { ...corsHeaders, "Content-Type": "application/json" },
        });
      }

      case "activity-log": {
        const page = parseInt(url.searchParams.get("page") || "1");
        const limit = parseInt(url.searchParams.get("limit") || "50");
        const adminId = url.searchParams.get("adminId");
        const offset = (page - 1) * limit;

        let query = supabase
          .from("admin_activity_log")
          .select(
            "id, action, target_type, target_id, details, ip_address, created_at, admin_users(full_name, email)",
            { count: "exact" }
          );

        if (adminId) {
          query = query.eq("admin_id", adminId);
        }

        const { data, count, error } = await query
          .range(offset, offset + limit - 1)
          .order("created_at", { ascending: false });

        if (error) {
          throw error;
        }

        return new Response(
          JSON.stringify({
            logs: data || [],
            total: count || 0,
            page,
            limit,
            totalPages: Math.ceil((count || 0) / limit),
          }),
          { headers: { ...corsHeaders, "Content-Type": "application/json" } }
        );
      }

      default:
        return new Response(
          JSON.stringify({ error: "Unknown action" }),
          {
            status: 400,
            headers: { ...corsHeaders, "Content-Type": "application/json" },
          }
        );
    }
  } catch (error) {
    console.error("Dashboard error:", error);
    return new Response(
      JSON.stringify({
        error: error instanceof Error ? error.message : "Internal server error",
      }),
      {
        status: 500,
        headers: { ...corsHeaders, "Content-Type": "application/json" },
      }
    );
  }
});

