import React, { useEffect, useState } from 'react';
import { useNavigate } from 'react-router-dom';
import { DataTable, StatusBadge } from '../components';
import { adminApi } from '../lib/supabase';
import type { AdminUser } from '../types';
import { Download, Mail, AlertCircle } from 'lucide-react';
import { formatDistanceToNow } from 'date-fns';

export const Users: React.FC = () => {
  const navigate = useNavigate();
  const [users, setUsers] = useState<AdminUser[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [search, setSearch] = useState('');
  const [page, setPage] = useState(1);
  const [total, setTotal] = useState(0);
  const [status, setStatus] = useState<string>('');
  const [plan, setPlan] = useState<string>('');

  const pageSize = 20;

  useEffect(() => {
    const fetchUsers = async () => {
      try {
        setLoading(true);
        setError(null);

        const result = await adminApi.getUsers(page, pageSize, search);

        if (result.success) {
          setUsers(result.data);
          setTotal(result.pagination?.total || 0);
        } else {
          setError(result.error || 'Failed to fetch users');
        }
      } catch (err) {
        setError('An error occurred while fetching users');
        console.error(err);
      } finally {
        setLoading(false);
      }
    };

    fetchUsers();
  }, [page, search]);

  const handleExport = async (format: 'csv' | 'json') => {
    try {
      const result = await adminApi.exportUsers(format);
      if (result.success && result.data) {
        const blob = new Blob([result.data], {
          type: format === 'csv' ? 'text/csv' : 'application/json',
        });
        const url = window.URL.createObjectURL(blob);
        const a = document.createElement('a');
        a.href = url;
        a.download = `users-export.${format}`;
        document.body.appendChild(a);
        a.click();
        document.body.removeChild(a);
        window.URL.revokeObjectURL(url);
      }
    } catch (err) {
      setError('Failed to export users');
    }
  };

  const columns = [
    {
      key: 'full_name' as const,
      label: 'Name',
      sortable: true,
    },
    {
      key: 'email' as const,
      label: 'Email',
      sortable: true,
    },
    {
      key: 'plan' as const,
      label: 'Plan',
      render: (value: string) => (
        <span className="px-2 py-1 rounded text-xs font-medium bg-slate-700 text-slate-200">
          {value === 'premium' ? 'Premium' : 'Free'}
        </span>
      ),
    },
    {
      key: 'total_bills_count' as const,
      label: 'Bills',
      render: (value: number) => <span className="font-semibold">{value}</span>,
    },
    {
      key: 'total_saved' as const,
      label: 'Total Saved',
      render: (value: number) => (
        <span className="text-emerald-400 font-semibold">${value.toLocaleString()}</span>
      ),
    },
    {
      key: 'current_streak' as const,
      label: 'Streak',
      render: (value: number) => <span className="text-blue-400 font-semibold">{value} days</span>,
    },
    {
      key: 'created_at' as const,
      label: 'Joined',
      render: (value: string) => (
        <span className="text-slate-400 text-sm">
          {formatDistanceToNow(new Date(value), { addSuffix: true })}
        </span>
      ),
    },
    {
      key: 'is_active' as const,
      label: 'Status',
      render: (value: boolean) => (
        <StatusBadge status={value ? 'active' : 'paused'} />
      ),
    },
  ];

  return (
    <div className="space-y-6">
      {/* Header */}
      <div className="flex items-center justify-between">
        <div>
          <h1 className="text-3xl font-bold text-slate-50">Users</h1>
          <p className="text-slate-400 mt-1">
            Manage and monitor all platform users ({total.toLocaleString()} total)
          </p>
        </div>

        <div className="flex gap-2">
          <button
            onClick={() => handleExport('csv')}
            className="flex items-center gap-2 px-4 py-2 bg-slate-800 border border-slate-700 rounded-lg text-slate-300 hover:bg-slate-700 transition-colors"
          >
            <Download className="w-4 h-4" />
            Export CSV
          </button>
          <button
            onClick={() => handleExport('json')}
            className="flex items-center gap-2 px-4 py-2 bg-slate-800 border border-slate-700 rounded-lg text-slate-300 hover:bg-slate-700 transition-colors"
          >
            <Download className="w-4 h-4" />
            Export JSON
          </button>
        </div>
      </div>

      {/* Filters */}
      <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
        <div>
          <label className="block text-sm font-medium text-slate-200 mb-2">
            Plan Type
          </label>
          <select
            value={plan}
            onChange={(e) => {
              setPlan(e.target.value);
              setPage(1);
            }}
            className="w-full px-4 py-2 bg-slate-700 border border-slate-600 rounded-lg text-slate-50 focus:outline-none focus:ring-2 focus:ring-emerald-500"
          >
            <option value="">All Plans</option>
            <option value="free">Free</option>
            <option value="premium">Premium</option>
          </select>
        </div>

        <div>
          <label className="block text-sm font-medium text-slate-200 mb-2">
            Status
          </label>
          <select
            value={status}
            onChange={(e) => {
              setStatus(e.target.value);
              setPage(1);
            }}
            className="w-full px-4 py-2 bg-slate-700 border border-slate-600 rounded-lg text-slate-50 focus:outline-none focus:ring-2 focus:ring-emerald-500"
          >
            <option value="">All Status</option>
            <option value="active">Active</option>
            <option value="inactive">Inactive</option>
          </select>
        </div>

        <div>
          <label className="block text-sm font-medium text-slate-200 mb-2">
            Sort By
          </label>
          <select
            className="w-full px-4 py-2 bg-slate-700 border border-slate-600 rounded-lg text-slate-50 focus:outline-none focus:ring-2 focus:ring-emerald-500"
          >
            <option>Newest First</option>
            <option>Total Saved (High to Low)</option>
            <option>Bills (High to Low)</option>
            <option>Active Streak (High to Low)</option>
          </select>
        </div>
      </div>

      {/* Error Alert */}
      {error && (
        <div className="bg-red-900 border border-red-700 rounded-lg p-4 flex gap-3">
          <AlertCircle className="w-5 h-5 text-red-400 flex-shrink-0 mt-0.5" />
          <p className="text-red-300">{error}</p>
        </div>
      )}

      {/* Data Table */}
      <DataTable
        columns={columns}
        data={users}
        loading={loading}
        onRowClick={(user) => navigate(`/users/${user.id}`)}
        search={{
          value: search,
          onChange: (value) => {
            setSearch(value);
            setPage(1);
          },
          placeholder: 'Search by name or email...',
        }}
        pagination={{
          current: page,
          total: Math.ceil(total / pageSize),
          pageSize,
          onChange: setPage,
        }}
      />

      {/* Bulk Actions */}
      {users.length > 0 && (
        <div className="bg-slate-800 rounded-lg border border-slate-700 p-4 flex items-center justify-between">
          <p className="text-slate-300">
            <span className="font-semibold">{users.length}</span> users selected
          </p>
          <div className="flex gap-2">
            <button
              className="px-4 py-2 bg-slate-700 hover:bg-slate-600 text-slate-200 rounded-lg transition-colors text-sm font-medium flex items-center gap-2"
            >
              <Mail className="w-4 h-4" />
              Send Notification
            </button>
            <button
              className="px-4 py-2 bg-red-950 hover:bg-red-900 text-red-300 rounded-lg transition-colors text-sm font-medium"
            >
              Disable Accounts
            </button>
          </div>
        </div>
      )}
    </div>
  );
};

