/**
 * Plaid integration service for account linking and transaction detection
 */

import { supabase } from './supabase';

export const PlaidService = {
  /**
   * Get link token from Supabase edge function
   * Used to initialize Plaid Link flow
   */
  async createLinkToken() {
    try {
      const { data, error } = await supabase.functions.invoke('plaid-link-token');
      if (error) throw error;
      return { data: data?.link_token, error: null };
    } catch (err: any) {
      return { data: null, error: err };
    }
  },

  /**
   * Exchange public token for access token
   * Called after user completes Plaid Link flow
   */
  async exchangeToken(publicToken: string, metadata: any) {
    try {
      const { data, error } = await supabase.functions.invoke('plaid-exchange-token', {
        body: { public_token: publicToken, metadata },
      });
      if (error) throw error;
      return { data, error: null };
    } catch (err: any) {
      return { data: null, error: err };
    }
  },

  /**
   * Fetch and analyze transactions for bill detection
   * Calls Plaid transactions endpoint and applies bill detection ML
   */
  async detectBills(accountId: string) {
    try {
      const { data, error } = await supabase.functions.invoke('plaid-transactions', {
        body: { account_id: accountId },
      });
      if (error) throw error;
      return { data: data?.detected_bills || [], error: null };
    } catch (err: any) {
      return { data: [], error: err };
    }
  },

  /**
   * Get account balance information
   */
  async getAccountBalance(accountId: string) {
    try {
      const { data, error } = await supabase.functions.invoke('plaid-balance', {
        body: { account_id: accountId },
      });
      if (error) throw error;
      return { data: data?.balances, error: null };
    } catch (err: any) {
      return { data: null, error: err };
    }
  },

  /**
   * Get recent transactions for display
   */
  async getRecentTransactions(accountId: string, limit: number = 30) {
    try {
      const { data, error } = await supabase.functions.invoke('plaid-recent-transactions', {
        body: { account_id: accountId, limit },
      });
      if (error) throw error;
      return { data: data?.transactions || [], error: null };
    } catch (err: any) {
      return { data: [], error: err };
    }
  },

  /**
   * Unlink account from Plaid
   */
  async unlinkAccount(accountId: string) {
    try {
      const { data, error } = await supabase.functions.invoke('plaid-unlink', {
        body: { account_id: accountId },
      });
      if (error) throw error;
      return { data, error: null };
    } catch (err: any) {
      return { data: null, error: err };
    }
  },
};

import { serve } from "https://deno.land/std@0.168.0/http/server.ts";
import { corsHeaders, handleCors } from "../_shared/cors.ts";
import { verifyAdminAuth, createSupabaseClient, logAdminActivity } from "../_shared/admin-utils.ts";

const SUPABASE_URL = Deno.env.get("SUPABASE_URL") || "";
const SUPABASE_SERVICE_KEY = Deno.env.get("SUPABASE_SERVICE_ROLE_KEY") || "";

serve(async (req: Request) => {
  const corsResponse = handleCors(req);
  if (corsResponse) return corsResponse;

  try {
    // Verify admin authentication
    const authHeader = req.headers.get("authorization");
    if (!authHeader) {
      return new Response(
        JSON.stringify({ error: "Missing authorization header" }),
        {
          status: 401,
          headers: { ...corsHeaders, "Content-Type": "application/json" },
        }
      );
    }

    const token = authHeader.replace("Bearer ", "");
    const admin = await verifyAdminAuth(SUPABASE_URL, SUPABASE_SERVICE_KEY, token);

    if (req.method !== "POST") {
      return new Response(
        JSON.stringify({ error: "Method not allowed" }),
        {
          status: 405,
          headers: { ...corsHeaders, "Content-Type": "application/json" },
        }
      );
    }

    const body = await req.json();
    const { action, data } = body;

    if (!action || !data) {
      return new Response(
        JSON.stringify({ error: "Missing action or data" }),
        {
          status: 400,
          headers: { ...corsHeaders, "Content-Type": "application/json" },
        }
      );
    }

    const supabase = createSupabaseClient(SUPABASE_URL, SUPABASE_SERVICE_KEY);
    const clientIp = req.headers.get("x-forwarded-for") || "unknown";

    switch (action) {
      case "disable_user": {
        const { userId } = data;
        if (!userId) {
          return new Response(
            JSON.stringify({ error: "Missing userId" }),
            {
              status: 400,
              headers: { ...corsHeaders, "Content-Type": "application/json" },
            }
          );
        }

        // Update user
        const { error: updateError } = await supabase
          .from("users")
          .update({ is_active: false, updated_at: new Date().toISOString() })
          .eq("id", userId);

        if (updateError) throw updateError;

        // Log activity
        await logAdminActivity(supabase, {
          admin_id: admin.id,
          action: "disable_user",
          target_type: "user",
          target_id: userId,
          details: { reason: data.reason || null },
          ip_address: clientIp,
        });

        return new Response(
          JSON.stringify({
            success: true,
            message: `User ${userId} has been disabled`,
          }),
          { headers: { ...corsHeaders, "Content-Type": "application/json" } }
        );
      }

      case "enable_user": {
        const { userId } = data;
        if (!userId) {
          return new Response(
            JSON.stringify({ error: "Missing userId" }),
            {
              status: 400,
              headers: { ...corsHeaders, "Content-Type": "application/json" },
            }
          );
        }

        // Update user
        const { error: updateError } = await supabase
          .from("users")
          .update({ is_active: true, updated_at: new Date().toISOString() })
          .eq("id", userId);

        if (updateError) throw updateError;

        // Log activity
        await logAdminActivity(supabase, {
          admin_id: admin.id,
          action: "enable_user",
          target_type: "user",
          target_id: userId,
          details: {},
          ip_address: clientIp,
        });

        return new Response(
          JSON.stringify({
            success: true,
            message: `User ${userId} has been enabled`,
          }),
          { headers: { ...corsHeaders, "Content-Type": "application/json" } }
        );
      }

      case "update_user": {
        const { userId, updates } = data;
        if (!userId || !updates) {
          return new Response(
            JSON.stringify({ error: "Missing userId or updates" }),
            {
              status: 400,
              headers: { ...corsHeaders, "Content-Type": "application/json" },
            }
          );
        }

        // Allowed fields to update
        const allowedFields = [
          "full_name",
          "email",
          "income_amount",
          "income_cadence",
          "pay_day",
          "timezone",
        ];
        const safeUpdates: Record<string, any> = {
          updated_at: new Date().toISOString(),
        };

        for (const [key, value] of Object.entries(updates)) {
          if (allowedFields.includes(key)) {
            safeUpdates[key] = value;
          }
        }

        const { data: updatedUser, error: updateError } = await supabase
          .from("users")
          .update(safeUpdates)
          .eq("id", userId)
          .select();

        if (updateError) throw updateError;

        // Log activity
        await logAdminActivity(supabase, {
          admin_id: admin.id,
          action: "update_user",
          target_type: "user",
          target_id: userId,
          details: { updated_fields: Object.keys(safeUpdates) },
          ip_address: clientIp,
        });

        return new Response(
          JSON.stringify({
            success: true,
            message: "User updated successfully",
            user: updatedUser[0],
          }),
          { headers: { ...corsHeaders, "Content-Type": "application/json" } }
        );
      }

      case "reset_password": {
        const { userId, newPassword } = data;
        if (!userId || !newPassword) {
          return new Response(
            JSON.stringify({ error: "Missing userId or newPassword" }),
            {
              status: 400,
              headers: { ...corsHeaders, "Content-Type": "application/json" },
            }
          );
        }

        // Get user's email
        const { data: user } = await supabase
          .from("users")
          .select("email")
          .eq("id", userId)
          .single();

        if (!user) {
          return new Response(
            JSON.stringify({ error: "User not found" }),
            {
              status: 404,
              headers: { ...corsHeaders, "Content-Type": "application/json" },
            }
          );
        }

        // Update password in auth
        const { error: passwordError } = await supabase.auth.admin.updateUserById(
          userId,
          { password: newPassword }
        );

        if (passwordError) {
          throw passwordError;
        }

        // Log activity
        await logAdminActivity(supabase, {
          admin_id: admin.id,
          action: "reset_password",
          target_type: "user",
          target_id: userId,
          details: { email: user.email },
          ip_address: clientIp,
        });

        return new Response(
          JSON.stringify({
            success: true,
            message: `Password reset for user ${user.email}`,
          }),
          { headers: { ...corsHeaders, "Content-Type": "application/json" } }
        );
      }

      case "update_subscription": {
        const { userId, subscriptionId, status } = data;
        if (!userId || !subscriptionId || !status) {
          return new Response(
            JSON.stringify({
              error: "Missing userId, subscriptionId, or status",
            }),
            {
              status: 400,
              headers: { ...corsHeaders, "Content-Type": "application/json" },
            }
          );
        }

        const validStatuses = ["active", "paused", "canceled"];
        if (!validStatuses.includes(status)) {
          return new Response(
            JSON.stringify({ error: "Invalid subscription status" }),
            {
              status: 400,
              headers: { ...corsHeaders, "Content-Type": "application/json" },
            }
          );
        }

        // Update subscription
        const { data: subscription, error: updateError } = await supabase
          .from("subscriptions")
          .update({ status, updated_at: new Date().toISOString() })
          .eq("id", subscriptionId)
          .eq("user_id", userId)
          .select();

        if (updateError) throw updateError;
        if (!subscription || subscription.length === 0) {
          return new Response(
            JSON.stringify({ error: "Subscription not found" }),
            {
              status: 404,
              headers: { ...corsHeaders, "Content-Type": "application/json" },
            }
          );
        }

        // Update user's premium status if needed
        if (status === "canceled") {
          await supabase
            .from("users")
            .update({ is_premium: false })
            .eq("id", userId);
        } else if (status === "active") {
          await supabase
            .from("users")
            .update({ is_premium: true })
            .eq("id", userId);
        }

        // Log activity
        await logAdminActivity(supabase, {
          admin_id: admin.id,
          action: "update_subscription",
          target_type: "subscription",
          target_id: subscriptionId,
          details: { userId, newStatus: status },
          ip_address: clientIp,
        });

        return new Response(
          JSON.stringify({
            success: true,
            message: `Subscription status updated to ${status}`,
            subscription: subscription[0],
          }),
          { headers: { ...corsHeaders, "Content-Type": "application/json" } }
        );
      }

      case "update_settings": {
        const { key, value } = data;
        if (!key || value === undefined) {
          return new Response(
            JSON.stringify({ error: "Missing key or value" }),
            {
              status: 400,
              headers: { ...corsHeaders, "Content-Type": "application/json" },
            }
          );
        }

        // Update setting
        const { data: setting, error: updateError } = await supabase
          .from("app_settings")
          .upsert(
            {
              key,
              value: typeof value === "string" ? JSON.parse(value) : value,
              updated_by: admin.id,
              updated_at: new Date().toISOString(),
            },
            { onConflict: "key" }
          )
          .select();

        if (updateError) throw updateError;

        // Log activity
        await logAdminActivity(supabase, {
          admin_id: admin.id,
          action: "update_settings",
          target_type: "setting",
          target_id: key,
          details: { newValue: value },
          ip_address: clientIp,
        });

        return new Response(
          JSON.stringify({
            success: true,
            message: `Setting ${key} updated`,
            setting: setting[0],
          }),
          { headers: { ...corsHeaders, "Content-Type": "application/json" } }
        );
      }

      case "create_support_ticket": {
        const { userId, subject, description, priority } = data;
        if (!userId || !subject) {
          return new Response(
            JSON.stringify({ error: "Missing userId or subject" }),
            {
              status: 400,
              headers: { ...corsHeaders, "Content-Type": "application/json" },
            }
          );
        }

        const { data: ticket, error: insertError } = await supabase
          .from("support_tickets")
          .insert({
            user_id: userId,
            subject,
            description: description || null,
            priority: priority || "medium",
            status: "open",
            assigned_to: admin.id,
            created_at: new Date().toISOString(),
            updated_at: new Date().toISOString(),
          })
          .select();

        if (insertError) throw insertError;

        // Log activity
        await logAdminActivity(supabase, {
          admin_id: admin.id,
          action: "create_support_ticket",
          target_type: "ticket",
          target_id: ticket[0].id,
          details: { userId, subject },
          ip_address: clientIp,
        });

        return new Response(
          JSON.stringify({
            success: true,
            message: "Support ticket created",
            ticket: ticket[0],
          }),
          { headers: { ...corsHeaders, "Content-Type": "application/json" } }
        );
      }

      case "update_ticket": {
        const { ticketId, updates } = data;
        if (!ticketId || !updates) {
          return new Response(
            JSON.stringify({ error: "Missing ticketId or updates" }),
            {
              status: 400,
              headers: { ...corsHeaders, "Content-Type": "application/json" },
            }
          );
        }

        const allowedFields = ["status", "priority", "notes", "assigned_to"];
        const safeUpdates: Record<string, any> = {
          updated_at: new Date().toISOString(),
        };

        for (const [key, value] of Object.entries(updates)) {
          if (allowedFields.includes(key)) {
            safeUpdates[key] = value;
          }
        }

        const { data: ticket, error: updateError } = await supabase
          .from("support_tickets")
          .update(safeUpdates)
          .eq("id", ticketId)
          .select();

        if (updateError) throw updateError;

        // Log activity
        await logAdminActivity(supabase, {
          admin_id: admin.id,
          action: "update_ticket",
          target_type: "ticket",
          target_id: ticketId,
          details: { updated_fields: Object.keys(safeUpdates) },
          ip_address: clientIp,
        });

        return new Response(
          JSON.stringify({
            success: true,
            message: "Support ticket updated",
            ticket: ticket[0],
          }),
          { headers: { ...corsHeaders, "Content-Type": "application/json" } }
        );
      }

      case "export_user_data": {
        const { userId } = data;
        if (!userId) {
          return new Response(
            JSON.stringify({ error: "Missing userId" }),
            {
              status: 400,
              headers: { ...corsHeaders, "Content-Type": "application/json" },
            }
          );
        }

        // Get user data
        const { data: user } = await supabase
          .from("users")
          .select("*")
          .eq("id", userId)
          .single();

        if (!user) {
          return new Response(
            JSON.stringify({ error: "User not found" }),
            {
              status: 404,
              headers: { ...corsHeaders, "Content-Type": "application/json" },
            }
          );
        }

        // Get user's bills
        const { data: bills } = await supabase
          .from("bills")
          .select("*")
          .eq("user_id", userId);

        // Get user's transactions
        const { data: transactions } = await supabase
          .from("transactions")
          .select("*")
          .eq("user_id", userId);

        // Get user's subscriptions
        const { data: subscriptions } = await supabase
          .from("subscriptions")
          .select("*")
          .eq("user_id", userId);

        const exportData = {
          user,
          bills,
          transactions,
          subscriptions,
          exportedAt: new Date().toISOString(),
        };

        // Log activity
        await logAdminActivity(supabase, {
          admin_id: admin.id,
          action: "export_user_data",
          target_type: "user",
          target_id: userId,
          details: { exportedAt: new Date().toISOString() },
          ip_address: clientIp,
        });

        return new Response(JSON.stringify(exportData), {
          headers: {
            ...corsHeaders,
            "Content-Type": "application/json",
            "Content-Disposition": `attachment; filename="user_${userId}_export.json"`,
          },
        });
      }

      case "toggle_maintenance": {
        const { enabled } = data;
        if (enabled === undefined) {
          return new Response(
            JSON.stringify({ error: "Missing enabled flag" }),
            {
              status: 400,
              headers: { ...corsHeaders, "Content-Type": "application/json" },
            }
          );
        }

        const { data: setting, error: updateError } = await supabase
          .from("app_settings")
          .upsert(
            {
              key: "maintenance_mode",
              value: enabled,
              updated_by: admin.id,
              updated_at: new Date().toISOString(),
            },
            { onConflict: "key" }
          )
          .select();

        if (updateError) throw updateError;

        // Log activity
        await logAdminActivity(supabase, {
          admin_id: admin.id,
          action: "toggle_maintenance",
          target_type: "setting",
          target_id: "maintenance_mode",
          details: { enabled },
          ip_address: clientIp,
        });

        return new Response(
          JSON.stringify({
            success: true,
            message: enabled
              ? "Maintenance mode enabled"
              : "Maintenance mode disabled",
            setting: setting[0],
          }),
          { headers: { ...corsHeaders, "Content-Type": "application/json" } }
        );
      }

      default:
        return new Response(
          JSON.stringify({ error: "Unknown action" }),
          {
            status: 400,
            headers: { ...corsHeaders, "Content-Type": "application/json" },
          }
        );
    }
  } catch (error) {
    console.error("Admin action error:", error);
    return new Response(
      JSON.stringify({
        error: error instanceof Error ? error.message : "Internal server error",
      }),
      {
        status: 500,
        headers: { ...corsHeaders, "Content-Type": "application/json" },
      }
    );
  }
});

/**
 * Stripe integration service for payments and subscriptions
 */

import { supabase } from './supabase';

export const StripeService = {
  /**
   * Create a payment intent for one-time payments
   */
  async createPaymentIntent(amount: number, billId: string, paymentMethodId?: string) {
    try {
      const { data, error } = await supabase.functions.invoke('create-payment-intent', {
        body: {
          amount,
          bill_id: billId,
          payment_method_id: paymentMethodId,
        },
      });
      if (error) throw error;
      return { data, error: null };
    } catch (err: any) {
      return { data: null, error: err };
    }
  },

  /**
   * Confirm a payment intent
   */
  async confirmPayment(paymentIntentId: string) {
    try {
      const { data, error } = await supabase.functions.invoke('confirm-payment', {
        body: { payment_intent_id: paymentIntentId },
      });
      if (error) throw error;
      return { data, error: null };
    } catch (err: any) {
      return { data: null, error: err };
    }
  },

  /**
   * Get user's saved payment methods
   */
  async getPaymentMethods() {
    try {
      const { data, error } = await supabase.functions.invoke('payment-methods', {
        body: { action: 'list' },
      });
      if (error) throw error;
      return { data: data?.payment_methods || [], error: null };
    } catch (err: any) {
      return { data: [], error: err };
    }
  },

  /**
   * Add a new payment method
   */
  async addPaymentMethod(token: string) {
    try {
      const { data, error } = await supabase.functions.invoke('payment-methods', {
        body: { action: 'attach', token },
      });
      if (error) throw error;
      return { data, error: null };
    } catch (err: any) {
      return { data: null, error: err };
    }
  },

  /**
   * Remove a payment method
   */
  async removePaymentMethod(id: string) {
    try {
      const { data, error } = await supabase.functions.invoke('payment-methods', {
        body: { action: 'detach', payment_method_id: id },
      });
      if (error) throw error;
      return { data, error: null };
    } catch (err: any) {
      return { data: null, error: err };
    }
  },

  /**
   * Set a payment method as default
   */
  async setDefaultPaymentMethod(paymentMethodId: string) {
    try {
      const { data, error } = await supabase.functions.invoke('payment-methods', {
        body: { action: 'set_default', payment_method_id: paymentMethodId },
      });
      if (error) throw error;
      return { data, error: null };
    } catch (err: any) {
      return { data: null, error: err };
    }
  },

  /**
   * Create a subscription for recurring payments
   */
  async createSubscription(priceId: string, paymentMethodId: string) {
    try {
      const { data, error } = await supabase.functions.invoke('create-subscription', {
        body: { price_id: priceId, payment_method_id: paymentMethodId },
      });
      if (error) throw error;
      return { data, error: null };
    } catch (err: any) {
      return { data: null, error: err };
    }
  },

  /**
   * Cancel a subscription
   */
  async cancelSubscription(subscriptionId: string) {
    try {
      const { data, error } = await supabase.functions.invoke('create-subscription', {
        body: { action: 'cancel', subscription_id: subscriptionId },
      });
      if (error) throw error;
      return { data, error: null };
    } catch (err: any) {
      return { data: null, error: err };
    }
  },

  /**
   * Update a subscription
   */
  async updateSubscription(subscriptionId: string, updates: Record<string, any>) {
    try {
      const { data, error } = await supabase.functions.invoke('create-subscription', {
        body: {
          action: 'update',
          subscription_id: subscriptionId,
          ...updates,
        },
      });
      if (error) throw error;
      return { data, error: null };
    } catch (err: any) {
      return { data: null, error: err };
    }
  },

  /**
   * Get invoice history
   */
  async getInvoices() {
    try {
      const { data, error } = await supabase.functions.invoke('invoices', {
        body: { action: 'list' },
      });
      if (error) throw error;
      return { data: data?.invoices || [], error: null };
    } catch (err: any) {
      return { data: [], error: err };
    }
  },

  /**
   * Download invoice PDF
   */
  async downloadInvoice(invoiceId: string) {
    try {
      const { data, error } = await supabase.functions.invoke('invoices', {
        body: { action: 'download', invoice_id: invoiceId },
      });
      if (error) throw error;
      return { data, error: null };
    } catch (err: any) {
      return { data: null, error: err };
    }
  },
};

import React, { useEffect, useState } from 'react';
import { useParams, useNavigate } from 'react-router-dom';
import { DataTable, StatusBadge, Modal } from '../components';
import { adminApi } from '../lib/supabase';
import type { AdminUser, AdminBill, AdminTransaction } from '../types';
import {
  ArrowLeft,
  User,
  Mail,
  Calendar,
  TrendingUp,
  AlertCircle,
  Lock,
  MoreVertical,
} from 'lucide-react';
import { formatDistanceToNow, format } from 'date-fns';

export const UserDetail: React.FC = () => {
  const { userId } = useParams<{ userId: string }>();
  const navigate = useNavigate();

  const [user, setUser] = useState<AdminUser | null>(null);
  const [bills, setBills] = useState<AdminBill[]>([]);
  const [transactions, setTransactions] = useState<AdminTransaction[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [activeTab, setActiveTab] = useState<'bills' | 'transactions' | 'activity'>('bills');
  const [showActionModal, setShowActionModal] = useState(false);
  const [actionType, setActionType] = useState<string>('');

  useEffect(() => {
    const fetchUserData = async () => {
      if (!userId) return;

      try {
        setLoading(true);
        setError(null);

        const [userRes, billsRes, transRes] = await Promise.all([
          adminApi.getUserById(userId),
          adminApi.getUserBills(userId),
          adminApi.getUserTransactions(userId),
        ]);

        if (userRes.success && userRes.data) {
          setUser(userRes.data);
        } else {
          setError('Failed to load user');
        }

        if (billsRes.success) setBills(billsRes.data);
        if (transRes.success) setTransactions(transRes.data);
      } catch (err) {
        setError('An error occurred while loading user data');
        console.error(err);
      } finally {
        setLoading(false);
      }
    };

    fetchUserData();
  }, [userId]);

  const handleAction = async () => {
    if (!user) return;

    try {
      if (actionType === 'disable') {
        await adminApi.disableUser(user.id);
        setUser({ ...user, is_active: false });
      }
      setShowActionModal(false);
      setActionType('');
    } catch (err) {
      setError('Failed to perform action');
    }
  };

  if (loading) {
    return (
      <div className="animate-pulse space-y-6">
        <div className="h-32 bg-slate-800 rounded-lg" />
        <div className="h-64 bg-slate-800 rounded-lg" />
      </div>
