          <p className="text-2xl font-bold text-blue-400">{user.current_streak} days</p>
        </div>
        <div className="bg-slate-800 rounded-lg border border-slate-700 p-4">
          <p className="text-slate-400 text-sm mb-2">Subscription</p>
          <p className="text-sm font-semibold text-slate-50 capitalize">
            {user.subscription_status}
          </p>
        </div>
      </div>

      {/* Tabs */}
      <div className="border-b border-slate-700">
        <div className="flex gap-8">
          {['bills', 'transactions', 'activity'].map((tab) => (
            <button
              key={tab}
              onClick={() => setActiveTab(tab as any)}
              className={`py-3 px-1 border-b-2 font-medium transition-colors ${
                activeTab === tab
                  ? 'border-emerald-500 text-emerald-400'
                  : 'border-transparent text-slate-400 hover:text-slate-200'
              }`}
            >
              {tab.charAt(0).toUpperCase() + tab.slice(1)}
            </button>
          ))}
        </div>
      </div>

      {/* Tab Content */}
      {activeTab === 'bills' && (
        <DataTable
          columns={billColumns}
          data={bills}
          loading={false}
        />
      )}

      {activeTab === 'transactions' && (
        <DataTable
          columns={transactionColumns}
          data={transactions}
          loading={false}
        />
      )}

      {activeTab === 'activity' && (
        <div className="bg-slate-800 rounded-lg border border-slate-700 p-6">
          <p className="text-slate-400">Activity log coming soon</p>
        </div>
      )}

      {/* Action Modal */}
      <Modal
        isOpen={showActionModal}
        onClose={() => {
          setShowActionModal(false);
          setActionType('');
        }}
        title={
          actionType === 'disable'
            ? 'Disable Account'
            : actionType === 'reset-password'
              ? 'Reset Password'
              : 'Confirm Action'
        }
        footer={
          <div className="flex gap-3 justify-end">
            <button
              onClick={() => {
                setShowActionModal(false);
                setActionType('');
              }}
              className="px-4 py-2 rounded-lg bg-slate-700 text-slate-200 hover:bg-slate-600"
            >
              Cancel
            </button>
            <button
              onClick={handleAction}
              className="px-4 py-2 rounded-lg bg-emerald-600 text-white hover:bg-emerald-700"
            >
              Confirm
            </button>
          </div>
        }
      >
        {actionType === 'disable' && (
          <div className="space-y-4">
            <p className="text-slate-300">
              Are you sure you want to disable this account? The user will not be able to access
              their account until it's re-enabled.
            </p>
            <div className="bg-yellow-900 border border-yellow-700 rounded-lg p-3 flex gap-3">
              <AlertCircle className="w-5 h-5 text-yellow-400 flex-shrink-0 mt-0.5" />
              <p className="text-yellow-300 text-sm">This action is reversible.</p>
            </div>
          </div>
        )}
        {actionType === 'reset-password' && (
          <div className="space-y-4">
            <p className="text-slate-300">
              A password reset link will be sent to {user.email}. They'll receive an email with
              instructions to set a new password.
            </p>
            <div className="bg-blue-900 border border-blue-700 rounded-lg p-3 flex gap-3">
              <AlertCircle className="w-5 h-5 text-blue-400 flex-shrink-0 mt-0.5" />
              <p className="text-blue-300 text-sm">Email will be sent immediately.</p>
            </div>
          </div>
        )}
      </Modal>
    </div>
  );
};

/**
 * Push notifications service for Expo
 * Handles registration, scheduling, and management of push notifications
 */

import * as Notifications from 'expo-notifications';
import * as Device from 'expo-device';
import { Platform } from 'react-native';
import { supabase } from './supabase';

// Configure notification handler behavior
Notifications.setNotificationHandler({
  handleNotification: async () => ({
    shouldShowAlert: true,
    shouldPlaySound: true,
    shouldSetBadge: true,
  }),
});

export const PushNotificationService = {
  /**
   * Register device for push notifications
   * Must be called once during app initialization
   */
  async registerForPushNotifications() {
    try {
      // Only works on physical devices
      if (!Device.isDevice) {
        console.log('Push notifications only work on physical devices');
        return null;
      }

      // Check current permission status
      const { status: existingStatus } = await Notifications.getPermissionsAsync();
      let finalStatus = existingStatus;

      // Request permission if not already granted
      if (existingStatus !== 'granted') {
        const { status } = await Notifications.requestPermissionsAsync();
        finalStatus = status;
      }

      if (finalStatus !== 'granted') {
        console.log('Failed to get push notification permissions');
        return null;
      }

      // Get the Expo push token
      const token = await Notifications.getExpoPushTokenAsync();

      // Save token to user profile in Supabase
      const { data: { user } } = await supabase.auth.getUser();
      if (user) {
        await supabase
          .from('profiles')
          .update({ push_token: token.data })
          .eq('id', user.id)
          .catch((err) => console.log('Failed to save push token:', err));
      }

      // Configure Android notification channel
      if (Platform.OS === 'android') {
        Notifications.setNotificationChannelAsync('default', {
          name: 'default',
          importance: Notifications.AndroidImportance.MAX,
          vibrationPattern: [0, 250, 250, 250],
          lightColor: '#FF231F7F',
        });
      }

      return token.data;
    } catch (err) {
      console.error('Error registering for push notifications:', err);
      return null;
    }
  },

  /**
   * Schedule a bill due reminder
   * Notification fires 3 days before due date
   */
  async scheduleBillReminder(billName: string, dueDate: Date, amount: number) {
    try {
      const reminderDate = new Date(dueDate.getTime() - 3 * 24 * 60 * 60 * 1000);

      await Notifications.scheduleNotificationAsync({
        content: {
          title: `${billName} Due Soon`,
          body: `Your ${billName} ($${amount}) is due on ${dueDate.toLocaleDateString()}`,
          sound: 'default',
          data: { type: 'bill_reminder', billName },
        },
        trigger: reminderDate,
      });

      return { success: true, error: null };
    } catch (err) {
      return { success: false, error: err };
    }
  },

  /**
   * Schedule daily contribution reminder
   * Fires at 9:00 AM every day
   */
  async scheduleContributionReminder() {
    try {
      await Notifications.scheduleNotificationAsync({
        content: {
          title: 'Daily Contribution Reminder',
          body: 'Time to contribute to your bills!',
          sound: 'default',
          data: { type: 'contribution_reminder' },
        },
        trigger: {
          hour: 9,
          minute: 0,
          repeats: true,
        },
      });

      return { success: true, error: null };
    } catch (err) {
      return { success: false, error: err };
    }
  },

  /**
   * Schedule a custom notification
   */
  async scheduleNotification(title: string, body: string, delaySeconds: number = 10, data: any = {}) {
    try {
      await Notifications.scheduleNotificationAsync({
        content: {
          title,
          body,
          sound: 'default',
          data,
        },
        trigger: { seconds: delaySeconds },
      });

      return { success: true, error: null };
    } catch (err) {
      return { success: false, error: err };
    }
  },

  /**
   * Cancel a scheduled notification by ID
   */
  async cancelNotification(notificationId: string) {
    try {
      await Notifications.cancelScheduledNotificationAsync(notificationId);
      return { success: true, error: null };
    } catch (err) {
      return { success: false, error: err };
    }
  },

  /**
   * Cancel all scheduled notifications
   */
  async cancelAllScheduled() {
    try {
      await Notifications.cancelAllScheduledNotificationsAsync();
      return { success: true, error: null };
    } catch (err) {
      return { success: false, error: err };
    }
  },

  /**
   * Set up notification listeners for handling notifications
   * Returns cleanup function
   */
  setupNotificationListeners(handlers: {
    onNotificationReceived?: (notification: Notifications.Notification) => void;
    onNotificationResponseReceived?: (response: Notifications.NotificationResponse) => void;
  }) {
    const subscriptions = [];

    // Listen for notifications while app is in foreground
    if (handlers.onNotificationReceived) {
      subscriptions.push(
        Notifications.addNotificationReceivedListener((notification) => {
          handlers.onNotificationReceived?.(notification);
        })
      );
    }

    // Listen for notification interactions
    if (handlers.onNotificationResponseReceived) {
      subscriptions.push(
        Notifications.addNotificationResponseReceivedListener((response) => {
          handlers.onNotificationResponseReceived?.(response);
        })
      );
    }

    // Return cleanup function
    return () => {
      subscriptions.forEach((sub) => sub.remove());
    };
  },

  /**
   * Get all scheduled notifications
   */
  async getScheduledNotifications() {
    try {
      const notifications = await Notifications.getAllScheduledNotificationsAsync();
      return { data: notifications, error: null };
    } catch (err) {
      return { data: [], error: err };
    }
  },

  /**
   * Send a test notification
   */
  async sendTestNotification() {
    try {
      await Notifications.scheduleNotificationAsync({
        content: {
          title: 'Test Notification',
          body: 'This is a test notification',
          sound: 'default',
        },
        trigger: { seconds: 2 },
      });

      return { success: true, error: null };
    } catch (err) {
      return { success: false, error: err };
    }
  },
};

