import React, { useEffect, useState } from 'react';
import { DataTable, StatusBadge, Chart } from '../components';
import { adminApi } from '../lib/supabase';
import type { AdminBill, ChartDataPoint } from '../types';
import { AlertCircle, BarChart3, DollarSign, Percent, Grid3X3 } from 'lucide-react';
import { format } from 'date-fns';

export const Bills: React.FC = () => {
  const [bills, setBills] = useState<AdminBill[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [search, setSearch] = useState('');
  const [page, setPage] = useState(1);
  const [total, setTotal] = useState(0);
  const [status, setStatus] = useState('');
  const [category, setCategory] = useState('');
  const [categoryData, setCategoryData] = useState<ChartDataPoint[]>([]);

  const pageSize = 20;

  useEffect(() => {
    const fetchBills = async () => {
      try {
        setLoading(true);
        setError(null);

        const filters: any = {};
        if (status) filters.status = status;
        if (category) filters.category = category;

        const result = await adminApi.getBills(page, pageSize, filters);

        if (result.success) {
          setBills(result.data);
          setTotal(result.pagination?.total || 0);
        } else {
          setError(result.error || 'Failed to fetch bills');
        }
      } catch (err) {
        setError('An error occurred while fetching bills');
        console.error(err);
      } finally {
        setLoading(false);
      }
    };

    const fetchCategoryBreakdown = async () => {
      const result = await adminApi.getCategoryBreakdown();
      if (result.success) {
        setCategoryData(result.data);
      }
    };

    fetchBills();
    fetchCategoryBreakdown();
  }, [page, status, category]);

  const calculateStats = () => {
    const totalBills = total;
    const avgAmount =
      bills.length > 0
        ? bills.reduce((sum, b) => sum + b.amount, 0) / bills.length
        : 0;
    const successCount = bills.filter((b) => b.funding_percentage >= 80).length;
    const successRate =
      bills.length > 0 ? ((successCount / bills.length) * 100).toFixed(1) : '0';

    return {
      totalBills,
      avgAmount,
      successRate,
    };
  };

  const stats = calculateStats();
  const categories = ['Housing', 'Utilities', 'Insurance', 'Subscriptions', 'Phone', 'Internet'];

  const columns = [
    {
      key: 'name' as const,
      label: 'Bill Name',
      sortable: true,
    },
    {
      key: 'user_id' as const,
      label: 'User',
      render: () => <span className="text-slate-400">User ID</span>,
    },
    {
      key: 'amount' as const,
      label: 'Amount',
      render: (value: number) => (
        <span className="font-semibold text-slate-50">${value.toFixed(2)}</span>
      ),
    },
    {
      key: 'due_date' as const,
      label: 'Due Date',
      render: (value: string) => format(new Date(value), 'MMM dd, yyyy'),
    },
    {
      key: 'category' as const,
      label: 'Category',
      render: (value: string) => (
        <span className="px-2 py-1 bg-slate-700 text-slate-200 rounded text-xs">
          {value}
        </span>
      ),
    },
    {
      key: 'funding_percentage' as const,
      label: 'Funded',
      render: (value: number) => (
        <div className="flex items-center gap-2">
          <div className="w-20 bg-slate-700 rounded-full h-1.5">
            <div
              className={`h-1.5 rounded-full ${value >= 80 ? 'bg-emerald-500' : value >= 50 ? 'bg-amber-500' : 'bg-red-500'}`}
              style={{ width: `${value}%` }}
            />
          </div>
          <span className="text-sm text-slate-300 w-10">{value}%</span>
        </div>
      ),
    },
    {
      key: 'status' as const,
      label: 'Status',
      render: (value: string) => <StatusBadge status={value} />,
    },
  ];

  return (
    <div className="space-y-6">
      {/* Header */}
      <div>
        <h1 className="text-3xl font-bold text-slate-50">Bills</h1>
        <p className="text-slate-400 mt-1">Manage bills and track funding progress</p>
      </div>

      {/* Overview Stats */}
      <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
        <div className="bg-slate-800 rounded-lg border border-slate-700 p-6">
          <div className="flex items-start justify-between">
            <div>
              <p className="text-slate-400 text-sm mb-2">Total Bills</p>
              <p className="text-3xl font-bold text-slate-50">{stats.totalBills.toLocaleString()}</p>
            </div>
            <Grid3X3 className="w-6 h-6 text-blue-400" />
          </div>
        </div>

        <div className="bg-slate-800 rounded-lg border border-slate-700 p-6">
          <div className="flex items-start justify-between">
            <div>
              <p className="text-slate-400 text-sm mb-2">Avg Bill Amount</p>
              <p className="text-3xl font-bold text-slate-50">${stats.avgAmount.toFixed(2)}</p>
            </div>
            <DollarSign className="w-6 h-6 text-emerald-400" />
          </div>
        </div>

        <div className="bg-slate-800 rounded-lg border border-slate-700 p-6">
          <div className="flex items-start justify-between">
            <div>
              <p className="text-slate-400 text-sm mb-2">Success Rate</p>
              <p className="text-3xl font-bold text-slate-50">{stats.successRate}%</p>
            </div>
            <Percent className="w-6 h-6 text-purple-400" />
          </div>
        </div>
      </div>

      {/* Category Chart */}
      <Chart
        type="bar"
        data={categoryData}
        title="Bills by Category"
        dataKey="count"
        xAxisKey="category"
        color="#00D998"
        height={300}
      />

      {/* Filters */}
      <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
        <div>
          <label className="block text-sm font-medium text-slate-200 mb-2">
            Category
          </label>
          <select
            value={category}
            onChange={(e) => {
              setCategory(e.target.value);
              setPage(1);
            }}
            className="w-full px-4 py-2 bg-slate-700 border border-slate-600 rounded-lg text-slate-50 focus:outline-none focus:ring-2 focus:ring-emerald-500"
          >
            <option value="">All Categories</option>
            {categories.map((cat) => (
              <option key={cat} value={cat}>
                {cat}
              </option>
            ))}
          </select>
        </div>

        <div>
          <label className="block text-sm font-medium text-slate-200 mb-2">
            Status
          </label>
          <select
            value={status}
            onChange={(e) => {
              setStatus(e.target.value);
              setPage(1);
            }}
            className="w-full px-4 py-2 bg-slate-700 border border-slate-600 rounded-lg text-slate-50 focus:outline-none focus:ring-2 focus:ring-emerald-500"
          >
            <option value="">All Status</option>
            <option value="active">Active</option>
            <option value="paid">Paid</option>
            <option value="overdue">Overdue</option>
            <option value="cancelled">Cancelled</option>
          </select>
        </div>

        <div>
          <label className="block text-sm font-medium text-slate-200 mb-2">
            Funding
          </label>
          <select
            className="w-full px-4 py-2 bg-slate-700 border border-slate-600 rounded-lg text-slate-50 focus:outline-none focus:ring-2 focus:ring-emerald-500"
          >
            <option>All Funding Levels</option>
            <option>0-25% Funded</option>
            <option>25-50% Funded</option>
            <option>50-75% Funded</option>
            <option>75%+ Funded</option>
          </select>
        </div>
      </div>

      {/* Error Alert */}
      {error && (
        <div className="bg-red-900 border border-red-700 rounded-lg p-4 flex gap-3">
          <AlertCircle className="w-5 h-5 text-red-400 flex-shrink-0 mt-0.5" />
          <p className="text-red-300">{error}</p>
        </div>
      )}

      {/* Data Table */}
      <DataTable
        columns={columns}
        data={bills}
        loading={loading}
        search={{
          value: search,
          onChange: (value) => {
            setSearch(value);
            setPage(1);
          },
          placeholder: 'Search bills by name...',
        }}
        pagination={{
          current: page,
          total: Math.ceil(total / pageSize),
          pageSize,
          onChange: setPage,
        }}
      />
    </div>
  );
};

