import { serve } from "https://deno.land/std@0.168.0/http/server.ts";
import { corsHeaders, handleCors } from "../_shared/cors.ts";
import { verifyAdminAuth, createSupabaseClient } from "../_shared/admin-utils.ts";

const SUPABASE_URL = Deno.env.get("SUPABASE_URL") || "";
const SUPABASE_SERVICE_KEY = Deno.env.get("SUPABASE_SERVICE_ROLE_KEY") || "";

serve(async (req: Request) => {
  const corsResponse = handleCors(req);
  if (corsResponse) return corsResponse;

  try {
    // Verify admin authentication
    const authHeader = req.headers.get("authorization");
    if (!authHeader) {
      return new Response(
        JSON.stringify({ error: "Missing authorization header" }),
        {
          status: 401,
          headers: { ...corsHeaders, "Content-Type": "application/json" },
        }
      );
    }

    const token = authHeader.replace("Bearer ", "");
    const admin = await verifyAdminAuth(SUPABASE_URL, SUPABASE_SERVICE_KEY, token);

    const supabase = createSupabaseClient(SUPABASE_URL, SUPABASE_SERVICE_KEY);
    const url = new URL(req.url);
    const metric = url.searchParams.get("metric") || "funding-success-rate";

    switch (metric) {
      case "funding-success-rate": {
        const days = parseInt(url.searchParams.get("days") || "30");
        const startDate = new Date(Date.now() - days * 24 * 60 * 60 * 1000).toISOString();

        // Get all bills created in the period
        const { data: allBills } = await supabase
          .from("bills")
          .select("id, category, created_at")
          .gte("created_at", startDate);

        if (!allBills || allBills.length === 0) {
          return new Response(
            JSON.stringify({
              metric: "funding-success-rate",
              period_days: days,
              total_bills: 0,
              fully_funded: 0,
              success_rate: "0%",
              by_category: {},
            }),
            { headers: { ...corsHeaders, "Content-Type": "application/json" } }
          );
        }

        // For each bill, check if fully funded
        let fullyFunded = 0;
        const categoryStats: Record<
          string,
          { total: number; funded: number; rate: string }
        > = {};

        for (const bill of allBills) {
          const { data: contributions } = await supabase
            .from("micro_contributions")
            .select("amount")
            .eq("bill_id", bill.id);

          const { data: billData } = await supabase
            .from("bills")
            .select("amount")
            .eq("id", bill.id)
            .single();

          if (billData && contributions) {
            const totalContributed = contributions.reduce(
              (sum: number, c: any) => sum + Number(c.amount),
              0
            );
            const isFullyFunded = totalContributed >= Number(billData.amount);

            if (isFullyFunded) {
              fullyFunded++;
            }

            const cat = bill.category || "uncategorized";
            if (!categoryStats[cat]) {
              categoryStats[cat] = { total: 0, funded: 0, rate: "0%" };
            }
            categoryStats[cat].total++;
            if (isFullyFunded) {
              categoryStats[cat].funded++;
            }
          }
        }

        // Calculate rates by category
        for (const cat in categoryStats) {
          const stats = categoryStats[cat];
          stats.rate = (((stats.funded / stats.total) * 100).toFixed(1)) + "%";
        }

        const successRate = (((fullyFunded / allBills.length) * 100).toFixed(1)) + "%";

        return new Response(
          JSON.stringify({
            metric: "funding-success-rate",
            period_days: days,
            total_bills: allBills.length,
            fully_funded: fullyFunded,
            success_rate: successRate,
            by_category: categoryStats,
            timestamp: new Date().toISOString(),
          }),
          { headers: { ...corsHeaders, "Content-Type": "application/json" } }
        );
      }

      case "avg-time-to-funding": {
        const days = parseInt(url.searchParams.get("days") || "90");
        const startDate = new Date(Date.now() - days * 24 * 60 * 60 * 1000).toISOString();

        // Get all bills
        const { data: allBills } = await supabase
          .from("bills")
          .select("id, category, created_at, amount")
          .gte("created_at", startDate);

        if (!allBills || allBills.length === 0) {
          return new Response(
            JSON.stringify({
              metric: "avg-time-to-funding",
              period_days: days,
              avg_days: 0,
              by_category: {},
              fully_funded_count: 0,
            }),
            { headers: { ...corsHeaders, "Content-Type": "application/json" } }
          );
        }

        const fundingTimes: number[] = [];
        const categoryTimes: Record<string, number[]> = {};
        let fullyFundedCount = 0;

        for (const bill of allBills) {
          const { data: contributions } = await supabase
            .from("micro_contributions")
            .select("amount, created_at")
            .eq("bill_id", bill.id)
            .order("created_at", { ascending: true });

          if (contributions && contributions.length > 0) {
            // Calculate total funded
            const totalFunded = contributions.reduce(
              (sum: number, c: any) => sum + Number(c.amount),
              0
            );

            if (totalFunded >= Number(bill.amount)) {
              fullyFundedCount++;

              // Find when fully funded
              let runningTotal = 0;
              let fundedDate: string | null = null;

              for (const contrib of contributions) {
                runningTotal += Number(contrib.amount);
                if (runningTotal >= Number(bill.amount)) {
                  fundedDate = contrib.created_at;
                  break;
                }
              }

              if (fundedDate) {
                const billDate = new Date(bill.created_at);
                const fundedDateObj = new Date(fundedDate);
                const daysToFund = (fundedDateObj.getTime() - billDate.getTime()) / (1000 * 60 * 60 * 24);
                fundingTimes.push(daysToFund);

                const cat = bill.category || "uncategorized";
                if (!categoryTimes[cat]) {
                  categoryTimes[cat] = [];
                }
                categoryTimes[cat].push(daysToFund);
              }
            }
          }
        }

        const avgDays = fundingTimes.length > 0
          ? (fundingTimes.reduce((a: number, b: number) => a + b, 0) / fundingTimes.length).toFixed(1)
          : 0;

        const categoryAverages: Record<string, string> = {};
        for (const cat in categoryTimes) {
          const times = categoryTimes[cat];
          const avg = (times.reduce((a, b) => a + b, 0) / times.length).toFixed(1);
          categoryAverages[cat] = avg + " days";
        }

        return new Response(
          JSON.stringify({
            metric: "avg-time-to-funding",
            period_days: days,
            fully_funded_count: fullyFundedCount,
            avg_days: avgDays,
            by_category: categoryAverages,
            timestamp: new Date().toISOString(),
          }),
          { headers: { ...corsHeaders, "Content-Type": "application/json" } }
        );
      }

      case "retention-cohorts": {
        const months = parseInt(url.searchParams.get("months") || "6");
        const cohorts: Record<string, any> = {};

        for (let i = 0; i < months; i++) {
          const cohortDate = new Date();
          cohortDate.setMonth(cohortDate.getMonth() - i);
          const monthStart = new Date(
            cohortDate.getFullYear(),
            cohortDate.getMonth(),
            1
          ).toISOString();
          const monthEnd = new Date(
            cohortDate.getFullYear(),
            cohortDate.getMonth() + 1,
            0
          ).toISOString();

          const cohortKey = cohortDate.toLocaleString("default", {
            month: "short",
            year: "numeric",
          });

          // Users created in this month
          const { data: cohortUsers } = await supabase
            .from("users")
            .select("id")
            .gte("created_at", monthStart)
            .lte("created_at", monthEnd);

          if (!cohortUsers || cohortUsers.length === 0) {
            cohorts[cohortKey] = { created: 0, months: {} };
            continue;
          }

          const cohortSize = cohortUsers.length;
          const cohortIds = cohortUsers.map((u: any) => u.id);
          const months_data: Record<number, number> = {};

          // Check activity in each month after cohort
          for (let j = 0; j < 6; j++) {
            const checkDate = new Date();
            checkDate.setMonth(checkDate.getMonth() - (i - j));
            const checkStart = new Date(
              checkDate.getFullYear(),
              checkDate.getMonth(),
              1
            ).toISOString();
            const checkEnd = new Date(
              checkDate.getFullYear(),
              checkDate.getMonth() + 1,
              0
            ).toISOString();

            // Check if users have activity (bills created or transactions)
            const { data: activeBills } = await supabase
              .from("bills")
              .select("user_id")
              .in("user_id", cohortIds)
              .gte("created_at", checkStart)
              .lte("created_at", checkEnd);

            const { data: activeTransactions } = await supabase
              .from("transactions")
              .select("user_id")
              .in("user_id", cohortIds)
              .gte("created_at", checkStart)
              .lte("created_at", checkEnd);

            const activeUserIds = new Set([
              ...(activeBills?.map((b: any) => b.user_id) || []),
              ...(activeTransactions?.map((t: any) => t.user_id) || []),
            ]);

            months_data[j] = activeUserIds.size;
          }

          cohorts[cohortKey] = {
            created: cohortSize,
            retention: months_data,
          };
        }

        return new Response(
          JSON.stringify({
            metric: "retention-cohorts",
            months_tracked: months,
            cohorts,
            timestamp: new Date().toISOString(),
          }),
          { headers: { ...corsHeaders, "Content-Type": "application/json" } }
        );
      }

      case "payment-methods": {
        // Get distribution of payment methods
        const { data: paymentMethods } = await supabase
          .from("payment_methods")
          .select("type", { count: "exact" });

        const distribution: Record<string, number> = {};
        paymentMethods?.forEach((pm: any) => {
          distribution[pm.type] = (distribution[pm.type] || 0) + 1;
        });

        // Get payment method performance (success rate)
        const performance: Record<string, any> = {};
        const types = Object.keys(distribution);

        for (const type of types) {
          const { data: pmIds } = await supabase
            .from("payment_methods")
            .select("id")
            .eq("type", type);

          if (pmIds && pmIds.length > 0) {
            const pmIdList = pmIds.map((p: any) => p.id);

            const { data: allTxns } = await supabase
              .from("transactions")
              .select("status")
              .in("payment_method_id", pmIdList);

            const completed = allTxns?.filter((t: any) => t.status === "completed").length || 0;
            const total = allTxns?.length || 0;

            performance[type] = {
              count: distribution[type],
              transactions: total,
              success_rate:
                total > 0
                  ? (((completed / total) * 100).toFixed(1)) + "%"
                  : "0%",
            };
          }
        }

        return new Response(
          JSON.stringify({
            metric: "payment-methods",
            total_methods: paymentMethods?.length || 0,
            distribution,
            performance,
            timestamp: new Date().toISOString(),
          }),
          { headers: { ...corsHeaders, "Content-Type": "application/json" } }
        );
      }

      case "activity-peaks": {
        const days = parseInt(url.searchParams.get("days") || "30");
        const startDate = new Date(Date.now() - days * 24 * 60 * 60 * 1000).toISOString();

        // Get all transactions in period
        const { data: transactions } = await supabase
          .from("transactions")
          .select("created_at")
          .gte("created_at", startDate)
          .eq("status", "completed");

        const hourlyActivity: Record<number, number> = {};

        transactions?.forEach((t: any) => {
          const date = new Date(t.created_at);
          const hour = date.getUTCHours();
          hourlyActivity[hour] = (hourlyActivity[hour] || 0) + 1;
        });

        // Also get daily activity
        const dailyActivity: Record<number, number> = {};

        transactions?.forEach((t: any) => {
          const date = new Date(t.created_at);
          const day = date.getUTCDay();
          dailyActivity[day] = (dailyActivity[day] || 0) + 1;
        });

        const dayNames = [
          "Sunday",
          "Monday",
          "Tuesday",
          "Wednesday",
          "Thursday",
          "Friday",
          "Saturday",
        ];
        const dailyLabeled: Record<string, number> = {};

        for (let i = 0; i < 7; i++) {
          dailyLabeled[dayNames[i]] = dailyActivity[i] || 0;
        }

        return new Response(
          JSON.stringify({
            metric: "activity-peaks",
            period_days: days,
            hourly_activity: hourlyActivity,
            daily_activity: dailyLabeled,
            peak_hour: Object.entries(hourlyActivity).sort(
              (a, b) => b[1] - a[1]
            )[0]?.[0],
            peak_day: Object.entries(dailyLabeled).sort(
              (a, b) => b[1] - a[1]
            )[0]?.[0],
            timestamp: new Date().toISOString(),
          }),
          { headers: { ...corsHeaders, "Content-Type": "application/json" } }
        );
      }

      case "geographic-distribution": {
        // Get users and their timezones (proxy for geography)
        const { data: users } = await supabase
          .from("users")
          .select("timezone");

        const tzDistribution: Record<string, number> = {};

        users?.forEach((u: any) => {
          const tz = u.timezone || "UTC";
          tzDistribution[tz] = (tzDistribution[tz] || 0) + 1;
        });

        // Sort by count
        const sorted = Object.entries(tzDistribution)
          .sort((a, b) => b[1] - a[1])
          .slice(0, 20);

        return new Response(
          JSON.stringify({
            metric: "geographic-distribution",
            total_timezones: Object.keys(tzDistribution).length,
            top_locations: Object.fromEntries(sorted),
            all_timezones: tzDistribution,
            timestamp: new Date().toISOString(),
          }),
          { headers: { ...corsHeaders, "Content-Type": "application/json" } }
        );
      }

      case "churn-analysis": {
        const days = parseInt(url.searchParams.get("days") || "90");
        const startDate = new Date(Date.now() - days * 24 * 60 * 60 * 1000).toISOString();

        // Get users who were active in first half of period
        const midDate = new Date(Date.now() - (days / 2) * 24 * 60 * 60 * 1000).toISOString();

        const { data: activeEarly } = await supabase
          .from("transactions")
          .select("user_id")
          .gte("created_at", startDate)
          .lte("created_at", midDate)
          .eq("status", "completed");

        const earlyUserIds = new Set(
          activeEarly?.map((t: any) => t.user_id) || []
        );

        // Check if they were active in second half
        const { data: activeLate } = await supabase
          .from("transactions")
          .select("user_id")
          .gt("created_at", midDate)
          .lte("created_at", new Date().toISOString())
          .eq("status", "completed");

        const lateUserIds = new Set(activeLate?.map((t: any) => t.user_id) || []);

        const retained = Array.from(earlyUserIds).filter((id) =>
          lateUserIds.has(id as string)
        );
        const churned = Array.from(earlyUserIds).filter(
          (id) => !lateUserIds.has(id as string)
        );

        const churnRate = earlyUserIds.size > 0
          ? (((churned.length / earlyUserIds.size) * 100).toFixed(1)) + "%"
          : "0%";

        const retentionRate = earlyUserIds.size > 0
          ? (((retained.length / earlyUserIds.size) * 100).toFixed(1)) + "%"
          : "0%";

        return new Response(
          JSON.stringify({
            metric: "churn-analysis",
            period_days: days,
            active_users_first_half: earlyUserIds.size,
            retained_users: retained.length,
            churned_users: churned.length,
            churn_rate: churnRate,
            retention_rate: retentionRate,
            timestamp: new Date().toISOString(),
          }),
          { headers: { ...corsHeaders, "Content-Type": "application/json" } }
        );
      }

      default:
        return new Response(
          JSON.stringify({ error: "Unknown metric" }),
          {
            status: 400,
            headers: { ...corsHeaders, "Content-Type": "application/json" },
          }
        );
    }
  } catch (error) {
    console.error("Analytics error:", error);
    return new Response(
      JSON.stringify({
        error: error instanceof Error ? error.message : "Internal server error",
      }),
      {
        status: 500,
        headers: { ...corsHeaders, "Content-Type": "application/json" },
      }
    );
  }
});

