import { createClient } from "https://esm.sh/@supabase/supabase-js@2.38.4";

export function createSupabaseClient(
  supabaseUrl: string,
  supabaseKey: string,
  authToken?: string
) {
  const client = createClient(supabaseUrl, supabaseKey, {
    global: {
      headers: authToken
        ? {
            Authorization: `Bearer ${authToken}`,
          }
        : {},
    },
  });

  return client;
}

export interface AdminUser {
  id: string;
  email: string;
  full_name: string;
  role: "admin" | "super_admin" | "support";
  is_active: boolean;
}

export async function verifyAdminAuth(
  supabaseUrl: string,
  supabaseKey: string,
  token: string
): Promise<AdminUser> {
  const client = createSupabaseClient(supabaseUrl, supabaseKey, token);

  // Verify user exists in auth
  const { data: { user }, error: authError } = await client.auth.getUser();

  if (authError || !user) {
    throw new Error("Unauthorized");
  }

  // Verify user is an admin
  const { data: adminUser, error: adminError } = await client
    .from("admin_users")
    .select("id, email, full_name, role, is_active")
    .eq("email", user.email)
    .eq("is_active", true)
    .single();

  if (adminError || !adminUser) {
    throw new Error("Admin access denied");
  }

  // Update last login
  await client
    .from("admin_users")
    .update({ last_login: new Date().toISOString() })
    .eq("id", adminUser.id);

  return adminUser as AdminUser;
}

export interface AdminActivityLog {
  admin_id: string;
  action: string;
  target_type?: string;
  target_id?: string;
  details?: Record<string, any>;
  ip_address?: string;
}

export async function logAdminActivity(
  supabase: any,
  activity: AdminActivityLog
): Promise<void> {
  try {
    await supabase.from("admin_activity_log").insert({
      admin_id: activity.admin_id,
      action: activity.action,
      target_type: activity.target_type || null,
      target_id: activity.target_id || null,
      details: activity.details || {},
      ip_address: activity.ip_address || null,
      created_at: new Date().toISOString(),
    });
  } catch (error) {
    console.error("Failed to log admin activity:", error);
    // Don't throw - logging errors shouldn't break the main action
  }
}

export async function getAppSetting(
  supabase: any,
  key: string
): Promise<any> {
  const { data, error } = await supabase
    .from("app_settings")
    .select("value")
    .eq("key", key)
    .single();

  if (error) {
    return null;
  }

  return data?.value;
}

export async function updateAppSetting(
  supabase: any,
  key: string,
  value: any,
  adminId: string
): Promise<void> {
  await supabase.from("app_settings").upsert(
    {
      key,
      value,
      updated_by: adminId,
      updated_at: new Date().toISOString(),
    },
    { onConflict: "key" }
  );
}

import React, { useEffect, useState } from 'react';
import { DataTable, StatusBadge } from '../components';
import { adminApi } from '../lib/supabase';
import type { AdminTransaction } from '../types';
import { AlertCircle, ArrowUpRight, ArrowDownLeft, Zap, CheckCircle } from 'lucide-react';
import { format } from 'date-fns';

export const Transactions: React.FC = () => {
  const [transactions, setTransactions] = useState<AdminTransaction[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [search, setSearch] = useState('');
  const [page, setPage] = useState(1);
  const [total, setTotal] = useState(0);
  const [type, setType] = useState('');
  const [status, setStatus] = useState('');
  const [method, setMethod] = useState('');

  const pageSize = 20;

  useEffect(() => {
    const fetchTransactions = async () => {
      try {
        setLoading(true);
        setError(null);

        const filters: any = {};
        if (type) filters.type = type;
        if (status) filters.status = status;
        if (method) filters.method = method;

        const result = await adminApi.getTransactions(page, pageSize, filters);

        if (result.success) {
          setTransactions(result.data);
          setTotal(result.pagination?.total || 0);
        } else {
          setError(result.error || 'Failed to fetch transactions');
        }
      } catch (err) {
        setError('An error occurred while fetching transactions');
        console.error(err);
      } finally {
        setLoading(false);
      }
    };

    fetchTransactions();
  }, [page, type, status, method]);

  const calculateStats = () => {
    const totalVolume = transactions.reduce((sum, t) => sum + t.amount, 0);
    const successCount = transactions.filter((t) => t.status === 'success').length;
    const failedCount = transactions.filter((t) => t.status === 'failed').length;
    const successRate =
      transactions.length > 0 ? ((successCount / transactions.length) * 100).toFixed(1) : '0';
    const avgAmount =
      transactions.length > 0 ? totalVolume / transactions.length : 0;

    return {
      totalVolume,
      successRate,
      avgAmount,
      failedCount,
    };
  };

  const stats = calculateStats();

  const getTypeIcon = (type: string) => {
    switch (type) {
      case 'contribution':
        return <ArrowDownLeft className="w-4 h-4 text-blue-400" />;
      case 'payment':
        return <ArrowUpRight className="w-4 h-4 text-emerald-400" />;
      case 'refund':
        return <ArrowDownLeft className="w-4 h-4 text-purple-400" />;
      case 'fee':
        return <Zap className="w-4 h-4 text-amber-400" />;
      default:
        return null;
    }
  };

  const columns = [
    {
      key: 'created_at' as const,
      label: 'Date',
      sortable: true,
      render: (value: string) => format(new Date(value), 'MMM dd, yyyy HH:mm'),
    },
    {
      key: 'user_id' as const,
      label: 'User',
      render: () => <span className="text-slate-400 text-sm">User ID</span>,
    },
    {
      key: 'type' as const,
      label: 'Type',
      render: (value: string) => (
        <div className="flex items-center gap-2">
          {getTypeIcon(value)}
          <span className="capitalize font-medium text-slate-200">{value}</span>
        </div>
      ),
    },
    {
      key: 'amount' as const,
      label: 'Amount',
      sortable: true,
      render: (value: number) => (
        <span className="font-semibold text-emerald-400">${value.toFixed(2)}</span>
      ),
    },
    {
      key: 'status' as const,
      label: 'Status',
      render: (value: string) => <StatusBadge status={value} />,
    },
    {
      key: 'method' as const,
      label: 'Method',
      render: (value: string) => (
        <span className="px-2 py-1 bg-slate-700 text-slate-200 rounded text-xs capitalize">
          {value}
        </span>
      ),
    },
  ];

  return (
    <div className="space-y-6">
      {/* Header */}
