import React, { useEffect, useState } from 'react';
import { DataTable, StatusBadge, Chart } from '../components';
import { adminApi } from '../lib/supabase';
import type { AdminSubscription, ChartDataPoint } from '../types';
import { AlertCircle, Users, DollarSign, TrendingDown, CreditCard } from 'lucide-react';
import { format } from 'date-fns';

export const Subscriptions: React.FC = () => {
  const [subscriptions, setSubscriptions] = useState<AdminSubscription[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [page, setPage] = useState(1);
  const [total, setTotal] = useState(0);
  const [revenueData, setRevenueData] = useState<ChartDataPoint[]>([]);
  const [planData, setPlanData] = useState<ChartDataPoint[]>([]);

  const pageSize = 20;

  useEffect(() => {
    const fetchSubscriptions = async () => {
      try {
        setLoading(true);
        setError(null);

        const result = await adminApi.getSubscriptions(page, pageSize);

        if (result.success) {
          setSubscriptions(result.data);
          setTotal(result.pagination?.total || 0);
        } else {
          setError(result.error || 'Failed to fetch subscriptions');
        }
      } catch (err) {
        setError('An error occurred while fetching subscriptions');
        console.error(err);
      } finally {
        setLoading(false);
      }
    };

    const fetchCharts = async () => {
      const [revenueRes, categoryRes] = await Promise.all([
        adminApi.getRevenueData(6),
        adminApi.getCategoryBreakdown(),
      ]);

      if (revenueRes.success) setRevenueData(revenueRes.data);
      if (categoryRes.success) setPlanData(categoryRes.data);
    };

    fetchSubscriptions();
    fetchCharts();
  }, [page]);

  const calculateStats = () => {
    const totalSubscribers = total;
    const monthlyRevenue = subscriptions.reduce((sum, s) => sum + s.amount, 0);
    const activeSubscribers = subscriptions.filter((s) => s.status === 'active').length;
    const cancelledCount = subscriptions.filter((s) => s.status === 'cancelled').length;
    const churnRate =
      totalSubscribers > 0 ? ((cancelledCount / totalSubscribers) * 100).toFixed(2) : '0';
    const trialConversions = subscriptions.filter((s) => s.billing_cycle === 'monthly').length;

    return {
      totalSubscribers,
      monthlyRevenue,
      activeSubscribers,
      churnRate,
      trialConversions,
    };
  };

  const stats = calculateStats();

  const columns = [
    {
      key: 'user_id' as const,
      label: 'User',
      render: () => <span className="text-slate-400 text-sm">User ID</span>,
    },
    {
      key: 'plan' as const,
      label: 'Plan',
      sortable: true,
      render: (value: string) => (
        <span className="px-2 py-1 bg-slate-700 text-slate-200 rounded text-xs capitalize font-semibold">
          {value}
        </span>
      ),
    },
    {
      key: 'status' as const,
      label: 'Status',
      render: (value: string) => <StatusBadge status={value} />,
    },
    {
      key: 'start_date' as const,
      label: 'Start Date',
      render: (value: string) => format(new Date(value), 'MMM dd, yyyy'),
    },
    {
      key: 'next_billing_date' as const,
      label: 'Next Billing',
      render: (value: string) => (
        <span className="text-slate-300">{format(new Date(value), 'MMM dd, yyyy')}</span>
      ),
    },
    {
      key: 'amount' as const,
      label: 'Amount',
      sortable: true,
      render: (value: number) => (
        <span className="font-semibold text-emerald-400">${value.toFixed(2)}</span>
      ),
    },
    {
      key: 'billing_cycle' as const,
      label: 'Cycle',
      render: (value: string) => (
        <span className="capitalize text-slate-300">{value}</span>
      ),
    },
  ];

  return (
    <div className="space-y-6">
      {/* Header */}
      <div>
        <h1 className="text-3xl font-bold text-slate-50">Subscriptions</h1>
        <p className="text-slate-400 mt-1">Subscription management and revenue analytics</p>
      </div>

      {/* Overview Stats */}
      <div className="grid grid-cols-1 md:grid-cols-4 gap-4">
        <div className="bg-slate-800 rounded-lg border border-slate-700 p-6">
          <div className="flex items-start justify-between">
            <div>
              <p className="text-slate-400 text-sm mb-2">Total Subscribers</p>
              <p className="text-2xl font-bold text-slate-50">{stats.totalSubscribers}</p>
              <p className="text-xs text-slate-500 mt-2">
                {stats.activeSubscribers} active
              </p>
            </div>
            <Users className="w-6 h-6 text-blue-400" />
          </div>
        </div>

        <div className="bg-slate-800 rounded-lg border border-slate-700 p-6">
          <div className="flex items-start justify-between">
            <div>
              <p className="text-slate-400 text-sm mb-2">Monthly Revenue</p>
              <p className="text-2xl font-bold text-emerald-400">
                ${stats.monthlyRevenue.toLocaleString('en-US', { maximumFractionDigits: 0 })}
              </p>
            </div>
            <DollarSign className="w-6 h-6 text-emerald-400" />
          </div>
        </div>

        <div className="bg-slate-800 rounded-lg border border-slate-700 p-6">
          <div className="flex items-start justify-between">
            <div>
              <p className="text-slate-400 text-sm mb-2">Churn Rate</p>
              <p className="text-2xl font-bold text-red-400">{stats.churnRate}%</p>
            </div>
            <TrendingDown className="w-6 h-6 text-red-400" />
          </div>
        </div>

        <div className="bg-slate-800 rounded-lg border border-slate-700 p-6">
          <div className="flex items-start justify-between">
            <div>
              <p className="text-slate-400 text-sm mb-2">Trial Conversions</p>
              <p className="text-2xl font-bold text-purple-400">{stats.trialConversions}</p>
            </div>
            <CreditCard className="w-6 h-6 text-purple-400" />
          </div>
        </div>
      </div>

      {/* Charts */}
      <div className="grid grid-cols-1 lg:grid-cols-2 gap-6">
        <Chart
          type="line"
          data={revenueData}
          title="Revenue Trend"
          dataKey="revenue"
          xAxisKey="month"
          color="#00D998"
          height={300}
        />

        <Chart
          type="pie"
          data={planData.slice(0, 4)}
          title="Plan Distribution"
          dataKey="count"
          height={300}
        />
      </div>

      {/* Filters */}
      <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
        <div>
          <label className="block text-sm font-medium text-slate-200 mb-2">
            Plan Type
          </label>
          <select
            className="w-full px-4 py-2 bg-slate-700 border border-slate-600 rounded-lg text-slate-50 focus:outline-none focus:ring-2 focus:ring-emerald-500"
          >
            <option>All Plans</option>
            <option>Basic</option>
            <option>Pro</option>
            <option>Enterprise</option>
          </select>
        </div>

        <div>
          <label className="block text-sm font-medium text-slate-200 mb-2">
            Status
          </label>
          <select
            className="w-full px-4 py-2 bg-slate-700 border border-slate-600 rounded-lg text-slate-50 focus:outline-none focus:ring-2 focus:ring-emerald-500"
          >
            <option>All Status</option>
            <option>Active</option>
            <option>Paused</option>
            <option>Cancelled</option>
          </select>
        </div>

        <div>
          <label className="block text-sm font-medium text-slate-200 mb-2">
            Billing Cycle
          </label>
          <select
            className="w-full px-4 py-2 bg-slate-700 border border-slate-600 rounded-lg text-slate-50 focus:outline-none focus:ring-2 focus:ring-emerald-500"
          >
            <option>All Cycles</option>
            <option>Monthly</option>
            <option>Annual</option>
          </select>
        </div>
      </div>

      {/* Error Alert */}
      {error && (
        <div className="bg-red-900 border border-red-700 rounded-lg p-4 flex gap-3">
          <AlertCircle className="w-5 h-5 text-red-400 flex-shrink-0 mt-0.5" />
          <p className="text-red-300">{error}</p>
        </div>
      )}

      {/* Data Table */}
      <DataTable
        columns={columns}
        data={subscriptions}
        loading={loading}
        pagination={{
          current: page,
          total: Math.ceil(total / pageSize),
          pageSize,
          onChange: setPage,
        }}
      />
    </div>
  );
};

