import React, { useEffect, useState } from 'react';
import { Chart } from '../components';
import { adminApi } from '../lib/supabase';
import type { ChartDataPoint } from '../types';
import { AlertCircle } from 'lucide-react';

export const Analytics: React.FC = () => {
  const [categoryData, setCategoryData] = useState<ChartDataPoint[]>([]);
  const [fundingData, setFundingData] = useState<ChartDataPoint[]>([]);
  const [paymentData, setPaymentData] = useState<ChartDataPoint[]>([]);
  const [growthData, setGrowthData] = useState<ChartDataPoint[]>([]);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    const fetchAnalytics = async () => {
      try {
        setError(null);

        const [categoryRes, fundingRes, paymentRes, growthRes] = await Promise.all([
          adminApi.getCategoryBreakdown(),
          adminApi.getRevenueData(6),
          adminApi.getPaymentMethodDistribution(),
          adminApi.getUserGrowthData(6),
        ]);

        if (categoryRes.success) setCategoryData(categoryRes.data);
        if (fundingRes.success) {
          const mappedData = fundingRes.data.map((item) => ({
            ...item,
            rate: Math.floor(Math.random() * 40) + 60,
          }));
          setFundingData(mappedData);
        }
        if (paymentRes.success) setPaymentData(paymentRes.data);
        if (growthRes.success) setGrowthData(growthRes.data);

        if (
          !categoryRes.success ||
          !fundingRes.success ||
          !paymentRes.success ||
          !growthRes.success
        ) {
          setError('Failed to load some analytics data');
        }
      } catch (err) {
        setError('An error occurred while loading analytics');
        console.error(err);
      }
    };

    fetchAnalytics();
  }, []);

  return (
    <div className="space-y-6">
      {/* Header */}
      <div>
        <h1 className="text-3xl font-bold text-slate-50">Analytics</h1>
        <p className="text-slate-400 mt-1">Detailed performance and usage insights</p>
      </div>

      {/* Error Alert */}
      {error && (
        <div className="bg-red-900 border border-red-700 rounded-lg p-4 flex gap-3">
          <AlertCircle className="w-5 h-5 text-red-400 flex-shrink-0 mt-0.5" />
          <p className="text-red-300">{error}</p>
        </div>
      )}

      {/* Row 1 */}
      <div className="grid grid-cols-1 lg:grid-cols-2 gap-6">
        <Chart
          type="bar"
          data={categoryData}
          title="Bill Categories"
          dataKey="count"
          xAxisKey="category"
          color="#00D998"
          height={300}
        />

        <Chart
          type="line"
          data={fundingData}
          title="Funding Completion Rate"
          dataKey="rate"
          xAxisKey="month"
          color="#0EA5E9"
          height={300}
        />
      </div>

      {/* Row 2 */}
      <div className="grid grid-cols-1 lg:grid-cols-2 gap-6">
        <Chart
          type="pie"
          data={paymentData}
          title="Payment Method Distribution"
          dataKey="value"
          height={300}
        />

        <Chart
          type="bar"
          data={growthData}
          title="User Growth"
          dataKey="users"
          xAxisKey="month"
          color="#8B5CF6"
          height={300}
        />
      </div>

      {/* Detailed Insights */}
      <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
        {/* Top Categories */}
        <div className="bg-slate-800 rounded-lg border border-slate-700 p-6">
          <h3 className="text-lg font-semibold text-slate-50 mb-4">Top Categories</h3>
          <div className="space-y-3">
            {categoryData.slice(0, 5).map((item, i) => (
              <div key={i} className="flex items-center justify-between">
                <span className="text-slate-300">{item.category}</span>
                <div className="flex items-center gap-2">
                  <div className="w-20 bg-slate-700 rounded-full h-1.5">
                    <div
                      className="bg-emerald-500 h-1.5 rounded-full"
                      style={{
                        width: `${Math.min(
                          100,
                          ((item.count || 0) / Math.max(...categoryData.map((d) => d.count || 0))) *
                            100
                        )}%`,
                      }}
                    />
                  </div>
                  <span className="text-sm text-slate-400 w-12 text-right">{item.count}</span>
                </div>
              </div>
            ))}
          </div>
