Keep the mock data as fallback when Supabase isn't configured (check if supabase client exists).

### 2. Update supabase.ts with proper client setup

Read the current file. If it's just a stub, replace it with a proper implementation:
```typescript
import { createClient } from '@supabase/supabase-js';
import * as SecureStore from 'expo-secure-store';
import 'react-native-url-polyfill/auto';

const supabaseUrl = process.env.EXPO_PUBLIC_SUPABASE_URL || '';
const supabaseAnonKey = process.env.EXPO_PUBLIC_SUPABASE_ANON_KEY || '';

// Custom storage adapter using expo-secure-store
const ExpoSecureStoreAdapter = {
  getItem: async (key: string) => {
    try { return await SecureStore.getItemAsync(key); } catch { return null; }
  },
  setItem: async (key: string, value: string) => {
    try { await SecureStore.setItemAsync(key, value); } catch {}
  },
  removeItem: async (key: string) => {
    try { await SecureStore.deleteItemAsync(key); } catch {}
  },
};

export const supabase = createClient(supabaseUrl, supabaseAnonKey, {
  auth: {
    storage: ExpoSecureStoreAdapter,
    autoRefreshToken: true,
    persistSession: true,
    detectSessionInUrl: false,
  },
});
```

### 3. Update database.ts to be comprehensive

Read the current file. Make sure ALL services have proper CRUD methods that actually work. Each method should:
- Call the correct Supabase table
- Handle errors properly
- Return `{ data, error }` pattern

Make sure these services exist and are complete:
- ProfileService: get, update, uploadAvatar
- BillService: getAll, getById, create, update, delete, getByCategory
- BucketService: getAll, getByBill, create, update, getCurrentBucket
- ContributionService: getAll, getByBill, create, getRecent
- TransferService: getAll, getByBill, create
- LinkedAccountService: getAll, create, delete, setPrimary
- NotificationService: getAll, getUnread, markRead, markAllRead, delete
- AchievementService: getAll, unlock

### 4. Create src/services/plaid.ts - Full Plaid integration

```typescript
import { supabase } from './supabase';

export const PlaidService = {
  // Get link token from edge function
  async createLinkToken() {
    const { data, error } = await supabase.functions.invoke('plaid-link-token');
    if (error) throw error;
    return data.link_token;
  },

  // Exchange public token for access token
  async exchangeToken(publicToken: string, metadata: any) {
    const { data, error } = await supabase.functions.invoke('plaid-exchange-token', {
      body: { public_token: publicToken, metadata },
    });
    if (error) throw error;
    return data;
  },

  // Fetch and analyze transactions for bill detection
  async detectBills(accountId: string) {
    const { data, error } = await supabase.functions.invoke('plaid-transactions', {
      body: { account_id: accountId },
    });
    if (error) throw error;
    return data.detected_bills;
  },
};
```

### 5. Create src/services/stripe.ts - Full Stripe integration

```typescript
import { supabase } from './supabase';

export const StripeService = {
  async createPaymentIntent(amount: number, billId: string, paymentMethodId?: string) {
    const { data, error } = await supabase.functions.invoke('create-payment', {
      body: { amount, bill_id: billId, payment_method_id: paymentMethodId },
    });
    if (error) throw error;
    return data;
  },

  async confirmPayment(paymentIntentId: string) {
    const { data, error } = await supabase.functions.invoke('confirm-payment', {
      body: { payment_intent_id: paymentIntentId },
    });
    if (error) throw error;
    return data;
  },

  async getPaymentMethods() {
    const { data, error } = await supabase.functions.invoke('payment-methods', {
      body: { action: 'list' },
    });
    if (error) throw error;
    return data.payment_methods;
  },

  async addPaymentMethod(token: string) {
    const { data, error } = await supabase.functions.invoke('payment-methods', {
      body: { action: 'attach', token },
    });
    if (error) throw error;
    return data;
  },

  async removePaymentMethod(id: string) {
    const { data, error } = await supabase.functions.invoke('payment-methods', {
      body: { action: 'detach', payment_method_id: id },
    });
    if (error) throw error;
    return data;
  },

  async createSubscription(priceId: string, paymentMethodId: string) {
    const { data, error } = await supabase.functions.invoke('create-subscription', {
      body: { price_id: priceId, payment_method_id: paymentMethodId },
    });
    if (error) throw error;
    return data;
  },

  async cancelSubscription(subscriptionId: string) {
    const { data, error } = await supabase.functions.invoke('create-subscription', {
      body: { action: 'cancel', subscription_id: subscriptionId },
    });
    if (error) throw error;
    return data;
  },
};
```

### 6. Create src/services/notifications.ts - Push notification service

```typescript
import * as Notifications from 'expo-notifications';
import * as Device from 'expo-device';
import { Platform } from 'react-native';
import { supabase } from './supabase';

Notifications.setNotificationHandler({
  handleNotification: async () => ({
    shouldShowAlert: true,
    shouldPlaySound: true,
    shouldSetBadge: true,
  }),
});

export const PushNotificationService = {
  async registerForPushNotifications() {
    if (!Device.isDevice) return null;

    const { status: existingStatus } = await Notifications.getPermissionsAsync();
    let finalStatus = existingStatus;

    if (existingStatus !== 'granted') {
      const { status } = await Notifications.requestPermissionsAsync();
      finalStatus = status;
    }

    if (finalStatus !== 'granted') return null;

    const token = await Notifications.getExpoPushTokenAsync();

    // Save token to user profile
    const { data: { user } } = await supabase.auth.getUser();
    if (user) {
      await supabase.from('profiles').update({ push_token: token.data }).eq('id', user.id);
    }

    if (Platform.OS === 'android') {
      Notifications.setNotificationChannelAsync('default', {
        name: 'default',
        importance: Notifications.AndroidImportance.MAX,
      });
    }

    return token.data;
  },

  async scheduleBillReminder(billName: string, dueDate: Date, amount: number) {
    await Notifications.scheduleNotificationAsync({
      content: {
        title: `${billName} Due Soon`,
        body: `Your ${billName} ($${amount}) is due on ${dueDate.toLocaleDateString()}`,
        data: { type: 'bill_reminder' },
      },
      trigger: { date: new Date(dueDate.getTime() - 3 * 24 * 60 * 60 * 1000) }, // 3 days before
    });
  },

  async scheduleContributionReminder() {
    await Notifications.scheduleNotificationAsync({
      content: {
        title: 'Daily Contribution Reminder',
        body: 'Time to contribute to your bills!',
        data: { type: 'contribution_reminder' },
      },
      trigger: { hour: 9, minute: 0, repeats: true },
    });
  },

  async cancelAllScheduled() {
    await Notifications.cancelAllScheduledNotificationsAsync();
  },
};
```

### 7. Update src/services/index.ts to export all services

Add exports for PlaidService, StripeService, PushNotificationService.

IMPORTANT: Read each file before modifying it. Use Edit tool for modifications, Write tool only for new files. Preserve all existing code that still works. The key goal is to make the mock data → real Supabase transition seamless with graceful fallbacks.

