import React, { useEffect, useState } from 'react';
import { BrowserRouter, Routes, Route, Navigate } from 'react-router-dom';
import { Layout } from './components';
import {
  Login,
  Dashboard,
  Users,
  UserDetail,
  Bills,
  Transactions,
  Subscriptions,
  Analytics,
  Settings,
} from './pages';
import { adminApi } from './lib/supabase';

export default function App() {
  const [isAuthenticated, setIsAuthenticated] = useState(false);
  const [loading, setLoading] = useState(true);
  const [adminName, setAdminName] = useState('Admin');

  useEffect(() => {
    const checkAuth = async () => {
      try {
        const loggedIn = localStorage.getItem('adminLoggedIn') === 'true';
        setIsAuthenticated(loggedIn);

        if (loggedIn) {
          const userRes = await adminApi.getCurrentAdmin();
          if (userRes.success && userRes.data) {
            setAdminName(
              (userRes.data as any).user_metadata?.full_name ||
                (userRes.data as any).email ||
                'Admin'
            );
          }
        }
      } catch (err) {
        console.error('Auth check failed:', err);
        setIsAuthenticated(false);
      } finally {
        setLoading(false);
      }
    };

    checkAuth();
  }, []);

  const handleLogout = async () => {
    try {
      await adminApi.logoutAdmin();
    } catch (err) {
      console.error('Logout error:', err);
    } finally {
      localStorage.removeItem('adminLoggedIn');
      setIsAuthenticated(false);
      setAdminName('Admin');
    }
  };

  if (loading) {
    return (
      <div className="min-h-screen bg-slate-900 flex items-center justify-center">
        <div className="flex flex-col items-center gap-4">
          <div className="w-12 h-12 bg-emerald-500 rounded-lg flex items-center justify-center animate-pulse">
            <span className="text-white font-bold text-xl">F</span>
          </div>
          <p className="text-slate-400">Loading admin panel...</p>
        </div>
      </div>
    );
  }

  return (
    <BrowserRouter>
      <Routes>
        {!isAuthenticated ? (
          <>
            <Route path="/login" element={<Login />} />
            <Route path="*" element={<Navigate to="/login" replace />} />
          </>
        ) : (
          <>
            <Route
              path="/"
              element={
                <Layout onLogout={handleLogout} adminName={adminName}>
                  <Dashboard />
                </Layout>
              }
            />
            <Route
              path="/users"
              element={
                <Layout onLogout={handleLogout} adminName={adminName}>
                  <Users />
                </Layout>
              }
            />
            <Route
              path="/users/:userId"
              element={
                <Layout onLogout={handleLogout} adminName={adminName}>
                  <UserDetail />
                </Layout>
              }
            />
            <Route
              path="/bills"
              element={
                <Layout onLogout={handleLogout} adminName={adminName}>
                  <Bills />
                </Layout>
              }
            />
            <Route
              path="/transactions"
              element={
                <Layout onLogout={handleLogout} adminName={adminName}>
                  <Transactions />
                </Layout>
              }
            />
            <Route
              path="/subscriptions"
              element={
                <Layout onLogout={handleLogout} adminName={adminName}>
                  <Subscriptions />
                </Layout>
              }
            />
            <Route
              path="/analytics"
              element={
                <Layout onLogout={handleLogout} adminName={adminName}>
                  <Analytics />
                </Layout>
              }
            />
            <Route
              path="/settings"
              element={
                <Layout onLogout={handleLogout} adminName={adminName}>
                  <Settings />
                </Layout>
              }
            />
            <Route path="*" element={<Navigate to="/" replace />} />
          </>
        )}
      </Routes>
    </BrowserRouter>
  );
}

# Admin Panel Integration Guide

## Overview

This guide explains how to integrate the admin panel into your Fractional Bill Pay application frontend.

## Architecture

```
Frontend (React/Next.js)
    ↓
Admin Panel UI
    ↓
Edge Functions (Deno)
    ↓
Supabase Database
```

## Setup Steps

### 1. Database Migration

First, apply the database migration to create admin tables:

```bash
cd fractional-app
supabase migration up
```

This creates:
- `admin_users` - Admin account management
- `admin_activity_log` - Audit trail
- `app_settings` - Configuration store
- `support_tickets` - Customer support system

### 2. Deploy Edge Functions

