```typescript
import { createContext, useContext, useState, useCallback } from 'react';
import { Session } from '@supabase/supabase-js';
import { adminService } from '@/lib/admin-service';

interface DashboardStats {
  totalUsers: number;
  activeBills: number;
  premiumUsers: number;
  totalVolume: string;
  monthlyRevenue: string;
  subscriptionRate: string;
}

interface AdminContextType {
  session: Session | null;
  isLoading: boolean;
  dashboardStats: DashboardStats | null;
  fetchDashboardStats: () => Promise<void>;
  disableUser: (userId: string, reason?: string) => Promise<void>;
}

const AdminContext = createContext<AdminContextType | undefined>(undefined);

export function AdminProvider({ children }: { children: React.ReactNode }) {
  const [session, setSession] = useState<Session | null>(null);
  const [isLoading, setIsLoading] = useState(false);
  const [dashboardStats, setDashboardStats] = useState<DashboardStats | null>(null);

  const fetchDashboardStats = useCallback(async () => {
    if (!session) return;

    setIsLoading(true);
    try {
      const stats = await adminService.getDashboardStats(session.access_token);
      setDashboardStats(stats);
    } catch (error) {
      console.error('Failed to fetch dashboard stats:', error);
    } finally {
      setIsLoading(false);
    }
  }, [session]);

  const disableUser = useCallback(
    async (userId: string, reason?: string) => {
      if (!session) return;

      const result = await adminService.disableUser(session.access_token, userId, reason);
      if (result.error) {
        throw new Error(result.error);
      }
      await fetchDashboardStats();
    },
    [session, fetchDashboardStats]
  );

  return (
    <AdminContext.Provider
      value={{
        session,
        isLoading,
        dashboardStats,
        fetchDashboardStats,
        disableUser,
      }}
    >
      {children}
    </AdminContext.Provider>
  );
}

export function useAdmin() {
  const context = useContext(AdminContext);
  if (!context) {
    throw new Error('useAdmin must be used within AdminProvider');
  }
  return context;
}
