## 2. Create Edge Function: supabase/functions/admin-dashboard/index.ts

This function returns all dashboard statistics for the admin panel. It uses the service role key for full database access.

```typescript
import { serve } from 'https://deno.land/std@0.177.0/http/server.ts';
import { createClient } from 'https://esm.sh/@supabase/supabase-js@2';

const corsHeaders = {
  'Access-Control-Allow-Origin': '*',
  'Access-Control-Allow-Headers': 'authorization, x-client-info, apikey, content-type',
};

serve(async (req) => {
  if (req.method === 'OPTIONS') return new Response('ok', { headers: corsHeaders });

  try {
    const supabase = createClient(
      Deno.env.get('SUPABASE_URL')!,
      Deno.env.get('SUPABASE_SERVICE_ROLE_KEY')!
    );

    // Verify admin auth
    const authHeader = req.headers.get('Authorization');
    if (!authHeader) throw new Error('Unauthorized');

    const { data: { user }, error: authError } = await supabase.auth.getUser(authHeader.replace('Bearer ', ''));
    if (authError || !user) throw new Error('Unauthorized');

    const url = new URL(req.url);
    const action = url.searchParams.get('action') || 'stats';

    switch (action) {
      case 'stats': {
        // Get total users
        const { count: totalUsers } = await supabase.from('profiles').select('*', { count: 'exact', head: true });

        // Get active bills
        const { count: activeBills } = await supabase.from('bills').select('*', { count: 'exact', head: true }).eq('is_active', true);

        // Get premium subscribers
        const { count: premiumUsers } = await supabase.from('subscriptions').select('*', { count: 'exact', head: true }).eq('status', 'active');

        // Get total transaction volume
        const { data: txns } = await supabase.from('transactions').select('amount').eq('status', 'completed');
        const totalVolume = txns?.reduce((sum: number, t: any) => sum + Number(t.amount), 0) || 0;

        // Get recent signups (last 30 days)
        const thirtyDaysAgo = new Date(Date.now() - 30 * 24 * 60 * 60 * 1000).toISOString();
        const { count: newUsers } = await supabase.from('profiles').select('*', { count: 'exact', head: true }).gte('created_at', thirtyDaysAgo);

        // Get bill category breakdown
        const { data: categoryData } = await supabase.from('bills').select('category').eq('is_active', true);
        const categories: Record<string, number> = {};
        categoryData?.forEach((b: any) => { categories[b.category] = (categories[b.category] || 0) + 1; });

        // Get monthly revenue (subscriptions)
        const monthlyRevenue = (premiumUsers || 0) * 7.99;

        return new Response(JSON.stringify({
          totalUsers: totalUsers || 0,
          activeBills: activeBills || 0,
          premiumUsers: premiumUsers || 0,
          totalVolume,
          newUsers: newUsers || 0,
          monthlyRevenue,
          categoryBreakdown: categories,
          subscriptionRate: totalUsers ? ((premiumUsers || 0) / totalUsers * 100).toFixed(1) : '0',
        }), { headers: { ...corsHeaders, 'Content-Type': 'application/json' } });
      }

      case 'users': {
        const page = parseInt(url.searchParams.get('page') || '1');
        const limit = parseInt(url.searchParams.get('limit') || '20');
        const search = url.searchParams.get('search') || '';
        const offset = (page - 1) * limit;

        let query = supabase.from('profiles').select('*, bills(count), subscriptions(status)', { count: 'exact' });
        if (search) query = query.or(`email.ilike.%${search}%,full_name.ilike.%${search}%`);

        const { data, count, error } = await query.range(offset, offset + limit - 1).order('created_at', { ascending: false });

        return new Response(JSON.stringify({ users: data, total: count }), { headers: { ...corsHeaders, 'Content-Type': 'application/json' } });
      }

      case 'transactions': {
        const page = parseInt(url.searchParams.get('page') || '1');
        const limit = parseInt(url.searchParams.get('limit') || '20');
        const offset = (page - 1) * limit;
        const status = url.searchParams.get('status');
        const type = url.searchParams.get('type');

        let query = supabase.from('transactions').select('*, profiles(email, full_name)', { count: 'exact' });
        if (status) query = query.eq('status', status);
        if (type) query = query.eq('type', type);

        const { data, count } = await query.range(offset, offset + limit - 1).order('created_at', { ascending: false });

        return new Response(JSON.stringify({ transactions: data, total: count }), { headers: { ...corsHeaders, 'Content-Type': 'application/json' } });
      }

      case 'revenue': {
        const months = parseInt(url.searchParams.get('months') || '6');
        const data = [];
        for (let i = months - 1; i >= 0; i--) {
          const date = new Date();
          date.setMonth(date.getMonth() - i);
          const monthStart = new Date(date.getFullYear(), date.getMonth(), 1).toISOString();
          const monthEnd = new Date(date.getFullYear(), date.getMonth() + 1, 0).toISOString();

          const { data: txns } = await supabase.from('transactions').select('amount').eq('status', 'completed').gte('created_at', monthStart).lte('created_at', monthEnd);
          const total = txns?.reduce((sum: number, t: any) => sum + Number(t.amount), 0) || 0;

          const { count: subs } = await supabase.from('subscriptions').select('*', { count: 'exact', head: true }).eq('status', 'active').lte('created_at', monthEnd);

          data.push({
            month: date.toLocaleString('default', { month: 'short' }),
            revenue: total,
            subscriptionRevenue: (subs || 0) * 7.99,
            transactions: txns?.length || 0,
          });
        }

        return new Response(JSON.stringify(data), { headers: { ...corsHeaders, 'Content-Type': 'application/json' } });
      }

      case 'user-growth': {
        const months = parseInt(url.searchParams.get('months') || '6');
        const data = [];
        for (let i = months - 1; i >= 0; i--) {
          const date = new Date();
          date.setMonth(date.getMonth() - i);
          const monthStart = new Date(date.getFullYear(), date.getMonth(), 1).toISOString();
          const monthEnd = new Date(date.getFullYear(), date.getMonth() + 1, 0).toISOString();

          const { count } = await supabase.from('profiles').select('*', { count: 'exact', head: true }).gte('created_at', monthStart).lte('created_at', monthEnd);

          data.push({
            month: date.toLocaleString('default', { month: 'short' }),
            newUsers: count || 0,
          });
        }

        return new Response(JSON.stringify(data), { headers: { ...corsHeaders, 'Content-Type': 'application/json' } });
      }

      default:
        return new Response(JSON.stringify({ error: 'Unknown action' }), { status: 400, headers: { ...corsHeaders, 'Content-Type': 'application/json' } });
    }
  } catch (error) {
    return new Response(JSON.stringify({ error: error.message }), { status: 401, headers: { ...corsHeaders, 'Content-Type': 'application/json' } });
  }
});
```

