          <View style={styles.planDivider} />
          <View style={styles.planFeatures}>
            {features.map((feature) => (
              <View key={feature.name} style={styles.planFeature}>
                <Text
                  style={[
                    styles.featureIcon,
                    { color: feature.premium ? colors.primary : colors.textMuted },
                  ]}
                >
                  {typeof feature.premium === 'boolean'
                    ? feature.premium
                      ? '✓'
                      : '✗'
