1	/**
2	 * Calculation utilities for Fractional Bill Pay
3	 */
4	
5	export function formatCurrency(amount: number): string {
6	  return '$' + amount.toFixed(2).replace(/\B(?=(\d{3})+(?!\d))/g, ',');
7	}
8	
9	export function formatCurrencyShort(amount: number): string {
10	  if (amount >= 1000) return '$' + (amount / 1000).toFixed(1) + 'k';
11	  return '$' + amount.toFixed(0);
12	}
13	
14	export function calculateDailyContribution(amount: number, daysRemaining: number): number {
15	  if (daysRemaining <= 0) return amount;
16	  return Math.ceil((amount / daysRemaining) * 100) / 100;
17	}
18	
19	export function calculateWeeklyContribution(amount: number, weeksRemaining: number): number {
20	  if (weeksRemaining <= 0) return amount;
21	  return Math.ceil((amount / weeksRemaining) * 100) / 100;
22	}
23	
24	export function calculateBiweeklyContribution(amount: number, periodsRemaining: number): number {
25	  if (periodsRemaining <= 0) return amount;
26	  return Math.ceil((amount / periodsRemaining) * 100) / 100;
27	}
28	
29	export function calculateProgress(current: number, target: number): number {
30	  if (target <= 0) return 0;
31	  return Math.min(Math.round((current / target) * 100), 100);
32	}
33	
34	export function getDaysUntilDue(dueDay: number): number {
35	  const today = new Date();
36	  const currentDay = today.getDate();
37	  if (dueDay >= currentDay) return dueDay - currentDay;
38	  const daysInMonth = new Date(today.getFullYear(), today.getMonth() + 1, 0).getDate();
39	  return daysInMonth - currentDay + dueDay;
40	}
41	
42	export function getBillStatus(progress: number, daysUntil: number): 'on_track' | 'behind' | 'completed' {
43	  if (progress >= 100) return 'completed';
44	  const expectedProgress = Math.max(0, 100 - (daysUntil / 30) * 100);
45	  return progress >= expectedProgress * 0.8 ? 'on_track' : 'behind';
46	}
47	
48	export function getNextDueDate(dueDay: number): string {
49	  const today = new Date();
50	  const currentDay = today.getDate();
51	
52	  if (dueDay >= currentDay) {
53	    return new Date(today.getFullYear(), today.getMonth(), dueDay).toISOString();
54	  }
55	
56	  const nextMonth = new Date(today.getFullYear(), today.getMonth() + 1, dueDay);
57	  return nextMonth.toISOString();
58	}
59	
60	export function formatDate(dateString: string): string {
61	  const date = new Date(dateString);
62	  return date.toLocaleDateString('en-US', { month: 'short', day: 'numeric', year: 'numeric' });
63	}
64	
65	export function getFundedPercent(current: number, target: number): number {
66	  if (target <= 0) return 0;
67	  return Math.min(Math.round((current / target) * 100), 100);
68	}
