47	    try {
48	      const { data, error } = await supabase.functions.invoke('payment-methods', {
49	        body: { action: 'list' },
50	      });
51	
52	      if (error) throw error;
53	      return data.paymentMethods || [];
54	    } catch (err) {
55	      console.error('Failed to get payment methods:', err);
56	      return [];
57	    }
58	  },
