64	    provider: PaymentProvider,
65	    token: string
66	  ): Promise<PaymentResult> {
67	    try {
68	      const { data, error } = await supabase.functions.invoke('payment-methods', {
69	        body: {
70	          action: 'add',
71	          provider,
72	          token,
73	        },
74	      });
75	
76	      if (error) throw error;
77	      return {
78	        success: true,
79	        transactionId: data.paymentMethodId,
80	      };
81	    } catch (err: any) {
82	      return {
83	        success: false,
84	        error: err.message || 'Failed to add payment method',
85	      };
86	    }
