15	    const { user } = await verifyAuth(SUPABASE_URL, SUPABASE_ANON_KEY, req);
16	    const { paymentIntentId } = await req.json();
17	
18	    if (!paymentIntentId) {
19	      return new Response(
20	        JSON.stringify({ error: "Missing paymentIntentId" }),
21	        {
22	          status: 400,
23	          headers: { ...corsHeaders, "Content-Type": "application/json" },
24	        }
