// ── Transaction Fee Calculation ────────────────────────────────────────────

export const TRANSACTION_FEE_RATE = 0.015; // 1.5%

export function calculateFee(amount: number): number {
  return Math.round(amount * TRANSACTION_FEE_RATE * 100) / 100;
}

export function calculateNetAmount(amount: number): number {
  return Math.round((amount - calculateFee(amount)) * 100) / 100;
}

export function calculateGrossFromNet(netAmount: number): number {
  return Math.round((netAmount / (1 - TRANSACTION_FEE_RATE)) * 100) / 100;
}

export function formatFeeBreakdown(amount: number): { gross: number; fee: number; net: number } {
  const fee = calculateFee(amount);
  return { gross: amount, fee, net: amount - fee };
}

