-- Migration: Switch from subscription model to 1.5% transaction fee model

-- Add fee tracking columns to transactions
ALTER TABLE public.transactions ADD COLUMN IF NOT EXISTS fee_amount NUMERIC(10,2) DEFAULT 0;
ALTER TABLE public.transactions ADD COLUMN IF NOT EXISTS fee_rate NUMERIC(5,4) DEFAULT 0.0150;
ALTER TABLE public.transactions ADD COLUMN IF NOT EXISTS net_amount NUMERIC(10,2);

-- Add fee columns to funding entries
ALTER TABLE public.funding_entries ADD COLUMN IF NOT EXISTS fee_amount NUMERIC(10,2) DEFAULT 0;
ALTER TABLE public.funding_entries ADD COLUMN IF NOT EXISTS net_amount NUMERIC(10,2);

-- Remove premium-related columns from profiles (make them nullable/optional first)
ALTER TABLE public.profiles ALTER COLUMN is_premium SET DEFAULT FALSE;

-- Update app settings
UPDATE public.app_settings SET value = '0.015' WHERE key = 'transaction_fee_rate';
DELETE FROM public.app_settings WHERE key = 'max_free_bills';
INSERT INTO public.app_settings (key, value) VALUES ('fee_model', '"transaction_percentage"') ON CONFLICT (key) DO UPDATE SET value = '"transaction_percentage"';

-- Update subscriptions table to track fee revenue instead
ALTER TABLE public.subscriptions ALTER COLUMN plan SET DEFAULT 'standard';
-- Remove plan check constraint and add new one
ALTER TABLE public.subscriptions DROP CONSTRAINT IF EXISTS subscriptions_plan_check;
ALTER TABLE public.subscriptions ADD CONSTRAINT subscriptions_plan_check CHECK (plan IN ('standard'));

-- Create fee revenue tracking view
CREATE OR REPLACE VIEW public.fee_revenue AS
SELECT
  date_trunc('month', created_at) as month,
  SUM(fee_amount) as total_fees,
  SUM(amount) as total_volume,
  COUNT(*) as transaction_count,
  AVG(fee_rate) as avg_fee_rate
FROM public.transactions
WHERE status = 'completed' AND fee_amount > 0
GROUP BY date_trunc('month', created_at)
ORDER BY month DESC;

