1	import { createClient } from '@supabase/supabase-js';
2	import type { AdminUser, AdminBill, AdminTransaction, AdminSubscription, DashboardStats, ChartDataPoint, Activity, ApiResponse } from '../types';
3	
4	const supabaseUrl = import.meta.env.VITE_SUPABASE_URL || '';
5	const supabaseServiceKey = import.meta.env.VITE_SUPABASE_SERVICE_KEY || '';
6	
7	export const supabase = createClient(supabaseUrl, supabaseServiceKey);
8	
9	// Helper function to handle API responses
10	function handleResponse<T>(data: T, error: any): ApiResponse<T> {
11	  if (error) {
12	    console.error('Supabase error:', error);
13	    return {
14	      data: data as T,
15	      error: error.message,
16	      success: false,
17	    };
18	  }
19	  return {
20	    data,
21	    success: true,
22	  };
23	}
24	
25	export const adminApi = {
26	  // AUTH
27	  async loginAdmin(email: string, password: string) {
28	    try {
29	      const { data, error } = await supabase.auth.signInWithPassword({
30	        email,
31	        password,
32	      });
33	      return handleResponse(data, error);
34	    } catch (error) {
35	      return { data: null, error: 'Login failed', success: false };
36	    }
37	  },
38	
39	  async logoutAdmin() {
40	    try {
41	      const { error } = await supabase.auth.signOut();
42	      return handleResponse(null, error);
43	    } catch (error) {
44	      return { data: null, error: 'Logout failed', success: false };
45	    }
46	  },
47	
48	  async getCurrentAdmin() {
49	    try {
50	      const { data: { user }, error } = await supabase.auth.getUser();
51	      return handleResponse(user, error);
52	    } catch (error) {
53	      return { data: null, error: 'Failed to get current user', success: false };
54	    }
55	  },
56	
57	  // USERS
58	  async getUsers(page: number = 1, limit: number = 20, search?: string) {
59	    try {
60	      let query = supabase.from('users').select('*');
61	
62	      if (search) {
63	        query = query.or(`email.ilike.%${search}%,full_name.ilike.%${search}%`);
64	      }
65	
66	      const { data, error, count } = await query
67	        .order('created_at', { ascending: false })
68	        .range((page - 1) * limit, page * limit - 1);
69	
70	      const response: ApiResponse<AdminUser[]> = {
71	        data: data as AdminUser[],
72	        pagination: {
73	          page,
74	          limit,
75	          total: count || 0,
76	          total_pages: Math.ceil((count || 0) / limit),
77	        },
78	        success: !error,
79	        error: error?.message,
80	      };
81	      return response;
82	    } catch (error) {
83	      return { data: [], pagination: { page, limit, total: 0, total_pages: 0 }, error: 'Failed to fetch users', success: false };
84	    }
85	  },
86	
87	  async getUserById(id: string) {
88	    try {
89	      const { data, error } = await supabase
90	        .from('users')
91	        .select('*')
92	        .eq('id', id)
93	        .single();
94	
95	      return handleResponse(data, error);
96	    } catch (error) {
97	      return { data: null, error: 'Failed to fetch user', success: false };
98	    }
