409	  private convertToCSV(data: any[]) {
410	    if (!data || data.length === 0) return '';
411	
412	    const headers = Object.keys(data[0]);
413	    const csv = [
414	      headers.join(','),
415	      ...data.map(row =>
416	        headers.map(header => {
417	          const value = row[header];
418	          if (typeof value === 'string' && value.includes(',')) {
419	            return `"${value}"`;
420	          }
421	          return value;
422	        }).join(',')
423	      ),
424	    ].join('\n');
425	
426	    return csv;
