import React, { useEffect, useState } from 'react';
import { DataTable, StatusBadge, Chart } from '../components';
import { adminApi } from '../lib/supabase';
import type { AdminSubscription, ChartDataPoint } from '../types';
import { AlertCircle, Users, DollarSign, TrendingDown, CreditCard } from 'lucide-react';
import { format } from 'date-fns';

export const Subscriptions: React.FC = () => {
  const [subscriptions, setSubscriptions] = useState<AdminSubscription[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [page, setPage] = useState(1);
  const [total, setTotal] = useState(0);
  const [revenueData, setRevenueData] = useState<ChartDataPoint[]>([]);
  const [planData, setPlanData] = useState<ChartDataPoint[]>([]);

  const pageSize = 20;

  useEffect(() => {
    const fetchSubscriptions = async () => {
      try {
        setLoading(true);
        setError(null);

        const result = await adminApi.getSubscriptions(page, pageSize);

        if (result.success) {
          setSubscriptions(result.data);
          setTotal(result.pagination?.total || 0);
        } else {
          setError(result.error || 'Failed to fetch subscriptions');
        }
      } catch (err) {
        setError('An error occurred while fetching subscriptions');
        console.error(err);
      } finally {
        setLoading(false);
      }
    };

    const fetchCharts = async () => {
      const [revenueRes, categoryRes] = await Promise.all([
        adminApi.getRevenueData(6),
        adminApi.getCategoryBreakdown(),
      ]);

      if (revenueRes.success) setRevenueData(revenueRes.data);
      if (categoryRes.success) setPlanData(categoryRes.data);
    };

    fetchSubscriptions();
    fetchCharts();
  }, [page]);

  const calculateStats = () => {
    const totalSubscribers = total;
    const monthlyRevenue = subscriptions.reduce((sum, s) => sum + s.amount, 0);
    const activeSubscribers = subscriptions.filter((s) => s.status === 'active').length;
    const cancelledCount = subscriptions.filter((s) => s.status === 'cancelled').length;
    const churnRate =
      totalSubscribers > 0 ? ((cancelledCount / totalSubscribers) * 100).toFixed(2) : '0';
    const trialConversions = subscriptions.filter((s) => s.billing_cycle === 'monthly').length;

    return {
      totalSubscribers,
      monthlyRevenue,
      activeSubscribers,
      churnRate,
      trialConversions,
    };
  };

  const stats = calculateStats();

  const columns = [
    {
      key: 'user_id' as const,
      label: 'User',
      render: () => <span className="text-slate-400 text-sm">User ID</span>,
    },
    {
      key: 'plan' as const,
      label: 'Plan',
      sortable: true,
      render: (value: string) => (
        <span className="px-2 py-1 bg-slate-700 text-slate-200 rounded text-xs capitalize font-semibold">
          {value}
        </span>
