          <div className="flex items-start justify-between">
            <div>
              <p className="text-slate-400 text-sm mb-2">Trial Conversions</p>
              <p className="text-2xl font-bold text-purple-400">{stats.trialConversions}</p>
            </div>
            <CreditCard className="w-6 h-6 text-purple-400" />
          </div>
        </div>
      </div>

      {/* Charts */}
      <div className="grid grid-cols-1 lg:grid-cols-2 gap-6">
        <Chart
          type="line"
