import React, { useEffect, useState } from 'react';
import { DataTable, StatusBadge, Chart } from '../components';
import { adminApi } from '../lib/supabase';
import type { AdminTransaction, ChartDataPoint } from '../types';
import { AlertCircle, TrendingUp, DollarSign, Activity, BarChart3 } from 'lucide-react';
import { format } from 'date-fns';

export const Revenue: React.FC = () => {
  const [transactions, setTransactions] = useState<AdminTransaction[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [page, setPage] = useState(1);
  const [total, setTotal] = useState(0);
  const [revenueData, setRevenueData] = useState<ChartDataPoint[]>([]);
  const [volumeData, setVolumeData] = useState<ChartDataPoint[]>([]);

  const pageSize = 20;

  useEffect(() => {
    const fetchTransactions = async () => {
      try {
        setLoading(true);
        setError(null);

        const result = await adminApi.getTransactions(page, pageSize, { type: 'fee' });

        if (result.success) {
          setTransactions(result.data);
          setTotal(result.pagination?.total || 0);
        } else {
          setError(result.error || 'Failed to fetch transactions');
        }
      } catch (err) {
        setError('An error occurred while fetching transactions');
        console.error(err);
      } finally {
        setLoading(false);
      }
    };

    const fetchCharts = async () => {
      const [revenueRes, growthRes] = await Promise.all([
        adminApi.getRevenueData(6),
        adminApi.getUserGrowthData(6),
      ]);

      if (revenueRes.success) setRevenueData(revenueRes.data);
      if (growthRes.success) setVolumeData(growthRes.data);
    };

    fetchTransactions();
    fetchCharts();
  }, [page]);

  const calculateStats = () => {
    const totalFeeRevenue = transactions.reduce((sum, t) => sum + t.amount, 0);
    const successfulTransactions = transactions.filter((t) => t.status === 'success').length;
    const avgFeePerTransaction = successfulTransactions > 0 ? totalFeeRevenue / successfulTransactions : 0;
    const transactionVolume = total;

    return {
      totalFeeRevenue,
      avgFeePerTransaction,
      transactionVolume,
      feeRate: 1.5,
    };
  };

  const stats = calculateStats();

  const columns = [
    {
      key: 'user_id' as const,
      label: 'User',
      render: (value: string) => <span className="text-slate-400 text-sm">{value}</span>,
    },
    {
      key: 'created_at' as const,
      label: 'Date',
      sortable: true,
      render: (value: string) => format(new Date(value), 'MMM dd, yyyy HH:mm'),
    },
    {
      key: 'type' as const,
      label: 'Type',
      render: (value: string) => (
        <span className="px-2 py-1 bg-slate-700 text-slate-200 rounded text-xs capitalize font-semibold">
          {value}
        </span>
      ),
    },
    {
      key: 'amount' as const,
      label: 'Amount',
      sortable: true,
      render: (value: number) => (
        <span className="font-semibold text-emerald-400">${value.toFixed(2)}</span>
      ),
    },
    {
      key: 'method' as const,
      label: 'Method',
      render: (value: string) => (
        <span className="capitalize text-slate-300">{value}</span>
      ),
    },
    {
      key: 'status' as const,
      label: 'Status',
      render: (value: string) => <StatusBadge status={value} />,
    },
  ];

  return (
    <div className="space-y-6">
      {/* Header */}
      <div>
        <h1 className="text-3xl font-bold text-slate-50">Revenue</h1>
        <p className="text-slate-400 mt-1">Fee-based revenue analytics and transaction tracking</p>
      </div>

      {/* KPI Cards */}
      <div className="grid grid-cols-1 md:grid-cols-4 gap-4">
        <div className="bg-slate-800 rounded-lg border border-slate-700 p-6">
          <div className="flex items-start justify-between">
            <div>
              <p className="text-slate-400 text-sm mb-2">Total Fee Revenue</p>
              <p className="text-2xl font-bold text-emerald-400">
                ${stats.totalFeeRevenue.toLocaleString('en-US', { maximumFractionDigits: 2 })}
              </p>
            </div>
            <DollarSign className="w-6 h-6 text-emerald-400" />
          </div>
        </div>

        <div className="bg-slate-800 rounded-lg border border-slate-700 p-6">
          <div className="flex items-start justify-between">
            <div>
              <p className="text-slate-400 text-sm mb-2">Avg Fee/Transaction</p>
              <p className="text-2xl font-bold text-blue-400">
                ${stats.avgFeePerTransaction.toFixed(2)}
              </p>
            </div>
            <TrendingUp className="w-6 h-6 text-blue-400" />
          </div>
        </div>

        <div className="bg-slate-800 rounded-lg border border-slate-700 p-6">
          <div className="flex items-start justify-between">
            <div>
              <p className="text-slate-400 text-sm mb-2">Transaction Volume</p>
              <p className="text-2xl font-bold text-purple-400">
                {stats.transactionVolume.toLocaleString()}
              </p>
            </div>
            <Activity className="w-6 h-6 text-purple-400" />
          </div>
        </div>

        <div className="bg-slate-800 rounded-lg border border-slate-700 p-6">
          <div className="flex items-start justify-between">
            <div>
              <p className="text-slate-400 text-sm mb-2">Fee Rate</p>
              <p className="text-2xl font-bold text-teal-400">{stats.feeRate}%</p>
            </div>
            <BarChart3 className="w-6 h-6 text-teal-400" />
          </div>
        </div>
      </div>

      {/* Charts */}
      <div className="grid grid-cols-1 lg:grid-cols-2 gap-6">
        <Chart
          type="line"
          data={revenueData}
          title="Fee Revenue Trend"
          dataKey="revenue"
          xAxisKey="month"
          color="#00D998"
          height={300}
        />

        <Chart
          type="bar"
          data={volumeData}
          title="Transaction Volume"
          dataKey="users"
          xAxisKey="month"
          color="#0EA5E9"
          height={300}
        />
      </div>

      {/* Error Alert */}
      {error && (
        <div className="bg-red-900 border border-red-700 rounded-lg p-4 flex gap-3">
          <AlertCircle className="w-5 h-5 text-red-400 flex-shrink-0 mt-0.5" />
          <p className="text-red-300">{error}</p>
        </div>
      )}

      {/* Data Table */}
      <div>
        <h3 className="text-lg font-semibold text-slate-50 mb-4">Recent Fee Transactions</h3>
        <DataTable
          columns={columns}
          data={transactions}
          loading={loading}
          pagination={{
            current: page,
            total: Math.ceil(total / pageSize),
            pageSize,
            onChange: setPage,
          }}
        />
      </div>
    </div>
  );
};

