// SUBSCRIPTIONS
async getSubscriptions(page: number = 1, limit: number = 20) {
  try {
    const { data, error, count } = await supabase
      .from('subscriptions')
      .select('*')
      .order('created_at', { ascending: false })
      .range((page - 1) * limit, page * limit - 1);

    const response: ApiResponse<AdminSubscription[]> = {
      data: data as AdminSubscription[],
      pagination: {
        page,
        limit,
        total: count || 0,
        total_pages: Math.ceil((count || 0) / limit),
      },
      success: !error,
      error: error?.message,
    };
    return response;
  } catch (error) {
    return { data: [], pagination: { page, limit, total: 0, total_pages: 0 }, error: 'Failed to fetch subscriptions', success: false };
  }
},

